#define ROUNDUP_POW2(M, N) (((M) + (N) - 1) & ~((N) - 1))
#define CEIL_DIV(M, N) (((M) / (N)) + (((M) % (N)) != 0))
static bool fIsPow2(uint32_t pX) { return pX > 1 && (pX & (pX - 1)) == 0; }

