#define VK_CHECK(err, msg)                                                                                             \
  do {                                                                                                                 \
    vk::Result err_ = (err);                                                                                           \
    if (err_ != vk::Result::eSuccess) {                                                                                \
      fprintf(stderr, "ggml_vulkan: %s error %s at %s:%d\n", #err, to_string(err_).c_str(), __FILE__, __LINE__);       \
      exit(1);                                                                                                         \
    }                                                                                                                  \
  } while (0)

