struct vk_command_buffer {
  vk::CommandBuffer vBuf;
  uint64_t vUseCounter = 0;
  bool in_use = false;
};

// Stores command pool/buffers. There's an instance of this
// for each (context,queue) pair and for each (device,queue) pair.
struct vk_command_pool {
  void mInit(vk_device &pDevice, vk_queue *pQ);
  void mDestroy(vk::Device &pDevice);

  vk::CommandPool vPool;
  // Using deque so the pointers to command buffers
  // remain valid even if we add more
  std::deque<vk_command_buffer> lCmdBuffers;

  vk_queue *q;

  size_t mBuffersInUse() const {
    return std::count_if(lCmdBuffers.begin(), lCmdBuffers.end(), [](const auto &pCb) { return pCb.in_use; });
  }
};

// Prevent simultaneous submissions to the same queue.
struct vk_queue_handle {
  vk::Queue vQueue;
  virtual void mSubmit(vk::ArrayProxy<const vk::SubmitInfo> pSubmits, vk::Fence pFence) = 0;
  virtual void lock() {} // no-op by default (internally synchronized case)
  virtual void unlock() {}
  virtual ~vk_queue_handle() = default;
};

struct vk_queue_handle_synchronized : vk_queue_handle {
  std::mutex mutex;
  void mSubmit(vk::ArrayProxy<const vk::SubmitInfo> pSubmits, vk::Fence pFence) override {
    std::lock_guard<std::mutex> vGuard(mutex);
    vQueue.submit(pSubmits, pFence);
  }
  void lock() override { mutex.lock(); }
  void unlock() override { mutex.unlock(); }
};

struct vk_queue_handle_unsynchronized : vk_queue_handle {
  void mSubmit(vk::ArrayProxy<const vk::SubmitInfo> pSubmits, vk::Fence pFence) override {
    // Driver guarantees internal synchronization via VK_KHR_internally_synchronized_queues
    vQueue.submit(pSubmits, pFence);
  }
  // lock()/unlock() inherited no-ops
};

struct vk_queue {
  uint32_t vQueueFamilyIndex;
  std::shared_ptr<vk_queue_handle> vHandle;

  vk_command_pool vCmdPool;

  vk::PipelineStageFlags vStageFlags;

  bool vTransferOnly;
};

