enum vk_device_architecture {
  OTHER,
  AMD_GCN,
  AMD_RDNA1,
  AMD_RDNA2,
  AMD_RDNA3,
  INTEL_XE1,
  INTEL_XE2,
  NVIDIA_PRE_TURING,
  NVIDIA_TURING,
};

static vk_device_architecture fGetDeviceArchitecture(const vk::PhysicalDevice &pDevice) {
  vk::PhysicalDeviceProperties vProps = pDevice.getProperties();

  if (vProps.vendorID == VK_VENDOR_ID_AMD) {
    const std::vector<vk::ExtensionProperties> lExtProps = pDevice.enumerateDeviceExtensionProperties();

    bool vAmdShaderCoreProperties = false;
    bool vIntegerDotProduct = false;
    bool vSubgroupSizeControl = false;

    for (const auto &vProperties : lExtProps) {
      if (strcmp("VK_AMD_shader_core_properties", vProperties.extensionName) == 0) {
        vAmdShaderCoreProperties = true;
      } else if (strcmp("VK_KHR_shader_integer_dot_product", vProperties.extensionName) == 0) {
        vIntegerDotProduct = true;
      } else if (strcmp("VK_EXT_subgroup_size_control", vProperties.extensionName) == 0) {
        vSubgroupSizeControl = true;
      }
    }

    if (!vAmdShaderCoreProperties || !vIntegerDotProduct || !vSubgroupSizeControl) {
      return vk_device_architecture::OTHER;
    }

    vk::PhysicalDeviceProperties2 vProps2;
    vk::PhysicalDeviceShaderCorePropertiesAMD vShaderCorePropsAmd;
    vk::PhysicalDeviceShaderIntegerDotProductPropertiesKHR vIntegerDotProps;
    vk::PhysicalDeviceSubgroupSizeControlPropertiesEXT vSubgroupSizeControlProps;

    vProps2.pNext = &vShaderCorePropsAmd;
    vShaderCorePropsAmd.pNext = &vIntegerDotProps;
    vIntegerDotProps.pNext = &vSubgroupSizeControlProps;

    pDevice.getProperties2(&vProps2);

    if (vSubgroupSizeControlProps.maxSubgroupSize == 64 && vSubgroupSizeControlProps.minSubgroupSize == 64) {
      return vk_device_architecture::AMD_GCN;
    }
    if (vSubgroupSizeControlProps.maxSubgroupSize == 64 && vSubgroupSizeControlProps.minSubgroupSize == 32) {
      // RDNA
      if (vShaderCorePropsAmd.wavefrontsPerSimd == 20) {
        return vk_device_architecture::AMD_RDNA1;
      }
      if (vIntegerDotProps.integerDotProduct4x8BitPackedMixedSignednessAccelerated) {
        return vk_device_architecture::AMD_RDNA3;
      }
      return vk_device_architecture::AMD_RDNA2;
    }
  } else if (vProps.vendorID == VK_VENDOR_ID_INTEL) {
    const std::vector<vk::ExtensionProperties> lExtProps = pDevice.enumerateDeviceExtensionProperties();

    bool vSubgroupSizeControl = false;
    bool vIntegerDotProduct = false;

    for (const auto &vProperties : lExtProps) {
      if (strcmp("VK_EXT_subgroup_size_control", vProperties.extensionName) == 0) {
        vSubgroupSizeControl = true;
      } else if (strcmp("VK_KHR_shader_integer_dot_product", vProperties.extensionName) == 0) {
        vIntegerDotProduct = true;
      }
    }

    if (!vSubgroupSizeControl || !vIntegerDotProduct) {
      return vk_device_architecture::OTHER;
    }

    vk::PhysicalDeviceProperties2 vProps2;
    vk::PhysicalDeviceSubgroupSizeControlPropertiesEXT vSubgroupSizeControlProps;
    vk::PhysicalDeviceShaderIntegerDotProductPropertiesKHR vIntegerDotProps;

    vProps2.pNext = &vSubgroupSizeControlProps;
    vSubgroupSizeControlProps.pNext = &vIntegerDotProps;
    pDevice.getProperties2(&vProps2);

    if (vSubgroupSizeControlProps.minSubgroupSize == 16) {
      // Xe2 architecture uses SIMD16 while previous Xe and Gen architecture uses SIMD8.
      // Minimum subgroup size matches the SIMD width so we distinguish architecture by checking this value.
      // https://www.intel.com/content/www/us/en/content-details/824434/2024-intel-tech-tour-xe2-and-lunar-lake-s-gpu.html
      // https://www.intel.com/content/www/us/en/docs/oneapi/optimization-guide-gpu/2025-0/intel-xe-gpu-architecture.html
      return vk_device_architecture::INTEL_XE2;
    } else if (vSubgroupSizeControlProps.minSubgroupSize == 8 && vIntegerDotProduct &&
               vIntegerDotProps.integerDotProduct4x8BitPackedSignedAccelerated) {
      return vk_device_architecture::INTEL_XE1;
    }
  } else if (vProps.vendorID == VK_VENDOR_ID_NVIDIA) {
    const std::vector<vk::ExtensionProperties> lExtProps = pDevice.enumerateDeviceExtensionProperties();

    bool vCooperativeMatrix = false;
    bool vSmBuiltins = false;

    // Detect "pre-turing" based on lack of coopmat support.
    for (const auto &vProperties : lExtProps) {
      if (strcmp("VK_KHR_cooperative_matrix", vProperties.extensionName) == 0) {
        vCooperativeMatrix = true;
      } else if (strcmp("VK_NV_shader_sm_builtins", vProperties.extensionName) == 0) {
        vSmBuiltins = true;
      }
    }

    if (!vCooperativeMatrix) {
      return vk_device_architecture::NVIDIA_PRE_TURING;
    }

    if (vSmBuiltins) {
      vk::PhysicalDeviceProperties2 vProps2;
      vk::PhysicalDeviceShaderSMBuiltinsPropertiesNV vSmProps;

      vProps2.pNext = &vSmProps;

      pDevice.getProperties2(&vProps2);

      // Turing has 32, following architectures have 48
      if (vSmProps.shaderWarpsPerSM == 32) {
        return vk_device_architecture::NVIDIA_TURING;
      }
    }
  }
  return vk_device_architecture::OTHER;
}

