enum FaCodePath {
  FA_SCALAR,
  FA_COOPMAT1,
  FA_COOPMAT2,
};

struct vk_fa_pipeline_state {
  uint32_t vHsk, vHsv;
  uint32_t vBr, vBc;
  uint32_t D_split, vRowSplit;
  bool vShmemStaging;
  FaCodePath vPath;
  uint32_t vWorkgroupSize, vSubgroupSize;
  bool aligned;
  bool f32acc;
  uint32_t flags;
  uint32_t vLimitOccupancyShmem;
  ggml_type k_type;
  ggml_type v_type;

  bool operator<(const vk_fa_pipeline_state &pB) const {
    return std::tie(vHsk, vHsv, vBr, vBc, D_split, vRowSplit, vShmemStaging, vPath, vWorkgroupSize, vSubgroupSize,
                    aligned, f32acc, flags, vLimitOccupancyShmem, k_type,
                    v_type) < std::tie(pB.vHsk, pB.vHsv, pB.vBr, pB.vBc, pB.D_split, pB.vRowSplit, pB.vShmemStaging,
                                       pB.vPath, pB.vWorkgroupSize, pB.vSubgroupSize, pB.aligned, pB.f32acc, pB.flags,
                                       pB.vLimitOccupancyShmem, pB.k_type, pB.v_type);
  }
};

struct vk_conv2d_pipeline_state {
  vk_conv2d_pipeline_state(uint32_t pS0, uint32_t pS1, uint32_t p0, uint32_t p1, uint32_t pD0, uint32_t pD1,
                           uint32_t pKw, uint32_t pKh, uint32_t pAligned)
      : s0(pS0), s1(pS1), p0(p0), p1(p1), d0(pD0), d1(pD1), KW(pKw), KH(pKh), aligned(pAligned) {}

  uint32_t s0, s1, p0, p1, d0, d1, KW, KH;
  // when set, shader can skip K/CRS/NPQ bounds checks and address clamps
  uint32_t aligned;

  bool operator<(const vk_conv2d_pipeline_state &pB) const {
    return std::tie(s0, s1, p0, p1, d0, d1, KW, KH, aligned) <
           std::tie(pB.s0, pB.s1, pB.p0, pB.p1, pB.d0, pB.d1, pB.KW, pB.KH, pB.aligned);
  }
};

struct vk_conv3d_pipeline_state {
  vk_conv3d_pipeline_state(uint32_t pS0, uint32_t pS1, uint32_t pS2, uint32_t p0, uint32_t p1, uint32_t p2,
                           uint32_t pD0, uint32_t pD1, uint32_t pD2, uint32_t pKw, uint32_t pKh, uint32_t pKd,
                           uint32_t pAligned)
      : s0(pS0), s1(pS1), s2(pS2), p0(p0), p1(p1), p2(p2), d0(pD0), d1(pD1), d2(pD2), KW(pKw), KH(pKh), KD(pKd),
        aligned(pAligned) {}

  uint32_t s0, s1, s2, p0, p1, p2, d0, d1, d2, KW, KH, KD;
  uint32_t aligned;

  bool operator<(const vk_conv3d_pipeline_state &pB) const {
    return std::tie(s0, s1, s2, p0, p1, p2, d0, d1, d2, KW, KH, KD, aligned) <
           std::tie(pB.s0, pB.s1, pB.s2, pB.p0, pB.p1, pB.p2, pB.d0, pB.d1, pB.d2, pB.KW, pB.KH, pB.KD, pB.aligned);
  }
};

struct vk_solve_tri_pipeline_state {
  vk_solve_tri_pipeline_state(uint32_t pN, uint32_t pK) : N(pN), K(pK) {}

  uint32_t N, K;

  bool operator<(const vk_solve_tri_pipeline_state &pB) const { return std::tie(N, K) < std::tie(pB.N, pB.K); }
};

