static vk_op_pad_push_constants fVkOpPadPushConstantsInit(const ggml_tensor *pSrc0, const ggml_tensor *pDst) {
  int64_t vNe = ggml_nelements(pDst);
  GGML_ASSERT(vNe <= (int64_t)std::numeric_limits<uint32_t>::max());

  vk_op_pad_push_constants vP{};
  vP.ne = (uint32_t)vNe;

  size_t vSrc0Tsize = ggml_type_size(pSrc0->type);
  vP.vNe00 = (uint32_t)pSrc0->ne[0];
  vP.vNe01 = (uint32_t)pSrc0->ne[1];
  vP.ne02 = (uint32_t)pSrc0->ne[2];
  vP.vNe03 = (uint32_t)pSrc0->ne[3];
  vP.vNb00 = (uint32_t)(pSrc0->nb[0] / vSrc0Tsize);
  vP.vNb01 = (uint32_t)(pSrc0->nb[1] / vSrc0Tsize);
  vP.vNb02 = (uint32_t)(pSrc0->nb[2] / vSrc0Tsize);
  vP.vNb03 = (uint32_t)(pSrc0->nb[3] / vSrc0Tsize);

  size_t vDstTsize = ggml_type_size(pDst->type);
  vP.ne10 = (uint32_t)pDst->ne[0];
  vP.ne11 = (uint32_t)pDst->ne[1];
  vP.ne12 = (uint32_t)pDst->ne[2];
  vP.vNe13 = (uint32_t)pDst->ne[3];
  vP.nb10 = (uint32_t)(pDst->nb[0] / vDstTsize);
  vP.nb11 = (uint32_t)(pDst->nb[1] / vDstTsize);
  vP.nb12 = (uint32_t)(pDst->nb[2] / vDstTsize);
  vP.nb13 = (uint32_t)(pDst->nb[3] / vDstTsize);

  vP.vLp0 = pDst->op_params[0];
  vP.vRp0 = pDst->op_params[1];
  vP.vLp1 = pDst->op_params[2];
  vP.vRp1 = pDst->op_params[3];
  vP.vLp2 = pDst->op_params[4];
  vP.vRp2 = pDst->op_params[5];
  vP.vLp3 = pDst->op_params[6];
  vP.vRp3 = pDst->op_params[7];
  vP.vCircular = pDst->op_params[8];

  return vP; // fastdiv values and offsets are initialized later in ggml_vk_op
}

// See https://gmplib.org/~tege/divcnst-pldi94.pdf figure 4.1.
// Precompute mp (m' in the paper) and L such that division
// can be computed using a multiply (high 32b of 64b result)
// and a shift:
//
// n/d = (mulhi(n, mp) + n) >> L;
static void fInitFastdivValues(uint32_t pD, uint32_t &pMp, uint32_t &pL) {
  // compute L = ceil(log2(d));
  pL = 0;
  while (pL < 32 && (uint32_t{1} << pL) < pD) {
    pL++;
  }

  pMp = (uint32_t)((uint64_t{1} << 32) * ((uint64_t{1} << pL) - pD) / pD + 1);
}

static uint32_t fPackFastdivL(uint32_t pL0, uint32_t pL1, uint32_t pL2) { return pL0 | (pL1 << 8) | (pL2 << 16); }

template <typename T> void init_pushconst_fastdiv(T &p_) {
  GGML_UNUSED(p_);
  static_assert(!std::is_const<T>::value, "unexpected type");
}

template <> void init_pushconst_fastdiv(vk_op_unary_push_constants &p_) {
  // Compute magic values to divide by these six numbers.
  uint32_t vNe0012L;
  uint32_t vNe001L;
  uint32_t vNe00L;
  uint32_t vNe1012L;
  uint32_t vNe101L;
  uint32_t vNe10L;

  fInitFastdivValues(p_.ne02 * p_.vNe01 * p_.vNe00, p_.vNe0012mp, vNe0012L);
  fInitFastdivValues(p_.vNe01 * p_.vNe00, p_.vNe001mp, vNe001L);
  fInitFastdivValues(p_.vNe00, p_.vNe00mp, vNe00L);
  fInitFastdivValues(p_.ne12 * p_.ne11 * p_.ne10, p_.vNe1012mp, vNe1012L);
  fInitFastdivValues(p_.ne11 * p_.ne10, p_.vNe101mp, vNe101L);
  fInitFastdivValues(p_.ne10, p_.vNe10mp, vNe10L);

  p_.vNe0Ls = fPackFastdivL(vNe0012L, vNe001L, vNe00L);
  p_.vNe1Ls = fPackFastdivL(vNe1012L, vNe101L, vNe10L);
}

template <> void init_pushconst_fastdiv(vk_op_glu_push_constants &p_) {
  // GLU linearizes over dst, then uses dst coordinates for src0/src1.
  fInitFastdivValues(p_.vNe22 * p_.vNe21 * p_.vNe20, p_.vNe2012mp, p_.vNe2012L);
  fInitFastdivValues(p_.vNe21 * p_.vNe20, p_.vNe201mp, p_.vNe201L);
  fInitFastdivValues(p_.vNe20, p_.vNe20mp, p_.vNe20L);
}

