// Allow pre-recording command buffers
struct vk_staging_memcpy {
  vk_staging_memcpy(void *pDst, const void *pSrc, size_t pN) : dst(pDst), src(pSrc), n(pN) {}

  void *dst;
  const void *src;
  size_t n;
};

struct vk_staging_memset {
  vk_staging_memset(void *pDst, uint32_t pVal, size_t pN) : dst(pDst), val(pVal), n(pN) {}

  void *dst;
  uint32_t val;
  size_t n;
};

struct vk_context_struct {
  vk_submission *s;
  std::vector<vk_sequence> vSeqs;

  int vExitTensorIdx;

  std::vector<vk_staging_memcpy> lInMemcpys;
  std::vector<vk_staging_memcpy> lOutMemcpys;
  std::vector<vk_staging_memset> lMemsets;

  vk_command_pool *p{};

  // Times ggml_vk_submit has sent the recorded sequences, so the staging ring can tell whether a copy recorded in
  // this context has reached the queue yet.
  uint64_t vSubmitCount{};
};
typedef std::shared_ptr<vk_context_struct> vk_context;
typedef std::weak_ptr<vk_context_struct> vk_context_ref;

// Part of the staging ring of a backend that a queued device copy still reads (see fVkStagingWrite).
struct vk_staging_region {
  size_t vBegin;
  uint64_t vValue;            // value of the staging semaphore signaled once the copy has been done
  vk_context_ref vContext;    // context in which the copy was recorded
  uint64_t vEpoch;            // vSubmitCount of that context when the copy was recorded
  vk_command_buffer *vBuffer; // command buffer of the copy, reusable once the copy has been done
  uint64_t vBufferUse;        // use_counter of that command buffer when the copy was recorded
};

struct ggml_vk_garbage_collector {
  std::vector<vk_semaphore> lTlSemaphores;
  std::vector<vk_semaphore> lSemaphores;
  std::vector<vk::Event> lEvents;
  std::vector<vk_context> lContexts;
};

