      // Selects dot2 SPIR-V variant at runtime when device->dot2_f16 is true
#define CREATE_MM(TYPE, PIPELINE_NAME, NAMELC, F16ACC, WG_DENOMS, WARPTILE, PUSHCONST, PARAMCOUNT, ID,                 \
                  REQSUBGROUPSIZE)                                                                                     \
  if (device->mul_mat##ID##_l[TYPE])                                                                                   \
    ggml_vk_create_pipeline(device, device->PIPELINE_NAME->l, #NAMELC #F16ACC "_l",                                    \
                            (device->dot2_f16 ? NAMELC##_dot2##F16ACC##_len : NAMELC##F16ACC##_len),                   \
                            (device->dot2_f16 ? NAMELC##_dot2##F16ACC##_data : NAMELC##F16ACC##_data), "main",         \
                            PARAMCOUNT, sizeof(PUSHCONST), l_##WG_DENOMS, ggml_vk_mul_mm_spec(l_##WARPTILE, false), 1, \
                            false, REQSUBGROUPSIZE > 0, REQSUBGROUPSIZE);                                              \
  if (device->mul_mat##ID##_m[TYPE])                                                                                   \
    ggml_vk_create_pipeline(device, device->PIPELINE_NAME->m, #NAMELC #F16ACC "_m",                                    \
                            (device->dot2_f16 ? NAMELC##_dot2##F16ACC##_len : NAMELC##F16ACC##_len),                   \
                            (device->dot2_f16 ? NAMELC##_dot2##F16ACC##_data : NAMELC##F16ACC##_data), "main",         \
                            PARAMCOUNT, sizeof(PUSHCONST), m_##WG_DENOMS, ggml_vk_mul_mm_spec(m_##WARPTILE, false), 1, \
                            false, REQSUBGROUPSIZE > 0, REQSUBGROUPSIZE);                                              \
  if (device->mul_mat##ID##_s[TYPE])                                                                                   \
    ggml_vk_create_pipeline(device, device->PIPELINE_NAME->s, #NAMELC #F16ACC "_s",                                    \
                            (device->dot2_f16 ? NAMELC##_dot2##F16ACC##_len : NAMELC##F16ACC##_len),                   \
                            (device->dot2_f16 ? NAMELC##_dot2##F16ACC##_data : NAMELC##F16ACC##_data), "main",         \
                            PARAMCOUNT, sizeof(PUSHCONST), s_##WG_DENOMS, ggml_vk_mul_mm_spec(s_##WARPTILE, false), 1, \
                            false, REQSUBGROUPSIZE > 0, REQSUBGROUPSIZE);                                              \
  if (device->mul_mat##ID##_l[TYPE])                                                                                   \
    ggml_vk_create_pipeline(device, device->PIPELINE_NAME->a_l, #NAMELC #F16ACC "_aligned_l",                          \
                            (device->dot2_f16 ? NAMELC##_dot2##F16ACC##_len : NAMELC##F16ACC##_len),                   \
                            (device->dot2_f16 ? NAMELC##_dot2##F16ACC##_data : NAMELC##F16ACC##_data), "main",         \
                            PARAMCOUNT, sizeof(PUSHCONST), l_##WG_DENOMS, ggml_vk_mul_mm_spec(l_##WARPTILE, true),     \
                            l_align, false, REQSUBGROUPSIZE > 0, REQSUBGROUPSIZE);                                     \
  if (device->mul_mat##ID##_m[TYPE])                                                                                   \
    ggml_vk_create_pipeline(device, device->PIPELINE_NAME->a_m, #NAMELC #F16ACC "_aligned_m",                          \
                            (device->dot2_f16 ? NAMELC##_dot2##F16ACC##_len : NAMELC##F16ACC##_len),                   \
                            (device->dot2_f16 ? NAMELC##_dot2##F16ACC##_data : NAMELC##F16ACC##_data), "main",         \
                            PARAMCOUNT, sizeof(PUSHCONST), m_##WG_DENOMS, ggml_vk_mul_mm_spec(m_##WARPTILE, true),     \
                            m_align, false, REQSUBGROUPSIZE > 0, REQSUBGROUPSIZE);                                     \
  if (device->mul_mat##ID##_s[TYPE])                                                                                   \
    ggml_vk_create_pipeline(device, device->PIPELINE_NAME->a_s, #NAMELC #F16ACC "_aligned_s",                          \
                            (device->dot2_f16 ? NAMELC##_dot2##F16ACC##_len : NAMELC##F16ACC##_len),                   \
                            (device->dot2_f16 ? NAMELC##_dot2##F16ACC##_data : NAMELC##F16ACC##_data), "main",         \
                            PARAMCOUNT, sizeof(PUSHCONST), s_##WG_DENOMS, ggml_vk_mul_mm_spec(s_##WARPTILE, true),     \
                            s_align, false, REQSUBGROUPSIZE > 0, REQSUBGROUPSIZE);

      // bf16 scalar path promotes to f32, no dot2 variant
