static void fGgmlVkAdd1(ggml_backend_vk_context *pCtx, vk_context &pSubctx, const ggml_tensor *pSrc0,
                        const ggml_tensor *pSrc1, ggml_tensor *pDst) {
  const uint32_t cSrc0TypeSize = ggml_type_size(pSrc0->type);
  const uint32_t cSrc1TypeSize = ggml_type_size(pSrc1->type);
  const uint32_t cDstTypeSize = ggml_type_size(pDst->type);

  fGgmlVkOpF32<vk_op_binary_push_constants>(pCtx, pSubctx, pSrc0, pSrc1, nullptr, nullptr, pDst, GGML_OP_ADD1,
                                            {
                                                (uint32_t)ggml_nelements(pSrc0),
                                                (uint32_t)pSrc0->ne[0],
                                                (uint32_t)pSrc0->ne[1],
                                                (uint32_t)pSrc0->ne[2],
                                                (uint32_t)pSrc0->ne[3],
                                                (uint32_t)pSrc0->nb[0] / cSrc0TypeSize,
                                                (uint32_t)pSrc0->nb[1] / cSrc0TypeSize,
                                                (uint32_t)pSrc0->nb[2] / cSrc0TypeSize,
                                                (uint32_t)pSrc0->nb[3] / cSrc0TypeSize,
                                                (uint32_t)pSrc1->ne[0],
                                                (uint32_t)pSrc1->ne[1],
                                                (uint32_t)pSrc1->ne[2],
                                                (uint32_t)pSrc1->ne[3],
                                                (uint32_t)pSrc1->nb[0] / cSrc1TypeSize,
                                                (uint32_t)pSrc1->nb[1] / cSrc1TypeSize,
                                                (uint32_t)pSrc1->nb[2] / cSrc1TypeSize,
                                                (uint32_t)pSrc1->nb[3] / cSrc1TypeSize,
                                                (uint32_t)pDst->ne[0],
                                                (uint32_t)pDst->ne[1],
                                                (uint32_t)pDst->ne[2],
                                                (uint32_t)pDst->ne[3],
                                                (uint32_t)pDst->nb[0] / cDstTypeSize,
                                                (uint32_t)pDst->nb[1] / cDstTypeSize,
                                                (uint32_t)pDst->nb[2] / cDstTypeSize,
                                                (uint32_t)pDst->nb[3] / cDstTypeSize,
                                                0,
                                                0.0f,
                                                0.0f,
                                                0,
                                            });
}

static void fGgmlVkArange(ggml_backend_vk_context *pCtx, vk_context &pSubctx, ggml_tensor *dst) {
  VK_LOG_DEBUG("ggml_vk_arange(dst=" << dst << ", ne=" << ggml_nelements(dst) << ")");

  vk_op_push_constants vPc = {
      (uint32_t)ggml_nelements(dst), 1, ggml_get_op_params_f32(dst, 0), ggml_get_op_params_f32(dst, 2), 0.0f, 0.0f,
  };

  vk_pipeline vPipeline = fGgmlVkOpGetPipeline(pCtx, nullptr, nullptr, nullptr, dst, GGML_OP_ARANGE);
  GGML_ASSERT(vPipeline != nullptr);

  fGgmlPipelineRequestDescriptorSets(pCtx, vPipeline, 1);
  vk_subbuffer vDstBuf = fGgmlVkTensorSubbuffer(pCtx, dst, false);

  std::array<uint32_t, 3> vElements = {(uint32_t)ggml_nelements(dst), 1, 1};

  fGgmlVkDispatchPipeline(pCtx, pSubctx, vPipeline, {vDstBuf}, vPc, vElements);
}

static void fGgmlVkFill(ggml_backend_vk_context *pCtx, vk_context &pSubctx, ggml_tensor *dst) {
  VK_LOG_DEBUG("ggml_vk_fill(dst=" << dst << ", ne=" << ggml_nelements(dst) << ")");

  vk_op_push_constants vPc = {
      (uint32_t)ggml_nelements(dst), 1, ggml_get_op_params_f32(dst, 0), 0.0f, 0.0f, 0.0f,
  };

  vk_pipeline vPipeline = fGgmlVkOpGetPipeline(pCtx, nullptr, nullptr, nullptr, dst, GGML_OP_FILL);
  GGML_ASSERT(vPipeline != nullptr);

  fGgmlPipelineRequestDescriptorSets(pCtx, vPipeline, 1);
  vk_subbuffer vDstBuf = fGgmlVkTensorSubbuffer(pCtx, dst, false);

  std::array<uint32_t, 3> vElements = {(uint32_t)ggml_nelements(dst), 1, 1};

  fGgmlVkDispatchPipeline(pCtx, pSubctx, vPipeline, {vDstBuf}, vPc, vElements);
}

