static void fGgmlVkRoll(ggml_backend_vk_context *pCtx, vk_context &pSubctx, const ggml_tensor *pSrc0,
                        ggml_tensor *pDst) {
  const int32_t cS0 = ggml_get_op_params_i32(pDst, 0);
  const int32_t cS1 = ggml_get_op_params_i32(pDst, 1);
  const int32_t cS2 = ggml_get_op_params_i32(pDst, 2);
  const int32_t cS3 = ggml_get_op_params_i32(pDst, 3);
  const uint32_t cS01Packed = ((cS0 + 0x8000) << 16) | (cS1 + 0x8000);
  const uint32_t cS23Packed = ((cS2 + 0x8000) << 16) | (cS3 + 0x8000);

  vk_op_unary_push_constants vP = fVkOpUnaryPushConstantsInit(pSrc0, pDst);
  memcpy(&vP.vParam1, &cS01Packed, sizeof(float));
  memcpy(&vP.vParam2, &cS23Packed, sizeof(float));

  fGgmlVkOpF32(pCtx, pSubctx, pSrc0, nullptr, nullptr, nullptr, pDst, GGML_OP_ROLL, std::move(vP));
}

