static void fGgmlVkCpy(ggml_backend_vk_context *pCtx, vk_context &pSubctx, const ggml_tensor *pSrc0,
                       ggml_tensor *pDst) {
  uint32_t vNe = (uint32_t)ggml_nelements(pSrc0);
  if (ggml_is_quantized(pSrc0->type) && ggml_is_quantized(pDst->type)) {
    // Convert from number of logical elements to 2- or 4-byte units.
    vNe /= ggml_blck_size(pSrc0->type);
    if ((ggml_type_size(pSrc0->type) % 4) == 0) {
      vNe *= ggml_type_size(pSrc0->type) / 4;
    } else {
      vNe *= ggml_type_size(pSrc0->type) / 2;
    }
  }

  vk_op_unary_push_constants vP = fVkOpUnaryPushConstantsInit(pSrc0, pDst, vNe);
  fGgmlVkOpF32(pCtx, pSubctx, pSrc0, nullptr, nullptr, nullptr, pDst, GGML_OP_CPY, std::move(vP));
}

static void fGgmlVkSetRows(ggml_backend_vk_context *pCtx, vk_context &pSubctx, const ggml_tensor *pSrc0,
                           const ggml_tensor *pSrc1, ggml_tensor *pDst) {
  const uint32_t cSrc0TypeSize = ggml_type_size(pSrc0->type);
  const uint32_t cSrc1TypeSize = ggml_type_size(pSrc1->type);
  const uint32_t cDstTypeSize = ggml_type_size(pDst->type);

  // Skip empty skip_rows operations. For most ops the empty check at the start
  // of ggml_vk_build_graph is sufficient, but set_rows can have a nonempty dst
  // with empty srcs.
  if (ggml_is_empty(pSrc0) || ggml_is_empty(pSrc1)) {
    return;
  }

  fGgmlVkOpF32<vk_op_binary_push_constants>(pCtx, pSubctx, pSrc0, pSrc1, nullptr, nullptr, pDst, GGML_OP_SET_ROWS,
                                            {
                                                (uint32_t)ggml_nelements(pSrc0),
                                                (uint32_t)pSrc0->ne[0],
                                                (uint32_t)pSrc0->ne[1],
                                                (uint32_t)pSrc0->ne[2],
                                                (uint32_t)pSrc0->ne[3],
                                                (uint32_t)pSrc0->nb[0] / cSrc0TypeSize,
                                                (uint32_t)pSrc0->nb[1] / cSrc0TypeSize,
                                                (uint32_t)pSrc0->nb[2] / cSrc0TypeSize,
                                                (uint32_t)pSrc0->nb[3] / cSrc0TypeSize,
                                                (uint32_t)pSrc1->ne[0],
                                                (uint32_t)pSrc1->ne[1],
                                                (uint32_t)pSrc1->ne[2],
                                                (uint32_t)pSrc1->ne[3],
                                                (uint32_t)pSrc1->nb[0] / cSrc1TypeSize,
                                                (uint32_t)pSrc1->nb[1] / cSrc1TypeSize,
                                                (uint32_t)pSrc1->nb[2] / cSrc1TypeSize,
                                                (uint32_t)pSrc1->nb[3] / cSrc1TypeSize,
                                                (uint32_t)pDst->ne[0],
                                                (uint32_t)pDst->ne[1],
                                                (uint32_t)pDst->ne[2],
                                                (uint32_t)pDst->ne[3],
                                                (uint32_t)pDst->nb[0] / cDstTypeSize,
                                                (uint32_t)pDst->nb[1] / cDstTypeSize,
                                                (uint32_t)pDst->nb[2] / cDstTypeSize,
                                                (uint32_t)pDst->nb[3] / cDstTypeSize,
                                                0,
                                                0.0f,
                                                0.0f,
                                                0,
                                            });
}

