static void ggml_vk_test_dequant_matmul(ggml_backend_vk_context *ctx, size_t m, size_t n, size_t k, size_t batch,
                                        size_t num_it, size_t split_k, size_t shader_size, ggml_type quant,
                                        bool mmq = false) {
  VK_LOG_DEBUG("ggml_vk_test_dequant_matmul(" << m << ", " << n << ", " << k << ", " << batch << ", " << num_it << ", "
                                              << split_k << ", " << ggml_type_name(quant) << ")");
  const size_t x_ne = m * k * batch;
  const size_t y_ne = k * n * batch;
  const size_t d_ne = m * n * batch;

  vk_matmul_pipeline2 *pipelines;

  if (mmq) {
    pipelines = ctx->device->vPipelineDequantMulMatMatQ81;
  } else {
    pipelines = ctx->device->pipeline_dequant_mul_mat_mat;
  }

  const bool fp16acc = ctx->device->vFp16;

  vk_pipeline p;
  std::string shname;
  if (shader_size == 0) {
    p = fp16acc ? pipelines[quant].vF16acc->a_s : pipelines[quant].f32acc->a_s;
    shname = std::string(ggml_type_name(quant)) + "_ALIGNED_S";
  } else if (shader_size == 1) {
    p = fp16acc ? pipelines[quant].vF16acc->a_m : pipelines[quant].f32acc->a_m;
    shname = std::string(ggml_type_name(quant)) + "_ALIGNED_M";
  } else if (shader_size == 2) {
    p = fp16acc ? pipelines[quant].vF16acc->a_l : pipelines[quant].f32acc->a_l;
    shname = std::string(ggml_type_name(quant)) + "_ALIGNED_L";
  } else {
    GGML_ASSERT(0);
  }

  const size_t kpad = mmq ? 0 : fGgmlVkAlignSize(k, p->align);

  if (mmq || k != kpad) {
    if (shader_size == 0) {
      p = fp16acc ? pipelines[quant].vF16acc->s : pipelines[quant].f32acc->s;
      shname = std::string(ggml_type_name(quant)) + "_S";
    } else if (shader_size == 1) {
      p = fp16acc ? pipelines[quant].vF16acc->m : pipelines[quant].f32acc->m;
      shname = std::string(ggml_type_name(quant)) + "_M";
    } else if (shader_size == 2) {
      p = fp16acc ? pipelines[quant].vF16acc->l : pipelines[quant].f32acc->l;
      shname = std::string(ggml_type_name(quant)) + "_L";
    } else {
      GGML_ASSERT(0);
    }
  }

  if (p == nullptr) {
    std::cerr << "error: no pipeline for ggml_vk_test_dequant_matmul " << ggml_type_name(quant) << std::endl;
    return;
  }

  const size_t x_sz = sizeof(float) * x_ne;
  const size_t y_sz = sizeof(float) * y_ne;
  const size_t qx_sz = x_ne * ggml_type_size(quant) / ggml_blck_size(quant);
  const size_t qy_sz = mmq ? y_ne * ggml_type_size(GGML_TYPE_Q8_1) / ggml_blck_size(GGML_TYPE_Q8_1) : y_sz;
  const size_t d_sz = sizeof(float) * d_ne;
  float *x = (float *)malloc(x_sz);
  float *y = (float *)malloc(y_sz);
  void *qx = malloc(qx_sz);
  vk_buffer qx_buf = fGgmlVkCreateBufferCheck(ctx->device, qx_sz, {vk::MemoryPropertyFlagBits::eDeviceLocal});
  vk_buffer y_buf = fGgmlVkCreateBufferCheck(ctx->device, y_sz, {vk::MemoryPropertyFlagBits::eDeviceLocal});
  vk_buffer qy_buf = fGgmlVkCreateBufferCheck(ctx->device, qy_sz, {vk::MemoryPropertyFlagBits::eDeviceLocal});
  vk_buffer d_buf = fGgmlVkCreateBufferCheck(ctx->device, d_sz, {vk::MemoryPropertyFlagBits::eDeviceLocal});
  float *d = (float *)malloc(d_sz);
  float *d_chk = (float *)malloc(d_sz);

  for (size_t i = 0; i < x_ne; i++) {
    x[i] = (rand() / (float)RAND_MAX) * 2.0f - 1.0f;
    // x[i] = (i % k == i / k) ? 1.0f : 0.0f;
    // x[i] = i % k;
  }

  ggml_vk_quantize_data(x, qx, x_ne, quant);

  for (size_t i = 0; i < y_ne; i++) {
    y[i] = (rand() / (float)RAND_MAX) * 2.0f - 1.0f;
    // y[i] = (i % k == i / k) ? 1.0f : 0.0f;
    // y[i] = i % k;
  }

  if (split_k > 1) {
    fGgmlPipelineRequestDescriptorSets(ctx, ctx->device->vPipelineMatmulSplitKReduce, num_it);

    if (ctx->vPreallocSplitK == nullptr || ctx->vPreallocSplitK->size < sizeof(float) * d_ne * split_k) {
      // Resize buffer
      if (ctx->vPreallocSplitK != nullptr) {
        fGgmlVkDestroyBuffer(ctx->vPreallocSplitK);
      }
      ctx->vPreallocSplitK = fGgmlVkCreateBufferCheck(ctx->device, sizeof(float) * d_ne * split_k,
                                                      {vk::MemoryPropertyFlagBits::eDeviceLocal});
    }
  }
  if (mmq) {
    vk_pipeline pipeline_quantize_q8_1 = fGgmlVkGetQuantizePipeline(ctx, GGML_TYPE_Q8_1);
    fGgmlPipelineRequestDescriptorSets(ctx, pipeline_quantize_q8_1, num_it);
  }

  fGgmlPipelineAllocateDescriptorSets(ctx);

  fGgmlVkBufferWrite(qx_buf, 0, qx, qx_sz);
  fGgmlVkBufferWrite(y_buf, 0, y, y_sz);

  vk_context subctx = fGgmlVkCreateContext(ctx, ctx->vComputeCmdPool);
  fGgmlVkCtxBegin(ctx->device, subctx);
  if (mmq) {
    for (size_t i = 0; i < num_it; i++) {
      fGgmlVkQuantizeQ81(ctx, subctx, {y_buf, 0, y_sz}, {qy_buf, 0, qy_sz}, y_ne);
      fGgmlVkMatmul(ctx, subctx, p, {qx_buf, 0, qx_sz}, {qy_buf, 0, qy_sz}, {d_buf, 0, d_sz},
                    {ctx->vPreallocSplitK, 0, ctx->vPreallocSizeSplitK}, m, n, k, k, k, m, k * m, k * n, m * n, split_k,
                    batch, batch, batch, 1, 1, n);
    }
  } else {
    for (size_t i = 0; i < num_it; i++) {
      fGgmlVkMatmul(ctx, subctx, p, {qx_buf, 0, qx_sz}, {y_buf, 0, y_sz}, {d_buf, 0, d_sz},
                    {ctx->vPreallocSplitK, 0, ctx->vPreallocSizeSplitK}, m, n, k, k, k, m, k * m, k * n, m * n, split_k,
                    batch, batch, batch, 1, 1, n);
    }
  }
  fGgmlVkCtxEnd(subctx);

  auto begin = std::chrono::high_resolution_clock::now();

  fGgmlVkSubmit(subctx, ctx->fence);
  VK_CHECK(ctx->device->device.waitForFences({ctx->fence}, true, UINT64_MAX), "ggml_vk_test_dequant waitForFences");
  ctx->device->device.resetFences({ctx->fence});
  fGgmlVkQueueCommandPoolsCleanup(ctx->device);

  auto end = std::chrono::high_resolution_clock::now();

  double time_ms = std::chrono::duration_cast<std::chrono::microseconds>(end - begin).count() / 1000.0;
  fGgmlVkBufferRead(d_buf, 0, d, d_sz);

  ggml_init_params iparams = {
      /*.mem_size   =*/1024 * 1024 * 1024,
      /*.mem_buffer =*/NULL,
      /*.no_alloc   =*/true,
  };

  ggml_context *ggml_ctx = ggml_init(iparams);

  ggml_tensor *src0_ggml = ggml_new_tensor_3d(ggml_ctx, quant, k, m, batch);
  ggml_tensor *src1_ggml = ggml_new_tensor_3d(ggml_ctx, GGML_TYPE_F32, k, n, batch);
  ggml_tensor *tensor_ggml = ggml_mul_mat(ggml_ctx, src0_ggml, src1_ggml);

  src0_ggml->data = qx;
  src1_ggml->data = y;
  tensor_ggml->data = d_chk;

  ggml_cgraph *cgraph = ggml_new_graph(ggml_ctx);
  ggml_build_forward_expand(cgraph, tensor_ggml);

  ggml_graph_compute_with_ctx(ggml_ctx, cgraph, 1);

  ggml_free(ggml_ctx);

  double avg_err = 0.0;
  int first_err_n = -1;
  int first_err_m = -1;
  int first_err_b = -1;

  for (size_t i = 0; i < m * n * batch; i++) {
    double err = std::fabs(d[i] - d_chk[i]);
    avg_err += err;

    if ((err > 0.05f || std::isnan(err)) && first_err_n == -1) {
      first_err_b = i / (m * n);
      first_err_n = (i % (m * n)) / m;
      first_err_m = (i % (m * n)) % m;
    }
  }

  avg_err /= m * n;

  double tflops = 2.0 * m * n * k * batch * num_it / (time_ms / 1000.0) / (1000.0 * 1000.0 * 1000.0 * 1000.0);

  std::cerr << "TEST dequant matmul " << shname;
  if (mmq) {
    std::cerr << " mmq";
  }
  std::cerr << " m=" << m << " n=" << n << " k=" << k << " batch=" << batch << " split_k=" << split_k << " matmul "
            << time_ms / num_it << "ms " << tflops << " TFLOPS avg_err=" << avg_err << std::endl;

  if (avg_err > 0.01 || std::isnan(avg_err)) {
    std::cerr << "m = " << first_err_m << " n = " << first_err_n << " b = " << first_err_b << std::endl;
    std::cerr << "Actual result: " << std::endl << std::endl;
    ggml_vk_print_matrix_area(d, GGML_TYPE_F32, m, n, first_err_m, first_err_n, first_err_b);
    std::cerr << std::endl;
    std::cerr << "Expected result: " << std::endl << std::endl;
    ggml_vk_print_matrix_area(d_chk, GGML_TYPE_F32, m, n, first_err_m, first_err_n, first_err_b);

    std::cerr << "src0: " << std::endl << std::endl;
    ggml_vk_print_matrix_area(x, GGML_TYPE_F32, k, m, first_err_m, first_err_n, first_err_b);
    std::cerr << std::endl;
    std::cerr << "src1: " << std::endl << std::endl;
    ggml_vk_print_matrix_area(y, GGML_TYPE_F32, k, n, first_err_m, first_err_n, first_err_b);

    if (split_k > 1) {
      float *split_k_buf = (float *)malloc(sizeof(float) * d_ne * split_k);
      fGgmlVkBufferRead(ctx->vPreallocSplitK, 0, split_k_buf, sizeof(float) * d_ne * split_k);

      std::cerr << "d_buf0: " << std::endl << std::endl;
      ggml_vk_print_matrix_area(split_k_buf, GGML_TYPE_F32, m, n, first_err_m, first_err_n, first_err_b);

      std::cerr << "d_buf1: " << std::endl << std::endl;
      ggml_vk_print_matrix_area(split_k_buf + d_ne, GGML_TYPE_F32, m, n, first_err_m, first_err_n, first_err_b);

      std::cerr << "d_buf2: " << std::endl << std::endl;
      ggml_vk_print_matrix_area(split_k_buf + 2 * d_ne, GGML_TYPE_F32, m, n, first_err_m, first_err_n, first_err_b);

      std::cerr << "d_buf3: " << std::endl << std::endl;
      ggml_vk_print_matrix_area(split_k_buf + 3 * d_ne, GGML_TYPE_F32, m, n, first_err_m, first_err_n, first_err_b);

      free(split_k_buf);
    }
  }

  fGgmlVkDestroyBuffer(qx_buf);
  fGgmlVkDestroyBuffer(y_buf);
  fGgmlVkDestroyBuffer(qy_buf);
  fGgmlVkDestroyBuffer(d_buf);

  free(x);
  free(qx);
  free(y);
  free(d);
  free(d_chk);
}
#endif

static void fGgmlVkPreallocateBuffers(ggml_backend_vk_context *ctx, vk_context pSubctx) {
#if defined(GGML_VULKAN_RUN_TESTS)
  const std::vector<size_t> vals{
      512, 512, 128, 128, 512, 512, 4096, 512, 4096, 11008, 512, 4096, 4096, 512, 11008, 32000, 512, 4096,
      8,   8,   8,   100, 46,  576, 623,  111, 128,  100,   46,  558,  512,  1,   256,   128,   110, 622,
      511, 511, 127, 511, 511, 7,   511,  511, 17,   49,    49,  128,  128,  49,  49,    4096,  49,  4096,
  };
  const size_t num_it = 100;

  ggml_vk_test_dequant_matmul(ctx, 4096, 512, 4096, 2, num_it, 1, 0, GGML_TYPE_Q4_0);
  ggml_vk_test_dequant_matmul(ctx, 4096, 512, 4096, 2, num_it, 1, 1, GGML_TYPE_Q4_0);
  ggml_vk_test_dequant_matmul(ctx, 4096, 512, 4096, 2, num_it, 1, 2, GGML_TYPE_Q4_0);

  ggml_vk_test_dequant_matmul(ctx, 4096, 512, 4096, 2, num_it, 1, 0, GGML_TYPE_Q4_0, true);
  ggml_vk_test_dequant_matmul(ctx, 4096, 512, 4096, 2, num_it, 1, 1, GGML_TYPE_Q4_0, true);
  ggml_vk_test_dequant_matmul(ctx, 4096, 512, 4096, 2, num_it, 1, 2, GGML_TYPE_Q4_0, true);

  ggml_vk_test_dequant_matmul(ctx, 4096, 512, 4096, 2, num_it, 1, 0, GGML_TYPE_Q8_0);
  ggml_vk_test_dequant_matmul(ctx, 4096, 512, 4096, 2, num_it, 1, 1, GGML_TYPE_Q8_0);
  ggml_vk_test_dequant_matmul(ctx, 4096, 512, 4096, 2, num_it, 1, 2, GGML_TYPE_Q8_0);

  ggml_vk_test_dequant_matmul(ctx, 4096, 512, 4096, 2, num_it, 1, 0, GGML_TYPE_Q8_0, true);
  ggml_vk_test_dequant_matmul(ctx, 4096, 512, 4096, 2, num_it, 1, 1, GGML_TYPE_Q8_0, true);
  ggml_vk_test_dequant_matmul(ctx, 4096, 512, 4096, 2, num_it, 1, 2, GGML_TYPE_Q8_0, true);

  abort();

  for (size_t i = 0; i < vals.size(); i += 3) {
    ggml_vk_test_matmul<ggml_fp16_t, float>(ctx, vals[i], vals[i + 1], vals[i + 2], 2, num_it, 1, 0);
    ggml_vk_test_matmul<ggml_fp16_t, float>(ctx, vals[i], vals[i + 1], vals[i + 2], 2, num_it, 1, 1);
    ggml_vk_test_matmul<ggml_fp16_t, float>(ctx, vals[i], vals[i + 1], vals[i + 2], 2, num_it, 1, 2);
    std::cerr << '\n';
    ggml_vk_test_matmul<ggml_fp16_t, float>(ctx, vals[i], vals[i + 1], vals[i + 2], 2, num_it, 2, 0);
    ggml_vk_test_matmul<ggml_fp16_t, float>(ctx, vals[i], vals[i + 1], vals[i + 2], 2, num_it, 2, 1);
    ggml_vk_test_matmul<ggml_fp16_t, float>(ctx, vals[i], vals[i + 1], vals[i + 2], 2, num_it, 2, 2);
    std::cerr << '\n';
    ggml_vk_test_matmul<ggml_fp16_t, float>(ctx, vals[i], vals[i + 1], vals[i + 2], 2, num_it, 4, 0);
    ggml_vk_test_matmul<ggml_fp16_t, float>(ctx, vals[i], vals[i + 1], vals[i + 2], 2, num_it, 4, 1);
    ggml_vk_test_matmul<ggml_fp16_t, float>(ctx, vals[i], vals[i + 1], vals[i + 2], 2, num_it, 4, 2);
    std::cerr << '\n' << std::endl;

    if (vals[i + 2] % 32 == 0) {
      ggml_vk_test_dequant_matmul(ctx, vals[i], vals[i + 1], vals[i + 2], 2, num_it, 1, 0, GGML_TYPE_Q4_0);
      ggml_vk_test_dequant_matmul(ctx, vals[i], vals[i + 1], vals[i + 2], 2, num_it, 1, 1, GGML_TYPE_Q4_0);
      ggml_vk_test_dequant_matmul(ctx, vals[i], vals[i + 1], vals[i + 2], 2, num_it, 1, 2, GGML_TYPE_Q4_0);
      std::cerr << '\n';
      ggml_vk_test_dequant_matmul(ctx, vals[i], vals[i + 1], vals[i + 2], 2, num_it, 2, 0, GGML_TYPE_Q4_0);
      ggml_vk_test_dequant_matmul(ctx, vals[i], vals[i + 1], vals[i + 2], 2, num_it, 2, 1, GGML_TYPE_Q4_0);
      ggml_vk_test_dequant_matmul(ctx, vals[i], vals[i + 1], vals[i + 2], 2, num_it, 2, 2, GGML_TYPE_Q4_0);
      std::cerr << '\n';
      ggml_vk_test_dequant_matmul(ctx, vals[i], vals[i + 1], vals[i + 2], 2, num_it, 4, 0, GGML_TYPE_Q4_0);
      ggml_vk_test_dequant_matmul(ctx, vals[i], vals[i + 1], vals[i + 2], 2, num_it, 4, 1, GGML_TYPE_Q4_0);
      ggml_vk_test_dequant_matmul(ctx, vals[i], vals[i + 1], vals[i + 2], 2, num_it, 4, 2, GGML_TYPE_Q4_0);
      std::cerr << '\n' << std::endl;
    }

    if (vals[i + 2] % 256 == 0) {
      ggml_vk_test_dequant_matmul(ctx, vals[i], vals[i + 1], vals[i + 2], 2, num_it, 1, 0, GGML_TYPE_Q4_K);
      ggml_vk_test_dequant_matmul(ctx, vals[i], vals[i + 1], vals[i + 2], 2, num_it, 1, 1, GGML_TYPE_Q4_K);
      ggml_vk_test_dequant_matmul(ctx, vals[i], vals[i + 1], vals[i + 2], 2, num_it, 1, 2, GGML_TYPE_Q4_K);
      std::cerr << '\n';
      ggml_vk_test_dequant_matmul(ctx, vals[i], vals[i + 1], vals[i + 2], 2, num_it, 2, 0, GGML_TYPE_Q4_K);
      ggml_vk_test_dequant_matmul(ctx, vals[i], vals[i + 1], vals[i + 2], 2, num_it, 2, 1, GGML_TYPE_Q4_K);
      ggml_vk_test_dequant_matmul(ctx, vals[i], vals[i + 1], vals[i + 2], 2, num_it, 2, 2, GGML_TYPE_Q4_K);
      std::cerr << '\n';
      ggml_vk_test_dequant_matmul(ctx, vals[i], vals[i + 1], vals[i + 2], 2, num_it, 4, 0, GGML_TYPE_Q4_K);
      ggml_vk_test_dequant_matmul(ctx, vals[i], vals[i + 1], vals[i + 2], 2, num_it, 4, 1, GGML_TYPE_Q4_K);
      ggml_vk_test_dequant_matmul(ctx, vals[i], vals[i + 1], vals[i + 2], 2, num_it, 4, 2, GGML_TYPE_Q4_K);
      std::cerr << '\n' << std::endl;
    }
  }

  GGML_ABORT("fatal error");
#endif

  if (pSubctx) {
    // Submit and wait for any pending work before reallocating the buffers
    fGgmlVkCtxEnd(pSubctx);
    fGgmlVkSubmit(pSubctx, {});
    ctx->vSubmitPending = true;
    fGgmlVkSynchronize(ctx);
    GGML_ASSERT(ctx->compute_ctx.expired());
    fGgmlVkCtxBegin(ctx->device, pSubctx);
    ctx->compute_ctx = pSubctx;
  }

  if (ctx->vPreallocX == nullptr || (ctx->vPreallocSizeX > 0 && ctx->vPreallocX->size < ctx->vPreallocSizeX)) {
    VK_LOG_MEMORY("ggml_vk_preallocate_buffers(x_size: " << ctx->vPreallocSizeX << ")");
    // Resize buffer
    if (ctx->vPreallocX != nullptr) {
      fGgmlVkDestroyBuffer(ctx->vPreallocX);
    }
    ctx->vPreallocX = fGgmlVkCreateBufferDevice(ctx->device, ctx->vPreallocSizeX);
  }
  if (ctx->vPreallocY == nullptr || (ctx->vPreallocSizeY > 0 && ctx->vPreallocY->size < ctx->vPreallocSizeY)) {
    VK_LOG_MEMORY("ggml_vk_preallocate_buffers(y_size: " << ctx->vPreallocSizeY << ")");
    // Resize buffer
    if (ctx->vPreallocY != nullptr) {
      fGgmlVkDestroyBuffer(ctx->vPreallocY);
    }
    ctx->vPreallocY = fGgmlVkCreateBufferDevice(ctx->device, ctx->vPreallocSizeY);
    ctx->vPreallocYLastPipelineUsed = nullptr;
    ctx->vPreallocYLastTensorUsed = nullptr;
    ctx->vPreallocYLastDecodeVectorStaging = false;
  }
  if (ctx->vPreallocSplitK == nullptr ||
      (ctx->vPreallocSizeSplitK > 0 && ctx->vPreallocSplitK->size < ctx->vPreallocSizeSplitK)) {
    VK_LOG_MEMORY("ggml_vk_preallocate_buffers(split_k_size: " << ctx->vPreallocSizeSplitK << ")");
    // Resize buffer
    if (ctx->vPreallocSplitK != nullptr) {
      fGgmlVkDestroyBuffer(ctx->vPreallocSplitK);
    }
    ctx->vPreallocSplitK = fGgmlVkCreateBufferDevice(ctx->device, ctx->vPreallocSizeSplitK);
  }
  if (ctx->vPreallocAddRmsPartials == nullptr ||
      (ctx->vPreallocSizeAddRmsPartials > 0 && ctx->vPreallocAddRmsPartials->size < ctx->vPreallocSizeAddRmsPartials)) {
    VK_LOG_MEMORY("ggml_vk_preallocate_buffers(add_partials_size: " << ctx->vPreallocAddRmsPartials << ")");
    // Resize buffer
    if (ctx->vPreallocAddRmsPartials != nullptr) {
      fGgmlVkDestroyBuffer(ctx->vPreallocAddRmsPartials);
    }
    ctx->vPreallocAddRmsPartials = fGgmlVkCreateBufferDevice(ctx->device, ctx->vPreallocSizeAddRmsPartials);
  }
}

static void fGgmlVkComputeForward(ggml_backend_vk_context *pCtx, ggml_cgraph *pCgraph, ggml_tensor *pTensor,
                                  int pTensorIdx, bool pAlmostReady);

// Returns true if node has enqueued work into the queue, false otherwise
// If submit is true the current all operations queued so far are being submitted to Vulkan to overlap cmdlist creation
// and GPU execution.
static bool fGgmlVkBuildGraph(ggml_backend_vk_context *pCtx, ggml_cgraph *pCgraph, int pNodeIdx,
                              ggml_tensor *pNodeBegin, int pNodeIdxBegin, bool pLastNode, bool pAlmostReady,
                              bool pSubmit) {
  ggml_tensor *node = pCgraph->nodes[pNodeIdx];
  if (ggml_is_empty(node) || ggml_op_is_empty(node->op) || !node->buffer) {
    return false;
  }
  if ((node->flags & GGML_TENSOR_FLAG_COMPUTE) == 0) {
    return false;
  }

  VK_LOG_DEBUG("ggml_vk_build_graph(" << node << ", " << ggml_op_name(node->op) << ")");
  pCtx->vSemaphoreIdx = 0;

  ggml_tensor *vSrc0 = node->src[0];
  ggml_tensor *vSrc1 = node->src[1];
  ggml_tensor *vSrc2 = node->src[2];
  ggml_tensor *vSrc3 = node->src[3];

  if (node->op == GGML_OP_ADD) {
    int vNextNodeIdx = pNodeIdx + 1 + pCtx->vNumAdditionalFusedOps;
    if (vNextNodeIdx < pCgraph->n_nodes && pCgraph->nodes[vNextNodeIdx]->op == GGML_OP_RMS_NORM &&
        pCgraph->nodes[vNextNodeIdx]->src[0] == pCgraph->nodes[vNextNodeIdx - 1] &&
        ggml_nrows(pCgraph->nodes[vNextNodeIdx]) == 1 && pCtx->device->vAddRmsFusion) {
      uint32_t vSize = fGgmlVkRmsPartialsSize(pCtx, pCgraph->nodes[pNodeIdx]);
      pCtx->vDoAddRmsPartialsOffsetCalculation = true;
      if (pCtx->vPreallocSizeAddRmsPartialsOffset + vSize <= pCtx->vPreallocSizeAddRmsPartials) {
        pCtx->vDoAddRmsPartials = true;
      }
    }
  }

  vk_context vComputeCtx = fGgmlVkGetComputeCtx(pCtx);

  {
    // This logic detects dependencies between modes in the graph and calls ggml_vk_sync_buffers
    // to synchronize them. This handles most "normal" synchronization when computing the graph, and when
    // there is no auxiliary memory use, it shouldn't be necessary to call ggml_vk_sync_buffers
    // outside of this logic. When a node uses one of the prealloc buffers for something like
    // dequantization or split_k, additional synchronization is needed between those passes.
    bool vNeedSync = false;

    // Check whether "node" requires synchronization. The node requires synchronization if it
    // overlaps in memory with another unsynchronized node and at least one of them is a write.
    // Destination nodes are checked against both the written/read lists. Source nodes are only
    // checked against the written list. Two nodes overlap in memory if they come from the same
    // buffer and the tensor or view ranges overlap.
    auto const &fOverlapsUnsynced = [&](const ggml_tensor *node,
                                        const std::vector<const ggml_tensor *> &pUnsyncedNodes) -> bool {
      if (pUnsyncedNodes.size() == 0) {
        return false;
      }
      auto vNBase = fVkTensorOffset(node) + node->view_offs;
      auto vNSize = ggml_nbytes(node);
      ggml_backend_vk_buffer_context *vABufCtx = (ggml_backend_vk_buffer_context *)node->buffer->context;
      vk_buffer vABuf = vABufCtx->vDevBuffer;
      for (auto &vOther : pUnsyncedNodes) {
        ggml_backend_vk_buffer_context *vOBufCtx = (ggml_backend_vk_buffer_context *)vOther->buffer->context;
        vk_buffer vOBuf = vOBufCtx->vDevBuffer;
        if (vABuf == vOBuf) {
          auto vOBase = fVkTensorOffset(vOther) + vOther->view_offs;
          auto vOSize = ggml_nbytes(vOther);

          if ((vOBase <= vNBase && vNBase < vOBase + vOSize) || (vNBase <= vOBase && vOBase < vNBase + vNSize)) {
            return true;
          }
        }
      }
      return false;
    };

    // For all fused ops, check if the destination node or any of the source
    // nodes require synchronization.
    for (int32_t vI = 0; vI < pCtx->vNumAdditionalFusedOps + 1 && !vNeedSync; ++vI) {
      const ggml_tensor *vCurNode = pCgraph->nodes[pNodeIdx + vI];
      // If the node actually writes to memory, then check if it needs to sync
      if (pCtx->vFusedOpsWriteMask & (1 << vI)) {
        if (fOverlapsUnsynced(vCurNode, pCtx->lUnsyncedNodesRead) ||
            fOverlapsUnsynced(vCurNode, pCtx->lUnsyncedNodesWritten)) {
          vNeedSync = true;
          break;
        }
      }
      for (uint32_t vJ = 0; vJ < GGML_MAX_SRC; ++vJ) {
        if (!vCurNode->src[vJ]) {
          continue;
        }
        if (fOverlapsUnsynced(vCurNode->src[vJ], pCtx->lUnsyncedNodesWritten)) {
          vNeedSync = true;
          break;
        }
      }
    }

    if (vNeedSync) {
      if (vk_enable_sync_logger) {
        std::cerr << "sync" << std::endl;
      }
      pCtx->lUnsyncedNodesWritten.clear();
      pCtx->lUnsyncedNodesRead.clear();
      fGgmlVkSyncBuffers(pCtx, vComputeCtx);

      if (vk_perf_logger_enabled && vk_perf_logger_concurrent) {
        pCtx->lQueryNodeIdx[pCtx->vQueryIdx] = pNodeIdx;
        vComputeCtx->s->buffer->vBuf.writeTimestamp(vk::PipelineStageFlagBits::eAllCommands, pCtx->vQueryPool,
                                                    pCtx->vQueryIdx++);
        fGgmlVkSyncBuffers(pCtx, vComputeCtx);
      }
    }
    // Add all fused nodes to the unsynchronized lists.
    for (int32_t vI = 0; vI < pCtx->vNumAdditionalFusedOps + 1; ++vI) {
      const ggml_tensor *vCurNode = pCgraph->nodes[pNodeIdx + vI];
      // Multiple outputs could be written, e.g. in topk_moe. Add them all to the list.
      if (pCtx->vFusedOpsWriteMask & (1 << vI)) {
        pCtx->lUnsyncedNodesWritten.push_back(vCurNode);
      }
      for (uint32_t vJ = 0; vJ < GGML_MAX_SRC; ++vJ) {
        if (!vCurNode->src[vJ]) {
          continue;
        }
        pCtx->lUnsyncedNodesRead.push_back(vCurNode->src[vJ]);
      }
    }
  }
  if (vk_enable_sync_logger) {
    for (int vI = 0; vI < pCtx->vNumAdditionalFusedOps + 1; ++vI) {
      auto *vN = pCgraph->nodes[pNodeIdx + vI];
      std::cerr << pNodeIdx + vI << " " << ggml_op_name(vN->op) << " " << vN->name;
      if (vN->op == GGML_OP_GLU) {
        std::cerr << " " << ggml_glu_op_name(ggml_get_glu_op(vN)) << " " << (vN->src[1] ? "split" : "single") << " ";
      }
      if (vN->op == GGML_OP_ROPE) {
        const int cMode = ((const int32_t *)vN->op_params)[2];
        std::cerr << " rope mode: " << cMode;
      }
      std::cerr << std::endl;
    }
  }

  switch (node->op) {
  case GGML_OP_REPEAT:
    fGgmlVkRepeat(pCtx, vComputeCtx, vSrc0, node);

    break;
  case GGML_OP_REPEAT_BACK:
    fGgmlVkRepeatBack(pCtx, vComputeCtx, vSrc0, node);

    break;
  case GGML_OP_ACC:
  case GGML_OP_SET:
    fGgmlVkAcc(pCtx, vComputeCtx, vSrc0, vSrc1, node);

    break;
  case GGML_OP_GET_ROWS:
    fGgmlVkGetRows(pCtx, vComputeCtx, vSrc0, vSrc1, node);

    break;
  case GGML_OP_GET_ROWS_BACK:
    fGgmlVkGetRowsBack(pCtx, vComputeCtx, vSrc0, vSrc1, node);

    break;
  case GGML_OP_ADD:
    if (pCtx->vNumAdditionalFusedOps) {
      fGgmlVkMultiAdd(pCtx, vComputeCtx, pCgraph, pNodeIdx);
    } else {
      fGgmlVkAdd(pCtx, vComputeCtx, vSrc0, vSrc1, node);
    }
    break;
  case GGML_OP_OUT_PROD:
    fGgmlVkOutProd(pCtx, vComputeCtx, vSrc0, vSrc1, node);
    break;
  case GGML_OP_SUB:
    fGgmlVkSub(pCtx, vComputeCtx, vSrc0, vSrc1, node);

    break;
  case GGML_OP_MUL:
    if (pCtx->vNumAdditionalFusedOps) {
      fGgmlVkSnakeDispatchFused(pCtx, vComputeCtx, pCgraph, pNodeIdx);
    } else {
      fGgmlVkMul(pCtx, vComputeCtx, vSrc0, vSrc1, node);
    }

    break;
  case GGML_OP_DIV:
    fGgmlVkDiv(pCtx, vComputeCtx, vSrc0, vSrc1, node);

    break;
  case GGML_OP_ADD_ID:
    fGgmlVkAddId(pCtx, vComputeCtx, vSrc0, vSrc1, vSrc2, node);

    break;
  case GGML_OP_CONCAT:
    fGgmlVkConcat(pCtx, vComputeCtx, vSrc0, vSrc1, node);

    break;
  case GGML_OP_UPSCALE:
    fGgmlVkUpscale(pCtx, vComputeCtx, vSrc0, node);

    break;
  case GGML_OP_ADD1:
    fGgmlVkAdd1(pCtx, vComputeCtx, vSrc0, vSrc1, node);

    break;
  case GGML_OP_ARANGE:
    fGgmlVkArange(pCtx, vComputeCtx, node);

    break;
  case GGML_OP_FILL:
    fGgmlVkFill(pCtx, vComputeCtx, node);

    break;
  case GGML_OP_SCALE:
    if (pCtx->vFusedHcPostGate) {
      ggml_tensor *vHcPost = pCgraph->nodes[pNodeIdx + pCtx->vNumAdditionalFusedOps];
      fGgmlVkDsv4HcPost(pCtx, vComputeCtx, vHcPost->src[0], vHcPost->src[1], vHcPost->src[2], vHcPost->src[3], vHcPost,
                        node);
    } else {
      fGgmlVkScale(pCtx, vComputeCtx, vSrc0, node);
    }

    break;
  case GGML_OP_SQR:
    fGgmlVkSqr(pCtx, vComputeCtx, vSrc0, node);

    break;
  case GGML_OP_SQRT:
    fGgmlVkSqrt(pCtx, vComputeCtx, vSrc0, node);

    break;
  case GGML_OP_SIN:
    fGgmlVkSin(pCtx, vComputeCtx, vSrc0, node);

    break;
  case GGML_OP_COS:
    fGgmlVkCos(pCtx, vComputeCtx, vSrc0, node);

    break;
  case GGML_OP_LOG:
    fGgmlVkLog(pCtx, vComputeCtx, vSrc0, node);

    break;
  case GGML_OP_TRI:
    fGgmlVkTri(pCtx, vComputeCtx, vSrc0, node);

    break;
  case GGML_OP_DIAG:
    fGgmlVkDiag(pCtx, vComputeCtx, vSrc0, node);

    break;
  case GGML_OP_CLAMP:
    fGgmlVkClamp(pCtx, vComputeCtx, vSrc0, node);

    break;
  case GGML_OP_PAD:
    fGgmlVkPad(pCtx, vComputeCtx, vSrc0, node);

    break;
  case GGML_OP_ROLL:
    fGgmlVkRoll(pCtx, vComputeCtx, vSrc0, node);

    break;
  case GGML_OP_CPY:
  case GGML_OP_CONT:
  case GGML_OP_DUP:
    fGgmlVkCpy(pCtx, vComputeCtx, vSrc0, node);

    break;
  case GGML_OP_SET_ROWS:
    fGgmlVkSetRows(pCtx, vComputeCtx, vSrc0, vSrc1, node);

    break;
  case GGML_OP_SILU_BACK:
    fGgmlVkSiluBack(pCtx, vComputeCtx, vSrc0, vSrc1, node);

    break;
  case GGML_OP_NORM:
    fGgmlVkNorm(pCtx, vComputeCtx, vSrc0, node);

    break;
  case GGML_OP_GROUP_NORM:
    fGgmlVkGroupNorm(pCtx, vComputeCtx, vSrc0, node);

    break;
  case GGML_OP_RMS_NORM:
    fGgmlVkRmsNorm(pCtx, vComputeCtx, pCgraph, pNodeIdx, (float *)node->op_params);
    break;
  case GGML_OP_RMS_NORM_BACK:
    fGgmlVkRmsNormBack(pCtx, vComputeCtx, vSrc0, vSrc1, node);

    break;
  case GGML_OP_L2_NORM:
    fGgmlVkL2Norm(pCtx, vComputeCtx, vSrc0, node);

    break;
  case GGML_OP_UNARY:
    if (pCtx->vFusedTopkMoeMode != TOPK_MOE_COUNT) {
      fGgmlVkTopkMoe(pCtx, vComputeCtx, pCgraph, pNodeIdx);
      break;
    }
    if (pCtx->vNumAdditionalFusedOps) {
      fGgmlVkUnaryMul(pCtx, vComputeCtx, pCgraph, pNodeIdx);
      break;
    }

    switch (ggml_get_unary_op(node)) {
    case GGML_UNARY_OP_ELU:
    case GGML_UNARY_OP_EXP:
    case GGML_UNARY_OP_EXPM1:
    case GGML_UNARY_OP_SILU:
    case GGML_UNARY_OP_GELU:
    case GGML_UNARY_OP_GELU_ERF:
    case GGML_UNARY_OP_GELU_QUICK:
    case GGML_UNARY_OP_RELU:
    case GGML_UNARY_OP_NEG:
    case GGML_UNARY_OP_TANH:
    case GGML_UNARY_OP_SIGMOID:
    case GGML_UNARY_OP_HARDSIGMOID:
    case GGML_UNARY_OP_HARDSWISH:
    case GGML_UNARY_OP_ABS:
    case GGML_UNARY_OP_SOFTPLUS:
    case GGML_UNARY_OP_STEP:
    case GGML_UNARY_OP_ROUND:
    case GGML_UNARY_OP_CEIL:
    case GGML_UNARY_OP_FLOOR:
    case GGML_UNARY_OP_TRUNC:
    case GGML_UNARY_OP_SGN:
      fGgmlVkUnary(pCtx, vComputeCtx, vSrc0, node);
      break;
    case GGML_UNARY_OP_XIELU:
      fGgmlVkXielu(pCtx, vComputeCtx, vSrc0, node);
      break;
    default:
      return false;
    }
    break;
  case GGML_OP_GLU:
    switch (ggml_get_glu_op(node)) {
    case GGML_GLU_OP_GEGLU:
    case GGML_GLU_OP_REGLU:
    case GGML_GLU_OP_SWIGLU:
    case GGML_GLU_OP_SWIGLU_OAI:
    case GGML_GLU_OP_GEGLU_ERF:
    case GGML_GLU_OP_GEGLU_QUICK:
    case GGML_GLU_OP_SWIGLU_CLAMP:
      fGgmlVkGlu(pCtx, vComputeCtx, vSrc0, vSrc1, node);
      break;
    default:
      return false;
    }
    break;
  case GGML_OP_DIAG_MASK_INF:
    fGgmlVkDiagMaskInf(pCtx, vComputeCtx, vSrc0, node);

    break;
  case GGML_OP_SOFT_MAX:
    if (pCtx->vFusedTopkMoeMode != TOPK_MOE_COUNT) {
      fGgmlVkTopkMoe(pCtx, vComputeCtx, pCgraph, pNodeIdx);
    } else {
      fGgmlVkSoftMax(pCtx, vComputeCtx, vSrc0, vSrc1, vSrc2, node);
    }

    break;
  case GGML_OP_SOFT_MAX_BACK:
    fGgmlVkSoftMaxBack(pCtx, vComputeCtx, vSrc0, vSrc1, node);

    break;
  case GGML_OP_ROPE:
    fGgmlVkRope(pCtx, vComputeCtx, pCgraph, pNodeIdx, false);

    break;
  case GGML_OP_ROPE_BACK:
    fGgmlVkRope(pCtx, vComputeCtx, pCgraph, pNodeIdx, true);

    break;
  case GGML_OP_ARGSORT:
    if (pCtx->vFusedTopkMoeMode != TOPK_MOE_COUNT) {
      fGgmlVkTopkMoe(pCtx, vComputeCtx, pCgraph, pNodeIdx);
    } else {
      fGgmlVkArgsort(pCtx, vComputeCtx, vSrc0, node);
    }

    break;
  case GGML_OP_TOP_K:
    fGgmlVkTopk(pCtx, vComputeCtx, vSrc0, node);

    break;
  case GGML_OP_SUM:
    fGgmlVkSum(pCtx, vComputeCtx, vSrc0, node);

    break;
  case GGML_OP_SUM_ROWS:
    fGgmlVkSumRows(pCtx, vComputeCtx, vSrc0, node);

    break;
  case GGML_OP_CUMSUM:
    fGgmlVkCumsum(pCtx, vComputeCtx, vSrc0, node);

    break;
  case GGML_OP_MEAN:
    fGgmlVkMean(pCtx, vComputeCtx, vSrc0, node);

    break;
  case GGML_OP_ARGMAX:
    fGgmlVkArgmax(pCtx, vComputeCtx, vSrc0, node);

    break;
  case GGML_OP_AMAX_POW2:
    if (pCtx->vFusedAmaxPow2Mode) {
      fGgmlVkAmaxPow2Fused(pCtx, vComputeCtx, pCgraph, pNodeIdx);
    } else {
      fGgmlVkAmaxPow2(pCtx, vComputeCtx, vSrc0, node);
    }

    break;
  case GGML_OP_COUNT_EQUAL:
    fGgmlVkCountEqual(pCtx, vComputeCtx, vSrc0, vSrc1, node);

    break;
  case GGML_OP_SOLVE_TRI:
    fGgmlVkSolveTri(pCtx, vComputeCtx, vSrc0, vSrc1, node);

    break;
  case GGML_OP_DSV4_HC_COMB:
    fGgmlVkDsv4HcComb(pCtx, vComputeCtx, vSrc0, vSrc1, vSrc2, node);

    break;
  case GGML_OP_DSV4_HC_PRE:
    fGgmlVkDsv4HcPre(pCtx, vComputeCtx, vSrc0, vSrc1, node);

    break;
  case GGML_OP_DSV4_HC_POST:
    fGgmlVkDsv4HcPost(pCtx, vComputeCtx, vSrc0, vSrc1, vSrc2, vSrc3, node);

    break;
  case GGML_OP_IM2COL:
    fGgmlVkIm2col(pCtx, vComputeCtx, vSrc0, vSrc1, node);

    break;
  case GGML_OP_IM2COL_3D:
    fGgmlVkIm2col3d(pCtx, vComputeCtx, vSrc0, vSrc1, node);

    break;
  case GGML_OP_TIMESTEP_EMBEDDING:
    fGgmlVkTimestepEmbedding(pCtx, vComputeCtx, vSrc0, node);

    break;
  case GGML_OP_COL2IM_1D:
    fGgmlVkCol2im1d(pCtx, vComputeCtx, vSrc0, node);

    break;
  case GGML_OP_CONV_TRANSPOSE_1D:
    fGgmlVkConvTranspose1d(pCtx, vComputeCtx, vSrc0, vSrc1, node);

    break;
  case GGML_OP_POOL_1D:
    fGgmlVkPool1d(pCtx, vComputeCtx, vSrc0, node);

    break;
  case GGML_OP_POOL_2D:
    fGgmlVkPool2d(pCtx, vComputeCtx, vSrc0, node);

    break;
  case GGML_OP_CONV_2D:
  case GGML_OP_CONV_TRANSPOSE_2D:
    fGgmlVkConv2d(pCtx, vComputeCtx, vSrc0, vSrc1, node);

    break;
  case GGML_OP_CONV_3D:
    fGgmlVkConv3d(pCtx, vComputeCtx, vSrc0, vSrc1, node);

    break;
  case GGML_OP_CONV_2D_DW:
    fGgmlVkConv2dDw(pCtx, vComputeCtx, vSrc0, vSrc1, node);

    break;
  case GGML_OP_LEAKY_RELU:
    fGgmlVkLeakyRelu(pCtx, vComputeCtx, vSrc0, node);

    break;
  case GGML_OP_MUL_MAT:
    fGgmlVkMulMat(pCtx, vComputeCtx, pCgraph, pNodeIdx);

    break;
  case GGML_OP_MUL_MAT_ID:
    fGgmlVkMulMatId(pCtx, vComputeCtx, pCgraph, pNodeIdx);

    break;

  case GGML_OP_FLASH_ATTN_EXT:
    fGgmlVkFlashAttn(pCtx, vComputeCtx, vSrc0, vSrc1, vSrc2, vSrc3, node->src[4], node);

    break;

  case GGML_OP_RWKV_WKV6:
    fGgmlVkRwkvWkv6(pCtx, vComputeCtx, node);

    break;

  case GGML_OP_RWKV_WKV7:
    fGgmlVkRwkvWkv7(pCtx, vComputeCtx, node);

    break;

  case GGML_OP_GATED_LINEAR_ATTN:
    fGgmlVkGatedLinearAttn(pCtx, vComputeCtx, node);

    break;

  case GGML_OP_LIGHTNING_INDEXER:
    fGgmlVkLightningIndexer(pCtx, vComputeCtx, node);

    break;

  case GGML_OP_GATED_DELTA_NET:
    fGgmlVkGatedDeltaNet(pCtx, vComputeCtx, node);

    break;

  case GGML_OP_SSM_SCAN:
    fGgmlVkSsmScan(pCtx, vComputeCtx, node);

    break;

  case GGML_OP_SSM_CONV:
    fGgmlVkSsmConv(pCtx, vComputeCtx, pCgraph, pNodeIdx);

    break;

  case GGML_OP_OPT_STEP_ADAMW:
    fGgmlVkOptStepAdamw(pCtx, vComputeCtx, node);

    break;

  case GGML_OP_OPT_STEP_SGD:
    fGgmlVkOptStepSgd(pCtx, vComputeCtx, vSrc0, vSrc1, vSrc2, node);

    break;
  default:
    return false;
  }

  pCtx->lTensorCtxs[pNodeIdx] = vComputeCtx;

#if defined(GGML_VULKAN_CHECK_RESULTS)
  // Force context reset on each node so that each tensor ends up in its own context
  // and can be run and compared to its CPU equivalent separately
  pLastNode = true;
#endif

  if (pSubmit || pLastNode) {
    fGgmlVkCtxEnd(vComputeCtx);

    // TODO probably it'd be better to pass a exit_node flag to ggml_vk_compute_forward
    if (pLastNode) {
      vComputeCtx->vExitTensorIdx = pNodeIdxBegin;
    } else {
      vComputeCtx->vExitTensorIdx = -1;
    }

    pCtx->compute_ctx.reset();

    fGgmlVkComputeForward(pCtx, pCgraph, pNodeBegin, pNodeIdxBegin, pAlmostReady);
  }
  return true;
}

static void fGgmlVkComputeForward(ggml_backend_vk_context *ctx, ggml_cgraph *pCgraph, ggml_tensor *pTensor,
                                  int pTensorIdx, bool pAlmostReady = false) {
  GGML_UNUSED(pCgraph);
  GGML_UNUSED(pTensor);

  VK_LOG_DEBUG("ggml_vk_compute_forward("
               << pTensor << ", name=" << pTensor->name << ", op=" << ggml_op_name(pTensor->op)
               << ", type=" << pTensor->type << ", ne0=" << pTensor->ne[0] << ", ne1=" << pTensor->ne[1]
               << ", ne2=" << pTensor->ne[2] << ", ne3=" << pTensor->ne[3] << ", nb0=" << pTensor->nb[0]
               << ", nb1=" << pTensor->nb[1] << ", nb2=" << pTensor->nb[2] << ", nb3=" << pTensor->nb[3]
               << ", view_src=" << pTensor->view_src << ", view_offs=" << pTensor->view_offs << ")");

  vk_context vSubctx = ctx->lTensorCtxs[pTensorIdx].lock();

  // Only run if ctx hasn't been submitted yet
  if (!vSubctx->vSeqs.empty()) {
#ifdef GGML_VULKAN_CHECK_RESULTS
    ggml_vk_check_results_0(ctx, pCgraph, pTensorIdx);
#endif

    // Do staging buffer copies
    for (auto &vCpy : vSubctx->lInMemcpys) {
      memcpy(vCpy.dst, vCpy.src, vCpy.n);
    }

    for (auto &vMset : vSubctx->lMemsets) {
      memset(vMset.dst, vMset.val, vMset.n);
    }

    if (pAlmostReady && !ctx->vAlmostReadyFencePending) {
      fGgmlVkSubmit(vSubctx, ctx->vAlmostReadyFence);
      ctx->vAlmostReadyFencePending = true;
    } else {
      fGgmlVkSubmit(vSubctx, {});
    }
    ctx->vSubmitPending = true;

#ifdef GGML_VULKAN_CHECK_RESULTS
    fGgmlVkSynchronize(ctx);
    ggml_vk_check_results_1(ctx, pCgraph, pTensorIdx);
#endif
  }

  if (pTensorIdx == vSubctx->vExitTensorIdx) {
    // Do staging buffer copies
    for (auto &vCpy : vSubctx->lOutMemcpys) {
      memcpy(vCpy.dst, vCpy.src, vCpy.n);
    }
    vSubctx->lInMemcpys.clear();
    vSubctx->lOutMemcpys.clear();
    vSubctx->lMemsets.clear();
  }
}

// Clean up after graph processing is done
static void fGgmlVkGraphCleanup(ggml_backend_vk_context *pCtx) {
  VK_LOG_DEBUG("ggml_vk_graph_cleanup()");
  pCtx->vPreallocYLastPipelineUsed = {};
  pCtx->vPreallocYLastTensorUsed = nullptr;
  pCtx->vPreallocYLastDecodeVectorStaging = false;

  pCtx->lUnsyncedNodesWritten.clear();
  pCtx->lUnsyncedNodesRead.clear();
  pCtx->vPreallocXNeedSync = pCtx->vPreallocYNeedSync = pCtx->vPreallocSplitKNeedSync = false;

  fGgmlVkCommandPoolCleanup(pCtx->device, pCtx->vComputeCmdPool);
  if (pCtx->device->vAsyncUseTransferQueue) {
    fGgmlVkCommandPoolCleanup(pCtx->device, pCtx->vTransferCmdPool);
  }

  for (size_t vI = 0; vI < pCtx->vGc.lSemaphores.size(); vI++) {
    pCtx->device->device.destroySemaphore({pCtx->vGc.lSemaphores[vI].s});
  }
  pCtx->vGc.lSemaphores.clear();

  for (size_t vI = 0; vI < pCtx->vGc.lTlSemaphores.size(); vI++) {
    pCtx->device->device.destroySemaphore({pCtx->vGc.lTlSemaphores[vI].s});
  }
  pCtx->vGc.lTlSemaphores.clear();
  pCtx->vSemaphoreIdx = 0;

  pCtx->vEventIdx = 0;

  for (auto &vEvent : pCtx->vGc.lEvents) {
    pCtx->device->device.resetEvent(vEvent);
  }

  pCtx->lTensorCtxs.clear();
  pCtx->vGc.lContexts.clear();
  pCtx->vPipelineDescriptorSetRequirements = 0;
  pCtx->vDescriptorSetIdx = 0;
}

// Clean up on backend free
static void fGgmlVkCleanup(ggml_backend_vk_context *ctx) {
  VK_LOG_DEBUG("ggml_vk_cleanup(" << ctx->name << ")");
  // discard any unsubmitted command buffers
  ctx->compute_ctx.reset();
  // wait for any pending command buffers to finish
  fGgmlVkSynchronize(ctx);

  fGgmlVkGraphCleanup(ctx);

  fGgmlVkDestroyBuffer(ctx->vPreallocX);
  fGgmlVkDestroyBuffer(ctx->vPreallocY);
  fGgmlVkDestroyBuffer(ctx->vPreallocSplitK);
  fGgmlVkDestroyBuffer(ctx->vPreallocAddRmsPartials);
  fGgmlVkDestroyBuffer(ctx->vSyncStaging);
  // The synchronization above waited for every ring copy that was sent; the ones still unsent were discarded.
  fGgmlVkDestroyBuffer(ctx->vStagingRing);
  ctx->lLStagingRegions.clear();
  if (ctx->vStagingSemaphore.s) {
    ctx->device->device.destroySemaphore(ctx->vStagingSemaphore.s);
    ctx->vStagingSemaphore.s = VK_NULL_HANDLE;
  }

  ctx->vPreallocYLastPipelineUsed = nullptr;
  ctx->vPreallocYLastTensorUsed = nullptr;
  ctx->vPreallocYLastDecodeVectorStaging = false;

  ctx->vPreallocSizeX = 0;
  ctx->vPreallocSizeY = 0;
  ctx->vPreallocSizeSplitK = 0;

  for (auto &vEvent : ctx->vGc.lEvents) {
    ctx->device->device.destroyEvent(vEvent);
  }
  ctx->vGc.lEvents.clear();

  ctx->device->device.destroyFence(ctx->fence);
  ctx->device->device.destroyFence(ctx->vAlmostReadyFence);

  for (auto &vPool : ctx->lDescriptorPools) {
    ctx->device->device.destroyDescriptorPool(vPool);
  }
  ctx->lDescriptorPools.clear();
  ctx->vDescriptorSets.clear();

  ctx->vComputeCmdPool.mDestroy(ctx->device->device);
  if (ctx->device->vAsyncUseTransferQueue) {
    ctx->device->device.destroySemaphore(ctx->vTransferSemaphore.s);

    ctx->vTransferCmdPool.mDestroy(ctx->device->device);
  }
  if (vk_perf_logger_enabled) {
    ctx->vPerfLogger->mPrintTimings(true);
  }
}

static int fGgmlVkGetDeviceCount() {
  fGgmlVkInstanceInit();

  return vk_instance.vDeviceIndices.size();
}

static void fGgmlVkGetDeviceDescription(int pDevice, char *pDescription, size_t pDescriptionSize) {
  fGgmlVkInstanceInit();

  std::vector<vk::PhysicalDevice> vDevices = vk_instance.vInstance.enumeratePhysicalDevices();

  vk::PhysicalDeviceProperties vProps;
  vDevices[pDevice].getProperties(&vProps);

  snprintf(pDescription, pDescriptionSize, "%s", vProps.deviceName.data());
}

// backend interface

#define UNUSED GGML_UNUSED

// device backend

static bool fGgmlBackendBufferIsVk(ggml_backend_buffer_t pBuffer) {
  return pBuffer->buft->iface.get_name == fGgmlBackendVkBufferTypeName;
}

static void fGgmlBackendVkBufferFreeBuffer(ggml_backend_buffer_t pBuffer) {
  VK_LOG_MEMORY("ggml_backend_vk_buffer_free_buffer()");
  ggml_backend_vk_buffer_context *vCtx = (ggml_backend_vk_buffer_context *)pBuffer->context;
  fGgmlVkDestroyBuffer(vCtx->vDevBuffer);
  delete vCtx;
}

static void *fGgmlBackendVkBufferGetBase(ggml_backend_buffer_t pBuffer) {
  return vk_ptr_base;

  UNUSED(pBuffer);
}

static enum ggml_status fGgmlBackendVkBufferInitTensor(ggml_backend_buffer_t buffer, ggml_tensor *pTensor) {
  VK_LOG_DEBUG("ggml_backend_vk_buffer_init_tensor(" << buffer << " (" << buffer->context << "), " << pTensor << ")");
  if (pTensor->view_src != nullptr) {
    GGML_ASSERT(pTensor->view_src->buffer->buft == buffer->buft);
  }
  return GGML_STATUS_SUCCESS;
}

static void fGgmlBackendVkBufferMemsetTensor(ggml_backend_buffer_t buffer, ggml_tensor *pTensor, uint8_t value,
                                             size_t offset, size_t size) {
  VK_LOG_DEBUG("ggml_backend_vk_buffer_memset_tensor(" << buffer << ", " << pTensor << ", " << value << ", " << offset
                                                       << ", " << size << ")");
  ggml_backend_vk_buffer_context *vBufCtx = (ggml_backend_vk_buffer_context *)buffer->context;
  vk_buffer vBuf = vBufCtx->vDevBuffer;

  if (size == 0) {
    return;
  }

  uint32_t vVal32 = (uint32_t)value * 0x01010101;
  fGgmlVkBufferMemset(vBuf, fVkTensorOffset(pTensor) + pTensor->view_offs + offset, vVal32, size);
}

static void fGgmlBackendVkBufferSetTensor(ggml_backend_buffer_t buffer, ggml_tensor *pTensor, const void *pData,
                                          size_t offset, size_t size) {
  VK_LOG_DEBUG("ggml_backend_vk_buffer_set_tensor(" << buffer << ", " << pTensor << ", " << pData << ", " << offset
                                                    << ", " << size << ")");
  ggml_backend_vk_buffer_context *vBufCtx = (ggml_backend_vk_buffer_context *)buffer->context;
  vk_buffer vBuf = vBufCtx->vDevBuffer;

  if (size == 0) {
    return;
  }

  fGgmlVkBufferWrite(vBuf, fVkTensorOffset(pTensor) + pTensor->view_offs + offset, pData, size);
}

static void fGgmlBackendVkBufferSetTensor2d(ggml_backend_buffer_t buffer, ggml_tensor *pTensor, const void *pData,
                                            size_t offset, size_t size, size_t pNCopies, size_t pStrideTensor,
                                            size_t pStrideData) {
  VK_LOG_DEBUG("ggml_backend_vk_buffer_set_tensor_2d(" << buffer << ", " << pTensor << ", " << pData << ", " << offset
                                                       << ", " << size << ", " << pNCopies << ", " << pStrideTensor
                                                       << ", " << pStrideData << ")");
  ggml_backend_vk_buffer_context *vBufCtx = (ggml_backend_vk_buffer_context *)buffer->context;
  vk_buffer vBuf = vBufCtx->vDevBuffer;

  if (size == 0) {
    return;
  }

  fGgmlVkBufferWrite2d(vBuf, fVkTensorOffset(pTensor) + pTensor->view_offs + offset, pData, pStrideData, pStrideTensor,
                       size, pNCopies);
}

static void fGgmlBackendVkBufferGetTensor(ggml_backend_buffer_t buffer, const ggml_tensor *pTensor, void *pData,
                                          size_t offset, size_t size) {
  VK_LOG_DEBUG("ggml_backend_vk_buffer_get_tensor(" << buffer << ", " << pTensor << ", " << pData << ", " << offset
                                                    << ", " << size << ")");
  ggml_backend_vk_buffer_context *vBufCtx = (ggml_backend_vk_buffer_context *)buffer->context;

  if (size == 0) {
    return;
  }

  vk_buffer vBuf = vBufCtx->vDevBuffer;

  fGgmlVkBufferRead(vBuf, fVkTensorOffset(pTensor) + pTensor->view_offs + offset, pData, size);
}

static void fGgmlBackendVkBufferGetTensor2d(ggml_backend_buffer_t buffer, const ggml_tensor *pTensor, void *pData,
                                            size_t offset, size_t size, size_t pNCopies, size_t pStrideTensor,
                                            size_t pStrideData) {
  VK_LOG_DEBUG("ggml_backend_vk_buffer_get_tensor_2d(" << buffer << ", " << pTensor << ", " << pData << ", " << offset
                                                       << ", " << size << ", " << pNCopies << ", " << pStrideTensor
                                                       << ", " << pStrideData << ")");
  ggml_backend_vk_buffer_context *vBufCtx = (ggml_backend_vk_buffer_context *)buffer->context;

  if (size == 0) {
    return;
  }

  vk_buffer vBuf = vBufCtx->vDevBuffer;

  fGgmlVkBufferRead2d(vBuf, fVkTensorOffset(pTensor) + pTensor->view_offs + offset, pData, pStrideTensor, pStrideData,
                      size, pNCopies);
}

static bool fGgmlBackendVkBufferCpyTensor(ggml_backend_buffer_t pBuffer, const ggml_tensor *pSrc, ggml_tensor *pDst) {
  if (ggml_nbytes(pSrc) == 0) {
    return true;
  }

  if (fGgmlBackendBufferIsVk(pSrc->buffer)) {
    ggml_backend_vk_buffer_context *vSrcBufCtx = (ggml_backend_vk_buffer_context *)pSrc->buffer->context;
    ggml_backend_vk_buffer_context *vDstBufCtx = (ggml_backend_vk_buffer_context *)pDst->buffer->context;

    vk_buffer vSrcBuf = vSrcBufCtx->vDevBuffer;
    vk_buffer vDstBuf = vDstBufCtx->vDevBuffer;

    fGgmlVkBufferCopy(vDstBuf, fVkTensorOffset(pDst) + pDst->view_offs, vSrcBuf,
                      fVkTensorOffset(pSrc) + pSrc->view_offs, ggml_nbytes(pSrc));

    return true;
  }
  return false;

  UNUSED(pBuffer);
}

static void fGgmlBackendVkBufferClear(ggml_backend_buffer_t pBuffer, uint8_t pValue) {
  ggml_backend_vk_buffer_context *vCtx = (ggml_backend_vk_buffer_context *)pBuffer->context;

  fGgmlVkBufferMemset(vCtx->vDevBuffer, 0, pValue, pBuffer->size);
}

static ggml_backend_buffer_i ggml_backend_vk_buffer_interface = {
    /* .free_buffer     = */ fGgmlBackendVkBufferFreeBuffer,
    /* .get_base        = */ fGgmlBackendVkBufferGetBase,
    /* .init_tensor     = */ fGgmlBackendVkBufferInitTensor,
    /* .memset_tensor   = */ fGgmlBackendVkBufferMemsetTensor,
    /* .set_tensor      = */ fGgmlBackendVkBufferSetTensor,
    /* .get_tensor      = */ fGgmlBackendVkBufferGetTensor,
    /* .set_tensor_2d   = */ fGgmlBackendVkBufferSetTensor2d,
    /* .get_tensor_2d   = */ fGgmlBackendVkBufferGetTensor2d,
    /* .cpy_tensor      = */ fGgmlBackendVkBufferCpyTensor,
    /* .clear           = */ fGgmlBackendVkBufferClear,
    /* .reset           = */ NULL,
};

// vk buffer type
static const char *fGgmlBackendVkBufferTypeName(ggml_backend_buffer_type_t pBuft) {
  ggml_backend_vk_buffer_type_context *vCtx = (ggml_backend_vk_buffer_type_context *)pBuft->context;

  return vCtx->name.c_str();
}

static ggml_backend_buffer_t fGgmlBackendVkBufferTypeAllocBuffer(ggml_backend_buffer_type_t pBuft, size_t pSize) {
  VK_LOG_MEMORY("ggml_backend_vk_buffer_type_alloc_buffer(" << pSize << ")");
  ggml_backend_vk_buffer_type_context *vCtx = (ggml_backend_vk_buffer_type_context *)pBuft->context;

  vk_buffer vDevBuffer = nullptr;
  try {
    vDevBuffer = fGgmlVkCreateBufferDevice(vCtx->device, pSize, vCtx->vPriority);
  } catch (const vk::SystemError &vE) {
    return nullptr;
  }

  ggml_backend_vk_buffer_context *vBufctx =
      new ggml_backend_vk_buffer_context(vCtx->device, std::move(vDevBuffer), vCtx->name);

  return ggml_backend_buffer_init(pBuft, ggml_backend_vk_buffer_interface, vBufctx, pSize);
}

static size_t fGgmlBackendVkBufferTypeGetAlignment(ggml_backend_buffer_type_t pBuft) {
  ggml_backend_vk_buffer_type_context *vCtx = (ggml_backend_vk_buffer_type_context *)pBuft->context;
  return vCtx->device->properties.limits.minStorageBufferOffsetAlignment;
}

static size_t fGgmlBackendVkBufferTypeGetMaxSize(ggml_backend_buffer_type_t pBuft) {
  ggml_backend_vk_buffer_type_context *vCtx = (ggml_backend_vk_buffer_type_context *)pBuft->context;
  return vCtx->device->vSuballocationBlockSize;
}

static size_t fGgmlBackendVkBufferTypeGetAllocSize(ggml_backend_buffer_type_t pBuft, const ggml_tensor *pTensor) {
  return ggml_nbytes(pTensor);

  UNUSED(pBuft);
}

ggml_backend_buffer_type_t ggml_backend_vk_buffer_type(size_t pDevNum) {
  fGgmlVkInstanceInit();

  VK_LOG_DEBUG("ggml_backend_vk_buffer_type(" << pDevNum << ")");

  vk_device vDev = fGgmlVkGetDevice(pDevNum);

  return &vDev->vBufferType;
}

// host buffer type

static const char *fGgmlBackendVkHostBufferTypeName(ggml_backend_buffer_type_t pBuft) {
  return GGML_VK_NAME "_Host";

  UNUSED(pBuft);
}

static void fGgmlBackendVkHostBufferFreeBuffer(ggml_backend_buffer_t pBuffer) {
  VK_LOG_MEMORY("ggml_backend_vk_host_buffer_free_buffer()");
  fGgmlVkHostFree(vk_instance.vDevices[0], pBuffer->context);
}

static ggml_backend_buffer_t fGgmlBackendVkHostBufferTypeAllocBuffer(ggml_backend_buffer_type_t pBuft, size_t pSize) {
  VK_LOG_MEMORY("ggml_backend_vk_host_buffer_type_alloc_buffer(" << pSize << ")");

  pSize += 32; // Behave like the CPU buffer type
  void *vPtr = nullptr;
  try {
    vPtr = fGgmlVkHostMalloc(vk_instance.vDevices[0], pSize);
  } catch (vk::SystemError &vE) {
    GGML_LOG_WARN("ggml_vulkan: Failed to allocate pinned memory (%s)\n", vE.what());
    // fallback to cpu buffer
    return ggml_backend_buft_alloc_buffer(ggml_backend_cpu_buffer_type(), pSize);
  }

  ggml_backend_buffer_t vBuffer = ggml_backend_cpu_buffer_from_ptr(vPtr, pSize);
  vBuffer->buft = pBuft;
  vBuffer->iface.free_buffer = fGgmlBackendVkHostBufferFreeBuffer;

  return vBuffer;

  UNUSED(pBuft);
}

static size_t fGgmlBackendVkHostBufferTypeGetAlignment(ggml_backend_buffer_type_t pBuft) {
  return vk_instance.vDevices[0]->properties.limits.minMemoryMapAlignment;

  UNUSED(pBuft);
}

static size_t fGgmlBackendVkHostBufferTypeGetMaxSize(ggml_backend_buffer_type_t pBuft) {
  return vk_instance.vDevices[0]->vSuballocationBlockSize;

  UNUSED(pBuft);
}

// Should be changed to return device-specific host buffer type
// but that probably requires changes in mgs
ggml_backend_buffer_type_t ggml_backend_vk_host_buffer_type() {
  static struct ggml_backend_buffer_type vGgmlBackendVkBufferTypeHost = {
      /* .iface    = */ {
          /* .get_name         = */ fGgmlBackendVkHostBufferTypeName,
          /* .alloc_buffer     = */ fGgmlBackendVkHostBufferTypeAllocBuffer,
          /* .get_alignment    = */ fGgmlBackendVkHostBufferTypeGetAlignment,
          /* .get_max_size     = */ fGgmlBackendVkHostBufferTypeGetMaxSize,
          /* .get_alloc_size   = */ ggml_backend_cpu_buffer_type()->iface.get_alloc_size,
          /* .is_host          = */ ggml_backend_cpu_buffer_type()->iface.is_host,
      },
      /* .device   = */ ggml_backend_reg_dev_get(ggml_backend_vk_reg(), 0),
      /* .context  = */ nullptr,
  };

  // Make sure device 0 is initialized
  fGgmlVkInstanceInit();
  fGgmlVkGetDevice(0);

  return &vGgmlBackendVkBufferTypeHost;
}

// backend

static const char *fGgmlBackendVkName(ggml_backend_t pBackend) {
  ggml_backend_vk_context *vCtx = (ggml_backend_vk_context *)pBackend->context;

  return vCtx->name.c_str();
}

static void fGgmlBackendVkFree(ggml_backend_t pBackend) {
  ggml_backend_vk_context *ctx = (ggml_backend_vk_context *)pBackend->context;
  VK_LOG_DEBUG("ggml_backend_vk_free(" << ctx->name << ")");

  fGgmlVkCleanup(ctx);

  delete ctx;
  delete pBackend;
}

static ggml_backend_buffer_type_t fGgmlBackendVkGetDefaultBufferType(ggml_backend_t pBackend) {
  ggml_backend_vk_context *vCtx = (ggml_backend_vk_context *)pBackend->context;

  return &vCtx->device->vBufferType;
}

// Device buffer of the backend's GPU, whatever its buffer type (the default one or the lower priority cache one).
static bool fGgmlBackendVkBufferIsDeviceOf(ggml_backend_t pBackend, ggml_backend_buffer_t pBuffer) {
  if (!fGgmlBackendBufferIsVk(pBuffer)) {
    return false;
  }
  ggml_backend_vk_context *vCtx = (ggml_backend_vk_context *)pBackend->context;
  ggml_backend_vk_buffer_type_context *vBuftCtx = (ggml_backend_vk_buffer_type_context *)pBuffer->buft->context;
  return vBuftCtx->device == vCtx->device;
}

// Staging ring of the asynchronous uploads from host memory that the device cannot read directly: pageable memory
// such as the model mmap, from which the MoE expert cache and the expert prefetch of large micro-batches upload. The
// data is copied into this host-visible ring at once and the device copy is queued with the rest of the work, so an
// upload no longer submits its copy and waits for the device. Every submission that carries ring copies signals the
// staging semaphore, and the ring space of a copy is reused once the semaphore has reached its value.
static constexpr size_t cVkStagingRingBytes = 64ull * 1024 * 1024;
// A large upload goes through the ring in pieces, so writing a piece into the ring overlaps the device copy of the
// previous ones.
static constexpr size_t cVkStagingChunkBytes = 16ull * 1024 * 1024;
// The open submission is sent once it carries half of the ring: the device copies those bytes while the next ones are
// written into the other half.
static constexpr size_t cVkStagingFlushBytes = cVkStagingRingBytes / 2;
static constexpr size_t cVkStagingAlignment = 256;

// Creates the staging ring the first time an upload needs it. GGML_VK_STAGING_RING=0 keeps the single staging buffer
// that waits for the device after every upload, for diagnostics.
static bool fVkStagingReady(ggml_backend_vk_context *pCtx) {
  if (pCtx->vStagingRing) {
    return true;
  }
  if (pCtx->vStagingDisabled) {
    return false;
  }
  pCtx->vStagingDisabled = true;
  const char *vSetting = getenv("GGML_VK_STAGING_RING");
  if (vSetting != nullptr && strcmp(vSetting, "0") == 0) {
    return false;
  }
  try {
    if (!pCtx->vStagingSemaphore.s) {
      vk::SemaphoreTypeCreateInfo vTypeInfo{vk::SemaphoreType::eTimeline, 0};
      vk::SemaphoreCreateInfo vCreateInfo{};
      vCreateInfo.setPNext(&vTypeInfo);
      pCtx->vStagingSemaphore.s = pCtx->device->device.createSemaphore(vCreateInfo);
      pCtx->vStagingSemaphore.value = 0;
    }
    pCtx->vStagingRing =
        fGgmlVkCreateBuffer(pCtx->device, cVkStagingRingBytes,
                            {vk::MemoryPropertyFlagBits::eHostVisible | vk::MemoryPropertyFlagBits::eHostCoherent |
                                 vk::MemoryPropertyFlagBits::eHostCached,
                             vk::MemoryPropertyFlagBits::eHostVisible | vk::MemoryPropertyFlagBits::eHostCoherent});
  } catch (const vk::SystemError &vError) {
    GGML_LOG_WARN("ggml_vulkan: %s: no staging ring (%s), uploads from pageable memory wait for the device\n",
                  pCtx->name.c_str(), vError.what());
    return false;
  }
  if (pCtx->vStagingRing->ptr == nullptr) {
    fGgmlVkDestroyBuffer(pCtx->vStagingRing);
    return false;
  }
  pCtx->vStagingHead = 0;
  pCtx->vStagingDisabled = false;
  return true;
}

// Sends the open copy context, whose ring copies have not reached the queue yet, without waiting for the device.
static void fVkStagingFlush(ggml_backend_vk_context *pCtx) {
  if (pCtx->device->vAsyncUseTransferQueue) {
    if (fGgmlVkSubmitTransferCtx(pCtx)) {
      // the next synchronization makes the compute queue wait for the transfer semaphore
      pCtx->vSubmitPending = true;
    }
    return;
  }
  if (pCtx->compute_ctx.expired()) {
    return;
  }
  vk_context vComputeCtx = pCtx->compute_ctx.lock();
  if (!vComputeCtx->lOutMemcpys.empty()) {
    // a readback copies its data out once the context has finished, as the regular synchronization does
    fGgmlVkSynchronize(pCtx);
    return;
  }
  fGgmlVkCtxEnd(vComputeCtx);
  for (auto &vCopy : vComputeCtx->lInMemcpys) {
    memcpy(vCopy.dst, vCopy.src, vCopy.n);
  }
  vComputeCtx->lInMemcpys.clear();
  for (auto &vSet : vComputeCtx->lMemsets) {
    memset(vSet.dst, vSet.val, vSet.n);
  }
  vComputeCtx->lMemsets.clear();
  fGgmlVkSubmit(vComputeCtx, {});
  pCtx->vSubmitPending = true;
  pCtx->compute_ctx.reset();
}

// Frees the ring space of a copy that the device has done and makes its command buffer reusable, unless another
// submission already reuses it.
static void fVkStagingRelease(vk_staging_region &pRegion) {
  if (pRegion.vBuffer != nullptr && pRegion.vBuffer->in_use && pRegion.vBuffer->vUseCounter == pRegion.vBufferUse) {
    pRegion.vBuffer->in_use = false;
    pRegion.vBuffer->vBuf.reset();
  }
}

// Frees the ring space of the copies that the device has already done, without waiting.
static void fVkStagingRetireDone(ggml_backend_vk_context *pCtx) {
  if (pCtx->lLStagingRegions.empty()) {
    return;
  }
  const uint64_t cVDone = pCtx->device->device.getSemaphoreCounterValue(pCtx->vStagingSemaphore.s);
  while (!pCtx->lLStagingRegions.empty() && pCtx->lLStagingRegions.front().vValue <= cVDone) {
    fVkStagingRelease(pCtx->lLStagingRegions.front());
    pCtx->lLStagingRegions.pop_front();
  }
}

// Waits until the device has done the oldest copy of the ring and frees its space.
static void fVkStagingRetireOldest(ggml_backend_vk_context *pCtx) {
  vk_staging_region &vOldest = pCtx->lLStagingRegions.front();
  vk_context vContext = vOldest.vContext.lock();
  if (vContext && vContext->vSubmitCount == vOldest.vEpoch) {
    // the copy is still in the open context
    fVkStagingFlush(pCtx);
    if (vContext->vSubmitCount == vOldest.vEpoch) {
      // a context that is no longer open was discarded without being sent: its copy never runs
      pCtx->lLStagingRegions.pop_front();
      return;
    }
  }
  vk::Semaphore vSemaphore = pCtx->vStagingSemaphore.s;
  uint64_t vValue = vOldest.vValue;
  vk::SemaphoreWaitInfo vWaitInfo{vk::SemaphoreWaitFlags{}, vSemaphore, vValue};
  VK_CHECK(pCtx->device->device.waitSemaphores(vWaitInfo, UINT64_MAX), "staging ring");
  fVkStagingRelease(vOldest);
  pCtx->lLStagingRegions.pop_front();
}

// Reserves pBytes (at most cVkStagingChunkBytes after alignment) of the ring, waiting for the oldest copies while it
// is full, and returns their offset.
static size_t fVkStagingAlloc(ggml_backend_vk_context *pCtx, size_t pBytes) {
  const size_t cRingBytes = pCtx->vStagingRing->size;
  fVkStagingRetireDone(pCtx);
  for (;;) {
    if (pCtx->lLStagingRegions.empty()) {
      pCtx->vStagingHead = pBytes;
      return 0;
    }
    // The copies in flight use the ring from the oldest one (vTail) up to vHead, wrapping around its end.
    const size_t cVTail = pCtx->lLStagingRegions.front().vBegin;
    const size_t cVHead = pCtx->vStagingHead;
    if (cVHead > cVTail) {
      if (cRingBytes - cVHead >= pBytes) {
        pCtx->vStagingHead = cVHead + pBytes;
        return cVHead;
      }
      if (cVTail >= pBytes) {
        pCtx->vStagingHead = pBytes;
        return 0;
      }
    } else if (cVTail - cVHead >= pBytes) {
      pCtx->vStagingHead = cVHead + pBytes;
      return cVHead;
    }
    fVkStagingRetireOldest(pCtx);
  }
}

// Records that a copy just recorded in the open submission of pCpyCtx reads the ring from pOffset: the submission
// signals the next value of the staging semaphore, and it is sent once it carries cVkStagingFlushBytes of ring copies.
static void fVkStagingTrack(ggml_backend_vk_context *pCtx, vk_context &pCpyCtx, size_t pOffset, size_t pBytes) {
  vk_submission *vSubmission = pCpyCtx->s;
  const uint64_t cVValue = ++pCtx->vStagingSemaphore.value;
  bool vSignaled = false;
  for (auto &vSignal : vSubmission->lSignalSemaphores) {
    if (vSignal.s == pCtx->vStagingSemaphore.s) {
      vSignal.value = cVValue;
      vSignaled = true;
    }
  }
  if (!vSignaled) {
    vSubmission->lSignalSemaphores.push_back({pCtx->vStagingSemaphore.s, cVValue});
  }
  pCtx->lLStagingRegions.push_back(
      {pOffset, cVValue, pCpyCtx, pCpyCtx->vSubmitCount, vSubmission->buffer, vSubmission->buffer->vUseCounter});

  const bool cVSameSubmission = pCtx->vStagingSubmission == vSubmission &&
                                pCtx->vStagingSubmissionContext.lock() == pCpyCtx &&
                                pCtx->vStagingSubmissionEpoch == pCpyCtx->vSubmitCount;
  pCtx->vStagingSubmissionBytes = (cVSameSubmission ? pCtx->vStagingSubmissionBytes : 0) + pBytes;
  pCtx->vStagingSubmission = vSubmission;
  pCtx->vStagingSubmissionContext = pCpyCtx;
  pCtx->vStagingSubmissionEpoch = pCpyCtx->vSubmitCount;
  if (pCtx->vStagingSubmissionBytes >= cVkStagingFlushBytes) {
    fVkStagingFlush(pCtx);
    pCtx->vStagingSubmission = nullptr;
    pCtx->vStagingSubmissionBytes = 0;
  }
}

// Queues an upload from host memory that the device cannot read through the staging ring and returns without waiting
// for the device (see cVkStagingRingBytes). Rows of a 2D upload stay whole within a piece. Returns false when the ring
// cannot be used, before recording anything: the caller then takes the single staging buffer.
static bool fVkStagingWrite(ggml_backend_vk_context *pCtx, vk_buffer &pDst, size_t pDstOffset, const void *pData,
                            size_t pSize, size_t pNCopies, size_t pStrideTensor, size_t pStrideData) {
  if (pNCopies > 1 && pSize > cVkStagingChunkBytes) {
    return false;
  }
  if (!fVkStagingReady(pCtx)) {
    return false;
  }
  const size_t cRowsPerPiece = pNCopies > 1 ? std::max<size_t>(1, cVkStagingChunkBytes / pSize) : 1;
  const uint8_t *vSource = (const uint8_t *)pData;
  vk_submission *vPreviousSubmission = nullptr;
  size_t vRow = 0;       // first row of the next piece
  size_t vRowOffset = 0; // first byte of the next piece within a single row
  while (vRow < pNCopies) {
    size_t vRows = 1;
    size_t vBytes;
    if (pNCopies == 1) {
      vBytes = std::min(cVkStagingChunkBytes, pSize - vRowOffset);
    } else {
      vRows = std::min(cRowsPerPiece, pNCopies - vRow);
      vBytes = vRows * pSize;
    }
    const size_t cVOffset = fVkStagingAlloc(pCtx, fGgmlVkAlignSize(vBytes, cVkStagingAlignment));
    uint8_t *vStaging = (uint8_t *)pCtx->vStagingRing->ptr + cVOffset;

    std::vector<vk::BufferCopy> lLSlices;
    if (pNCopies == 1) {
      memcpy(vStaging, vSource + vRowOffset, vBytes);
      lLSlices.push_back({cVOffset, pDstOffset + vRowOffset, vBytes});
    } else {
      for (size_t vI = 0; vI < vRows; vI++) {
        memcpy(vStaging + vI * pSize, vSource + (vRow + vI) * pStrideData, pSize);
      }
      if (pSize == pStrideTensor) {
        lLSlices.push_back({cVOffset, pDstOffset + vRow * pStrideTensor, vBytes});
      } else {
        for (size_t vI = 0; vI < vRows; vI++) {
          lLSlices.push_back({cVOffset + vI * pSize, pDstOffset + (vRow + vI) * pStrideTensor, pSize});
        }
      }
    }

    // Waiting for ring space may have sent the open context, so the copy goes into the one that is open now. Its
    // first copy waits for the earlier work on the destination, as the single staging buffer does.
    vk_context vCpyCtx =
        pCtx->device->vAsyncUseTransferQueue ? fGgmlVkGetTransferCtx(pCtx) : fGgmlVkGetComputeCtx(pCtx);
    if (vCpyCtx->s != vPreviousSubmission) {
      fGgmlVkSyncBuffers(nullptr, vCpyCtx);
    }
    vCpyCtx->s->buffer->vBuf.copyBuffer(pCtx->vStagingRing->buffer, pDst->buffer, lLSlices);
    vPreviousSubmission = vCpyCtx->s;
    fVkStagingTrack(pCtx, vCpyCtx, cVOffset, vBytes);

    if (pNCopies == 1) {
      vRowOffset += vBytes;
      if (vRowOffset == pSize) {
        vRow = 1;
      }
    } else {
      vRow += vRows;
    }
  }
  return true;
}

static void fGgmlBackendVkSetTensor2dAsync(ggml_backend_t pBackend, ggml_tensor *pTensor, const void *pData,
                                           size_t pOffset, size_t size, size_t pNCopies, size_t pStrideTensor,
                                           size_t pStrideData) {
  VK_LOG_DEBUG("ggml_backend_vk_set_tensor_2d_async(" << size << ", " << pNCopies << ")");
  ggml_backend_vk_context *vCtx = (ggml_backend_vk_context *)pBackend->context;
  GGML_ASSERT((fGgmlBackendVkBufferIsDeviceOf(pBackend, pTensor->buffer) ||
               pTensor->buffer->buft == ggml_backend_vk_host_buffer_type()) &&
              "unsupported buffer type");

  if (size == 0) {
    return;
  }

  ggml_backend_vk_buffer_context *vBufCtx = (ggml_backend_vk_buffer_context *)pTensor->buffer->context;

  vk_context vCpyCtx;

  if (vCtx->device->vAsyncUseTransferQueue) {
    vCpyCtx = fGgmlVkGetTransferCtx(vCtx);
  } else {
    vCpyCtx = fGgmlVkGetComputeCtx(vCtx);
  }

  vk_buffer vBuf = vBufCtx->vDevBuffer;

  auto vDstOffset = fVkTensorOffset(pTensor) + pTensor->view_offs + pOffset;

  bool vRet = fGgmlVkBufferWrite2dAsync(vCpyCtx, vBuf, vDstOffset, pData, pStrideData, pStrideTensor, size, pNCopies);

  // Memory the device cannot read (pageable memory) goes through the staging ring without waiting for the device.
  if (!vRet && !fVkStagingWrite(vCtx, vBuf, vDstOffset, pData, size, pNCopies, pStrideTensor, pStrideData)) {
    const size_t cStagingSize = size * pNCopies;
    fGgmlVkEnsureSyncStagingBuffer(vCtx, cStagingSize);
    fGgmlVkSyncBuffers(nullptr, vCpyCtx);

    std::vector<vk::BufferCopy> lSlices(1);
    if (size == pStrideTensor) {
      lSlices[0].srcOffset = 0;
      lSlices[0].dstOffset = vDstOffset;
      lSlices[0].size = cStagingSize;
    } else {
      lSlices.resize(pNCopies);
      for (size_t vI = 0; vI < pNCopies; vI++) {
        lSlices[vI].srcOffset = vI * size;
        lSlices[vI].dstOffset = vDstOffset + vI * pStrideTensor;
        lSlices[vI].size = size;
      }
    }

    vCpyCtx->s->buffer->vBuf.copyBuffer(vCtx->vSyncStaging->buffer, vBuf->buffer, lSlices);

    if (size == pStrideData) {
      fDeferredMemcpy(vCtx->vSyncStaging->ptr, pData, cStagingSize, &vCpyCtx->lInMemcpys);
    } else {
      for (size_t vI = 0; vI < pNCopies; vI++) {
        fDeferredMemcpy((uint8_t *)vCtx->vSyncStaging->ptr + vI * size, (const uint8_t *)pData + vI * pStrideData, size,
                        &vCpyCtx->lInMemcpys);
      }
    }
    fGgmlVkSynchronize(vCtx);
  }
}

static void fGgmlBackendVkSetTensorAsync(ggml_backend_t pBackend, ggml_tensor *pTensor, const void *pData,
                                         size_t pOffset, size_t size) {
  VK_LOG_DEBUG("ggml_backend_vk_set_tensor_async(" << size << ")");
  fGgmlBackendVkSetTensor2dAsync(pBackend, pTensor, pData, pOffset, size, 1, size, size);
}

static void fGgmlBackendVkGetTensor2dAsync(ggml_backend_t pBackend, const ggml_tensor *pTensor, void *pData,
                                           size_t pOffset, size_t size, size_t pNCopies, size_t pStrideTensor,
                                           size_t pStrideData) {
  VK_LOG_DEBUG("ggml_backend_vk_get_tensor_2d_async(" << size << ", " << pNCopies << ")");
  ggml_backend_vk_context *vCtx = (ggml_backend_vk_context *)pBackend->context;
  GGML_ASSERT((fGgmlBackendVkBufferIsDeviceOf(pBackend, pTensor->buffer) ||
               pTensor->buffer->buft == ggml_backend_vk_host_buffer_type()) &&
              "unsupported buffer type");

  if (size == 0) {
    return;
  }

  ggml_backend_vk_buffer_context *vBufCtx = (ggml_backend_vk_buffer_context *)pTensor->buffer->context;

  vk_context vComputeCtx = fGgmlVkGetComputeCtx(vCtx);

  vk_buffer vBuf = vBufCtx->vDevBuffer;

  auto vSrcOffset = fVkTensorOffset(pTensor) + pTensor->view_offs + pOffset;
  bool vRet =
      fGgmlVkBufferRead2dAsync(vComputeCtx, vBuf, vSrcOffset, pData, pStrideTensor, pStrideData, size, pNCopies);

  if (!vRet) {
    const size_t cStagingSize = size * pNCopies;
    fGgmlVkEnsureSyncStagingBuffer(vCtx, cStagingSize);
    fGgmlVkSyncBuffers(nullptr, vComputeCtx);

    std::vector<vk::BufferCopy> lSlices(1);
    if (size == pStrideTensor) {
      lSlices[0].srcOffset = vSrcOffset;
      lSlices[0].dstOffset = 0;
      lSlices[0].size = cStagingSize;
    } else {
      lSlices.resize(pNCopies);
      for (size_t vI = 0; vI < pNCopies; vI++) {
        lSlices[vI].srcOffset = vSrcOffset + vI * pStrideTensor;
        lSlices[vI].dstOffset = vI * size;
        lSlices[vI].size = size;
      }
    }

    vComputeCtx->s->buffer->vBuf.copyBuffer(vBuf->buffer, vCtx->vSyncStaging->buffer, lSlices);

    if (size == pStrideData) {
      fDeferredMemcpy(pData, vCtx->vSyncStaging->ptr, cStagingSize, &vComputeCtx->lOutMemcpys);
    } else {
      for (size_t vI = 0; vI < pNCopies; vI++) {
        fDeferredMemcpy((uint8_t *)pData + vI * pStrideData, (const uint8_t *)vCtx->vSyncStaging->ptr + vI * size, size,
                        &vComputeCtx->lOutMemcpys);
      }
    }
    fGgmlVkSynchronize(vCtx);
  }
}

static void fGgmlBackendVkGetTensorAsync(ggml_backend_t pBackend, const ggml_tensor *pTensor, void *pData,
                                         size_t pOffset, size_t size) {
  VK_LOG_DEBUG("ggml_backend_vk_get_tensor_async(" << size << ")");
  fGgmlBackendVkGetTensor2dAsync(pBackend, pTensor, pData, pOffset, size, 1, size, size);
}

static bool fGgmlBackendVkCpyTensorAsync(ggml_backend_t pBackendSrc, ggml_backend_t pBackendDst, const ggml_tensor *src,
                                         ggml_tensor *dst) {
  VK_LOG_DEBUG("ggml_backend_vk_cpy_tensor_async(" << src << " -> " << dst << ", size=" << ggml_nbytes(src) << ")");
  ggml_backend_vk_context *vCtx = (ggml_backend_vk_context *)pBackendDst->context;

  // Skip zero-size tensors
  if (ggml_nbytes(src) == 0) {
    return true;
  }

  if (!fGgmlBackendVkBufferIsDeviceOf(pBackendDst, dst->buffer)) {
    return false;
  }

  ggml_backend_vk_buffer_context *vDstBufCtx = (ggml_backend_vk_buffer_context *)dst->buffer->context;
  vk_buffer vDstBuf = vDstBufCtx->vDevBuffer;

  if (fGgmlBackendBufferIsVk(src->buffer)) {
    ggml_backend_vk_buffer_context *vSrcBufCtx = (ggml_backend_vk_buffer_context *)src->buffer->context;

    // Async copy only works within the same device
    if (vSrcBufCtx->vDevBuffer->device != vDstBuf->device) {
      return false;
    }

    vk_context vComputeCtx = fGgmlVkGetComputeCtx(vCtx);

    fGgmlVkBufferCopyAsync(vComputeCtx, vDstBuf, fVkTensorOffset(dst) + dst->view_offs, vSrcBufCtx->vDevBuffer,
                           fVkTensorOffset(src) + src->view_offs, ggml_nbytes(src));
    return true;
  }

  if (ggml_backend_buffer_is_host(src->buffer)) {
    vk_buffer vPinnedBuf = nullptr;
    size_t vPinnedOffset = 0;
    fGgmlVkHostGet(vCtx->device, src->data, vPinnedBuf, vPinnedOffset);
    if (vPinnedBuf == nullptr) {
      return false;
    }

    vk_context vCpyCtx;
    if (vCtx->device->vAsyncUseTransferQueue) {
      vCpyCtx = fGgmlVkGetTransferCtx(vCtx);
    } else {
      vCpyCtx = fGgmlVkGetComputeCtx(vCtx);
    }

    return fGgmlVkBufferWriteAsync(vCpyCtx, vDstBuf, fVkTensorOffset(dst) + dst->view_offs, src->data,
                                   ggml_nbytes(src));
  }

  GGML_UNUSED(pBackendSrc);
  return false;
}

static void fGgmlVkSynchronize(ggml_backend_vk_context *pCtx) {
  VK_LOG_DEBUG("ggml_vk_synchronize()");

  bool vDoTransfer = !pCtx->compute_ctx.expired();

  if (fGgmlVkSubmitTransferCtx(pCtx)) {
    pCtx->vSubmitPending = true;
  }

  vk_context vComputeCtx;
  vk_command_buffer *vCmdBuf = nullptr;
  if (vDoTransfer) {
    vComputeCtx = pCtx->compute_ctx.lock();
    if (vComputeCtx->s) {
      vCmdBuf = vComputeCtx->s->buffer;
    }

    fGgmlVkCtxEnd(vComputeCtx);

    for (auto &vCpy : vComputeCtx->lInMemcpys) {
      memcpy(vCpy.dst, vCpy.src, vCpy.n);
    }

    fGgmlVkSubmit(vComputeCtx, {});
    pCtx->vSubmitPending = true;
  }

  if (pCtx->vSubmitPending) {
    if (pCtx->device->vAsyncUseTransferQueue &&
        pCtx->vTransferSemaphoreLastSubmitted < pCtx->vTransferSemaphore.value) {
      vk::TimelineSemaphoreSubmitInfo vTlInfo{
          1,
          &pCtx->vTransferSemaphore.value,
          0,
          nullptr,
      };
      vk::PipelineStageFlags vStage = pCtx->device->vTransferQueue->vStageFlags;
      vk::SubmitInfo vSi{
          1, &pCtx->vTransferSemaphore.s, &vStage, 0, nullptr, 0, nullptr,
      };
      vSi.setPNext(&vTlInfo);
      pCtx->device->vComputeQueue->vHandle->mSubmit({vSi}, pCtx->fence);
      pCtx->vTransferSemaphoreLastSubmitted = pCtx->vTransferSemaphore.value;
    } else {
      pCtx->device->vComputeQueue->vHandle->mSubmit({}, pCtx->fence);
    }
    fGgmlVkWaitForFence(pCtx);
    pCtx->vSubmitPending = false;
    if (vCmdBuf) {
      vCmdBuf->in_use = false;
      vCmdBuf->vBuf.reset();
    }
  }

  if (vDoTransfer) {
    for (auto &vCpy : vComputeCtx->lOutMemcpys) {
      memcpy(vCpy.dst, vCpy.src, vCpy.n);
    }
    pCtx->compute_ctx.reset();
  }
}

static void fGgmlBackendVkSynchronize(ggml_backend_t pBackend) {
  VK_LOG_DEBUG("ggml_backend_vk_synchronize()");
  ggml_backend_vk_context *vCtx = (ggml_backend_vk_context *)pBackend->context;

  fGgmlVkSynchronize(vCtx);

  fGgmlVkGraphCleanup(vCtx);
}

static bool fGgmlVkIsEmpty(ggml_tensor *pNode) {
  return ggml_is_empty(pNode) || pNode->op == GGML_OP_NONE || pNode->op == GGML_OP_RESHAPE ||
         pNode->op == GGML_OP_TRANSPOSE || pNode->op == GGML_OP_VIEW || pNode->op == GGML_OP_PERMUTE;
}

// Whether the MUL at pMulIdx can consume the unary op at pUnaryIdx in one fused dispatch (aPipelineUnaryMul).
static bool fGgmlVkCanFuseUnaryMul(const struct ggml_cgraph *pCgraph, int pUnaryIdx, int pMulIdx) {
  const ggml_tensor *vUnary = pCgraph->nodes[pUnaryIdx];
  const ggml_tensor *vMul = pCgraph->nodes[pMulIdx];

  if (fGgmlVkUnaryMulOpIndex(ggml_get_unary_op(vUnary)) < 0) {
    return false;
  }
  if (vUnary->type != GGML_TYPE_F32 && vUnary->type != GGML_TYPE_F16) {
    return false;
  }
  if (vUnary->type != vMul->type) {
    return false;
  }
  if (vMul->src[0] != vUnary && vMul->src[1] != vUnary) {
    return false;
  }
  const ggml_tensor *vOther = (vMul->src[0] == vUnary) ? vMul->src[1] : vMul->src[0];
  if (vOther == nullptr || vOther->type != vUnary->type) {
    return false;
  }
  if (!ggml_is_contiguous_1(vOther) || !ggml_is_contiguous_1(vUnary->src[0])) {
    return false;
  }
  // fastmod needs src to tile into dst
  if (vMul->src[0] == vUnary) {
    return ggml_can_repeat(vOther, vUnary);
  }
  return ggml_can_repeat(vUnary, vMul->src[0]);
}

static bool fGgmlVkCanFuse(const ggml_backend_vk_context *pCtx, const struct ggml_cgraph *pCgraph, int pNodeIdx,
                           std::initializer_list<enum ggml_op> pOps) {
  if (pOps.size() == 2 && pOps.begin()[0] == GGML_OP_UNARY && pOps.begin()[1] == GGML_OP_MUL) {
    return ggml_can_fuse_subgraph(pCgraph, pNodeIdx, {GGML_OP_UNARY, GGML_OP_MUL}, {pNodeIdx + 1}) &&
           fGgmlVkCanFuseUnaryMul(pCgraph, pNodeIdx, pNodeIdx + 1);
  }

  if (!ggml_can_fuse(pCgraph, pNodeIdx, pOps)) {
    return false;
  }

  if (pOps.size() == 2 && pOps.begin()[0] == GGML_OP_RMS_NORM && pOps.begin()[1] == GGML_OP_MUL) {
    // additional constraints specific to this fusion
    const ggml_tensor *vRmsNorm = pCgraph->nodes[pNodeIdx];
    const ggml_tensor *vMul = pCgraph->nodes[pNodeIdx + 1];

    GGML_ASSERT(vRmsNorm->src[0]->type == GGML_TYPE_F32);
    GGML_ASSERT(vRmsNorm->type == GGML_TYPE_F32);
    // rms_norm only supports f32
    if (vMul->src[0]->type != GGML_TYPE_F32 || vMul->src[1]->type != GGML_TYPE_F32 || vMul->type != GGML_TYPE_F32) {
      return false;
    }
    // if rms_norm is the B operand, then we don't handle broadcast
    if (vRmsNorm == vMul->src[1] && !ggml_are_same_shape(vMul->src[0], vRmsNorm)) {
      return false;
    }
    // rms_norm shader assumes contiguous rows
    if (!ggml_is_contiguous_rows(vMul->src[0]) || !ggml_is_contiguous_rows(vMul->src[1])) {
      return false;
    }
  }
  auto const &fMmAddOk = [&](const ggml_tensor *pMul, const ggml_tensor *pAdd) {
    const ggml_tensor *vBias = pAdd->src[0] == pMul ? pAdd->src[1] : pAdd->src[0];

    // mat-vec only
    if (ggml_nrows(pMul) != 1) {
      return false;
    }
    // shaders assume the types match
    if (pMul->type != vBias->type) {
      return false;
    }
    // shaders reuse the D shape for bias
    if (!ggml_are_same_shape(pMul, vBias) || !ggml_are_same_stride(pMul, vBias)) {
      return false;
    }
    // unaligned bias isn't handled
    if (fGetMisalignBytes(pCtx, vBias) != 0) {
      return false;
    }
    return true;
  };

  if ((pOps.size() == 2 || pOps.size() == 3) && pOps.begin()[0] == GGML_OP_MUL_MAT && pOps.begin()[1] == GGML_OP_ADD) {
    // additional constraints specific to this fusion
    const ggml_tensor *vMul = pCgraph->nodes[pNodeIdx];
    const ggml_tensor *vAdd = pCgraph->nodes[pNodeIdx + 1];

    if (!fMmAddOk(vMul, vAdd)) {
      return false;
    }
    if (pOps.size() == 3) {
      if (pOps.begin()[2] != GGML_OP_ADD) {
        return false;
      }
      if (!fMmAddOk(vAdd, pCgraph->nodes[pNodeIdx + 2])) {
        return false;
      }
    }
  }

  auto const &fMmidMulOk = [&](const ggml_tensor *pMmid, const ggml_tensor *pMul) {
    const ggml_tensor *vScale = pMul->src[1];

    if (pMmid != pMul->src[0]) {
      return false;
    }
    // mat-vec only
    if (!fGgmlVkUseMulMatVecId(pCgraph, pNodeIdx)) {
      return false;
    }
    // shaders assume the types match
    if (pMmid->type != vScale->type) {
      return false;
    }
    // shaders assume the bias is contiguous
    if (!ggml_is_contiguous(vScale)) {
      return false;
    }
    // unaligned bias isn't handled
    if (fGetMisalignBytes(pCtx, vScale) != 0) {
      return false;
    }
    // shader only indexes by expert index
    if (vScale->ne[0] != 1 || vScale->ne[1] != pMul->ne[1] || vScale->ne[2] != 1 || vScale->ne[3] != 1) {
      return false;
    }
    return true;
  };

  if ((pOps.size() == 2 || pOps.size() == 3) && pOps.begin()[0] == GGML_OP_MUL_MAT_ID &&
      pOps.begin()[1] == GGML_OP_ADD_ID) {
    // additional constraints specific to this fusion
    const ggml_tensor *vMul = pCgraph->nodes[pNodeIdx];
    const ggml_tensor *vAdd = pCgraph->nodes[pNodeIdx + 1];
    const ggml_tensor *vBias = vAdd->src[1];

    if (vMul != vAdd->src[0]) {
      return false;
    }
    // mat-vec only
    if (!fGgmlVkUseMulMatVecId(pCgraph, pNodeIdx)) {
      return false;
    }
    // shaders assume the types match
    if (vMul->type != vBias->type) {
      return false;
    }
    // shaders assume the bias is contiguous
    if (!ggml_is_contiguous(vBias)) {
      return false;
    }
    // the ID tensor must be the same for mul_mat_id and add_id
    if (vMul->src[2] != vAdd->src[2]) {
      return false;
    }
    // unaligned bias isn't handled
    if (fGetMisalignBytes(pCtx, vBias) != 0) {
      return false;
    }

    if (pOps.size() == 3) {
      if (pOps.begin()[2] != GGML_OP_MUL) {
        return false;
      }
      const ggml_tensor *vMul = pCgraph->nodes[pNodeIdx + 2];
      return fMmidMulOk(vAdd, vMul);
    }
  }

  if (pOps.size() == 2 && pOps.begin()[0] == GGML_OP_MUL_MAT_ID && pOps.begin()[1] == GGML_OP_MUL) {
    // additional constraints specific to this fusion
    const ggml_tensor *vMmid = pCgraph->nodes[pNodeIdx];
    const ggml_tensor *vMul = pCgraph->nodes[pNodeIdx + 1];

    if (!fMmidMulOk(vMmid, vMul)) {
      return false;
    }
  }

  return true;
}

// Match SSM_CONV + UNARY(SILU) or SSM_CONV + ADD + UNARY(SILU). num_extra is 1 or 2.
static bool fGgmlVkCanFuseSsmConv(const ggml_backend_vk_context *pCtx, const struct ggml_cgraph *pCgraph, int pNodeIdx,
                                  int pNumExtra) {
  const ggml_tensor *vConv = pCgraph->nodes[pNodeIdx];
  if (vConv->op != GGML_OP_SSM_CONV) {
    return false;
  }

  const ggml_tensor *vSilu = nullptr;
  const ggml_tensor *vBias = nullptr;

  if (pNumExtra == 1) {
    if (!ggml_can_fuse(pCgraph, pNodeIdx, {GGML_OP_SSM_CONV, GGML_OP_UNARY})) {
      return false;
    }
    vSilu = pCgraph->nodes[pNodeIdx + 1];
  } else if (pNumExtra == 2) {
    if (!ggml_can_fuse(pCgraph, pNodeIdx, {GGML_OP_SSM_CONV, GGML_OP_ADD, GGML_OP_UNARY})) {
      return false;
    }
    const ggml_tensor *vAdd = pCgraph->nodes[pNodeIdx + 1];
    vSilu = pCgraph->nodes[pNodeIdx + 2];
    vBias = (vAdd->src[0] == vConv) ? vAdd->src[1] : vAdd->src[0];

    if (vBias->type != GGML_TYPE_F32 || !ggml_is_contiguous(vBias)) {
      return false;
    }
    // bias must be channel-wise (one element per channel of the conv output)
    if (ggml_nelements(vBias) != vConv->ne[0] || vBias->ne[0] != vConv->ne[0]) {
      return false;
    }
    if (vAdd->type != GGML_TYPE_F32) {
      return false;
    }
    // The shader doesn't apply per-tensor offsets, so reject misaligned bias.
    if (fGetMisalignBytes(pCtx, vBias) != 0) {
      return false;
    }
  } else {
    return false;
  }

  if (ggml_get_unary_op(vSilu) != GGML_UNARY_OP_SILU) {
    return false;
  }
  if (vConv->type != GGML_TYPE_F32 || vSilu->type != GGML_TYPE_F32) {
    return false;
  }
  // The shader writes to the fused dst using its own strides, but the push constants don't
  // carry a per-tensor offset, so the binding must be naturally aligned.
  if (fGetMisalignBytes(pCtx, vSilu) != 0) {
    return false;
  }
  return true;
}

// AMAX_POW2 followed by the MUL of the expert weights by its factor and the DIV of its rows (pMode 2), or by the DIV
// only (pMode 1)
static bool fGgmlVkCanFuseAmaxPow2(ggml_backend_vk_context *pCtx, const struct ggml_cgraph *pCgraph, int pNodeIdx,
                                   int pMode) {
  const ggml_tensor *vAmax = pCgraph->nodes[pNodeIdx];
  if (vAmax->op != GGML_OP_AMAX_POW2) {
    return false;
  }
  if (pMode == 2) {
    if (!ggml_can_fuse_subgraph(pCgraph, pNodeIdx, amax_pow2_mul_div_pattern, {pNodeIdx + 1, pNodeIdx + 2})) {
      return false;
    }
  } else if (!ggml_can_fuse_subgraph(pCgraph, pNodeIdx, amax_pow2_div_pattern, {pNodeIdx, pNodeIdx + 1})) {
    return false;
  }
  const ggml_tensor *vX = vAmax->src[0];
  const ggml_tensor *vDiv = pCgraph->nodes[pNodeIdx + pMode];
  if (vX->type != GGML_TYPE_F32 || !ggml_is_contiguous(vX) || !ggml_is_contiguous(vAmax) ||
      vDiv->type != GGML_TYPE_F32 || vDiv->src[0] != vX || vDiv->src[1] != vAmax || !ggml_is_contiguous(vDiv) ||
      !ggml_are_same_shape(vDiv, vX)) {
    return false;
  }
  if (fGetMisalignBytes(pCtx, vX) != 0 || fGetMisalignBytes(pCtx, vAmax) != 0 || fGetMisalignBytes(pCtx, vDiv) != 0) {
    return false;
  }
  if (pMode == 2) {
    const ggml_tensor *vMul = pCgraph->nodes[pNodeIdx + 1];
    const ggml_tensor *vW = vMul->src[0];
    if (vMul->src[1] != vAmax || vW->type != GGML_TYPE_F32 || vMul->type != GGML_TYPE_F32 ||
        !ggml_are_same_shape(vW, vAmax) || !ggml_are_same_shape(vMul, vAmax) || !ggml_is_contiguous(vW) ||
        !ggml_is_contiguous(vMul) || fGetMisalignBytes(pCtx, vW) != 0 || fGetMisalignBytes(pCtx, vMul) != 0) {
      return false;
    }
  }
  return true;
}

static bool fGgmlVkCanFuseTopkMoe(ggml_backend_vk_context *pCtx, const struct ggml_cgraph *pCgraph, int pNodeIdx,
                                  topk_moe_mode pMode) {

  const ggml_tensor *vSoftmax;
  const ggml_tensor *vWeights;
  const ggml_tensor *vGetRows;
  const ggml_tensor *vArgsort;

  switch (pMode) {
  case TOPK_MOE_EARLY_SOFTMAX_NORM:
    vSoftmax = pCgraph->nodes[pNodeIdx + 0];
    vWeights = pCgraph->nodes[pNodeIdx + 9];
    vGetRows = pCgraph->nodes[pNodeIdx + 4];
    vArgsort = pCgraph->nodes[pNodeIdx + 2];
    break;
  case TOPK_MOE_SIGMOID_NORM_BIAS:
    vSoftmax = pCgraph->nodes[pNodeIdx + 0]; // really sigmoid
    vWeights = pCgraph->nodes[pNodeIdx + 10];
    vGetRows = pCgraph->nodes[pNodeIdx + 5];
    vArgsort = pCgraph->nodes[pNodeIdx + 3];
    if (ggml_get_unary_op(vSoftmax) != GGML_UNARY_OP_SIGMOID) {
      return false;
    }
    // bias is expected to be 1D
    if (ggml_nrows(pCgraph->nodes[pNodeIdx + 2]->src[1]) != 1 ||
        !ggml_is_contiguous(pCgraph->nodes[pNodeIdx + 2]->src[1])) {
      return false;
    }
    // sigmoid fusion seems to generate infinities on moltenvk
    if (pCtx->device->vDriverId == vk::DriverId::eMoltenvk) {
      return false;
    }
    break;
  case TOPK_MOE_SIGMOID_NORM:
    vSoftmax = pCgraph->nodes[pNodeIdx + 0]; // really sigmoid
    vWeights = pCgraph->nodes[pNodeIdx + 9];
    vGetRows = pCgraph->nodes[pNodeIdx + 4];
    vArgsort = pCgraph->nodes[pNodeIdx + 2];
    if (ggml_get_unary_op(vSoftmax) != GGML_UNARY_OP_SIGMOID) {
      return false;
    }
    // sigmoid fusion seems to generate infinities on moltenvk
    if (pCtx->device->vDriverId == vk::DriverId::eMoltenvk) {
      return false;
    }
    break;
  case TOPK_MOE_SQRT_SOFTPLUS_NORM_BIAS:
    vSoftmax = pCgraph->nodes[pNodeIdx + 0]; // really softplus
    vWeights = pCgraph->nodes[pNodeIdx + 11];
    vGetRows = pCgraph->nodes[pNodeIdx + 6];
    vArgsort = pCgraph->nodes[pNodeIdx + 4];
    if (ggml_get_unary_op(vSoftmax) != GGML_UNARY_OP_SOFTPLUS) {
      return false;
    }
    // bias is expected to be 1D
    if (ggml_nrows(pCgraph->nodes[pNodeIdx + 3]->src[1]) != 1 ||
        !ggml_is_contiguous(pCgraph->nodes[pNodeIdx + 3]->src[1])) {
      return false;
    }
    break;
  case TOPK_MOE_EARLY_SOFTMAX:
    vSoftmax = pCgraph->nodes[pNodeIdx + 0];
    vWeights = pCgraph->nodes[pNodeIdx + 4];
    vGetRows = pCgraph->nodes[pNodeIdx + 4];
    vArgsort = pCgraph->nodes[pNodeIdx + 2];
    break;
  case TOPK_MOE_LATE_SOFTMAX:
    vSoftmax = pCgraph->nodes[pNodeIdx + 4];
    vWeights = pCgraph->nodes[pNodeIdx + 5];
    vGetRows = pCgraph->nodes[pNodeIdx + 2];
    vArgsort = pCgraph->nodes[pNodeIdx + 0];
    break;
  default:
    return false;
  }

  ggml_tensor *vProbs = vGetRows->src[0];
  if (vProbs->op != GGML_OP_RESHAPE) {
    return false;
  }
  vProbs = vProbs->src[0];
  ggml_tensor *vSelectionProbs = vArgsort->src[0];

  if (vProbs != vSelectionProbs && pMode != TOPK_MOE_SIGMOID_NORM_BIAS && pMode != TOPK_MOE_SQRT_SOFTPLUS_NORM_BIAS) {
    return false;
  }

  if (!ggml_is_contiguous(vSoftmax->src[0]) || !ggml_is_contiguous(vWeights)) {
    return false;
  }

  if (vSoftmax->op == GGML_OP_SOFT_MAX) {
    const float *vOpParams = (const float *)vSoftmax->op_params;

    float vScale = vOpParams[0];
    float vMaxBias = vOpParams[1];

    if (vScale != 1.0f || vMaxBias != 0.0f) {
      return false;
    }

    // don't fuse when masks or sinks are present
    if (vSoftmax->src[1] || vSoftmax->src[2]) {
      return false;
    }
  }

  const int cNExpert = vSoftmax->ne[0];
  if (cNExpert > (1 << (num_topk_moe_pipelines - 1))) {
    return false;
  }

  if (!pCtx->device->vSubgroupArithmetic || !pCtx->device->vSubgroupShuffle ||
      !pCtx->device->vSubgroupRequireFullSupport || pCtx->device->vDisableFusion) {
    return false;
  }

  return true;
}

static bool fGgmlVkCanFuseRopeSetRows(ggml_backend_vk_context *pCtx, const struct ggml_cgraph *pCgraph, int pNodeIdx) {
  GGML_UNUSED(pCtx);
  const ggml_tensor *vRope = pCgraph->nodes[pNodeIdx + 0];
  const ggml_tensor *vView = pCgraph->nodes[pNodeIdx + 1];
  const ggml_tensor *vSetRows = pCgraph->nodes[pNodeIdx + 2];

  // ne3 not tested
  if (vRope->src[0]->ne[3] != 1) {
    return false;
  }

  if (vSetRows->type != GGML_TYPE_F32 && vSetRows->type != GGML_TYPE_F16) {
    return false;
  }

  if (vSetRows->src[1]->type != GGML_TYPE_I64) {
    return false;
  }

  // The view should flatten two dims of rope into one dim
  if (!ggml_is_contiguous(vView) || vView->ne[0] != vRope->ne[0] * vRope->ne[1]) {
    return false;
  }

  // Only norm/neox/mrope shaders have the fusion code
  const int cMode = ((const int32_t *)vRope->op_params)[2];
  if (cMode != GGML_ROPE_TYPE_NORMAL && cMode != GGML_ROPE_TYPE_NEOX && cMode != GGML_ROPE_TYPE_MROPE) {
    return false;
  }

  return true;
}

// Pattern check for the 5-op Snake fusion: mul -> sin -> sqr -> mul -> add.
// Verifies the chain shape, the closure x_in_add == x_in_mul0, and that
// the broadcast operands a and inv_b share a [1, C] layout.
static bool fGgmlVkCanFuseHcPostGate(const struct ggml_cgraph *pCgraph, int pNodeIdx) {
  const ggml_tensor *vScaleIn = pCgraph->nodes[pNodeIdx];
  const ggml_tensor *vSigmoid = pCgraph->nodes[pNodeIdx + 1];
  const ggml_tensor *vScaleOut = pCgraph->nodes[pNodeIdx + 2];

  // the shader folds scale -> sigmoid -> scale; a bias on either scale is not handled
  return ggml_get_unary_op(vSigmoid) == GGML_UNARY_OP_SIGMOID && ggml_get_op_params_f32(vScaleIn, 1) == 0.0f &&
         ggml_get_op_params_f32(vScaleOut, 1) == 0.0f && vScaleIn->src[0]->type == GGML_TYPE_F32 &&
         ggml_are_same_shape(vScaleIn->src[0], vScaleOut);
}

static bool fGgmlVkCanFuseSnake(ggml_backend_vk_context *pCtx, const struct ggml_cgraph *pCgraph, int pNodeIdx) {
  GGML_UNUSED(pCtx);
  if (!ggml_can_fuse(pCgraph, pNodeIdx, snake_pattern)) {
    return false;
  }

  const ggml_tensor *vMul0 = pCgraph->nodes[pNodeIdx + 0];
  const ggml_tensor *vSinNode = pCgraph->nodes[pNodeIdx + 1];
  const ggml_tensor *vSqr = pCgraph->nodes[pNodeIdx + 2];
  const ggml_tensor *vMul1 = pCgraph->nodes[pNodeIdx + 3];
  const ggml_tensor *vAdd = pCgraph->nodes[pNodeIdx + 4];

  const ggml_tensor *vX = ggml_are_same_shape(vMul0, vMul0->src[0]) ? vMul0->src[0] : vMul0->src[1];
  const ggml_tensor *vA = (vX == vMul0->src[0]) ? vMul0->src[1] : vMul0->src[0];

  const ggml_tensor *vInvB = (vMul1->src[0] == vSqr) ? vMul1->src[1] : vMul1->src[0];
  const ggml_tensor *vXInAdd = (vAdd->src[0] == vMul1) ? vAdd->src[1] : vAdd->src[0];

  if (vXInAdd != vX) {
    return false;
  }
  if (vX->type != GGML_TYPE_F32 && vX->type != GGML_TYPE_F16 && vX->type != GGML_TYPE_BF16) {
    return false;
  }
  // Shader bindings: data_a is A_TYPE so it follows x's precision, while
  // data_b and data_c are hardcoded float, so the broadcast operands must
  // be F32 regardless of x's type.
  if (vA->type != GGML_TYPE_F32)
    return false;
  if (vInvB->type != GGML_TYPE_F32)
    return false;
  // Chain intermediates and output share x's precision (single A_TYPE / D_TYPE pipeline).
  if (vMul0->type != vX->type)
    return false;
  if (vSinNode->type != vX->type)
    return false;
  if (vSqr->type != vX->type)
    return false;
  if (vMul1->type != vX->type)
    return false;
  if (vAdd->type != vX->type)
    return false;
  if (!ggml_are_same_shape(vA, vInvB)) {
    return false;
  }
  if (vA->ne[0] != 1 || vA->ne[1] != vX->ne[1]) {
    return false;
  }
  // Dispatch is 2D over (ne0, ne1), so x and add must be 2D and a / inv_b
  // must collapse to [1, C, 1, 1]. Higher dims are not handled by the shader.
  if (vX->ne[2] != 1 || vX->ne[3] != 1)
    return false;
  if (vAdd->ne[2] != 1 || vAdd->ne[3] != 1)
    return false;
  if (vA->ne[2] != 1 || vA->ne[3] != 1)
    return false;
  if (vInvB->ne[2] != 1 || vInvB->ne[3] != 1)
    return false;
  // Shader uses idx = i0 + i1 * ne0 and reads data_b[i1] / data_c[i1],
  // so every operand must be contiguous.
  if (!ggml_is_contiguous(vX) || !ggml_is_contiguous(vAdd) || !ggml_is_contiguous(vA) || !ggml_is_contiguous(vInvB)) {
    return false;
  }
  return true;
}

// Check whether the tensors overlap in memory.
// Fusions can potentially overwrite src tensors in ways that are not prevented
// by ggml-alloc. If the fusion src is being applied in a way that's elementwise
// with the destination, then it's OK for them to overlap if they are exactly equal.
static bool fGgmlVkTensorsOverlap(const ggml_tensor *pA, const ggml_tensor *pB, bool pElementwise) {
  ggml_backend_vk_buffer_context *vABufCtx = (ggml_backend_vk_buffer_context *)pA->buffer->context;
  vk_buffer vABuf = vABufCtx->vDevBuffer;
  ggml_backend_vk_buffer_context *vBBufCtx = (ggml_backend_vk_buffer_context *)pB->buffer->context;
  vk_buffer vBBuf = vBBufCtx->vDevBuffer;
  if (vABuf == vBBuf) {
    auto vABase = fVkTensorOffset(pA) + pA->view_offs;
    auto vASize = ggml_nbytes(pA);
    auto vBBase = fVkTensorOffset(pB) + pB->view_offs;
    auto vBSize = ggml_nbytes(pB);

    if (pElementwise && vABase == vBBase && vASize == vBSize) {
      return false;
    }

    if ((vBBase <= vABase && vABase < vBBase + vBSize) || (vABase <= vBBase && vBBase < vABase + vASize)) {
      return true;
    }
  }
  return false;
}

static bool fGgmlVkCanFuseRmsNormMulRope(ggml_backend_vk_context *pCtx, const struct ggml_cgraph *pCgraph,
                                         int pNodeIdx) {
  GGML_UNUSED(pCtx);
  const ggml_tensor *vRms = pCgraph->nodes[pNodeIdx + 0];
  const ggml_tensor *vMul = pCgraph->nodes[pNodeIdx + 1];
  const ggml_tensor *vRope = pCgraph->nodes[pNodeIdx + 2];

  const int cMode = ((const int32_t *)vRope->op_params)[2];

  // noncontig tensors aren't tested, and don't seem common in practice
  if (!ggml_is_contiguous(vRms) || !ggml_is_contiguous(vMul) || !ggml_is_contiguous(vRope)) {
    return false;
  }

  // only norm/neox are handled in the shader
  if (cMode != GGML_ROPE_TYPE_NEOX && cMode != GGML_ROPE_TYPE_NORMAL) {
    return false;
  }

  // shared memory size for passing data from mul->rope
  if (vMul->ne[0] > 1024) {
    return false;
  }

  // conditions for pipeline creation
  if (sizeof(vk_op_rms_norm_mul_rope_push_constants) > pCtx->device->properties.limits.maxPushConstantsSize) {
    return false;
  }

  return true;
}

static uint32_t fGgmlVkFuseMultiAdd(ggml_backend_vk_context *pCtx, const struct ggml_cgraph *pCgraph, int pNodeIdx) {

  const ggml_tensor *vFirstNode = pCgraph->nodes[pNodeIdx];
  if (vFirstNode->op != GGML_OP_ADD) {
    return 0;
  }

  if (!pCtx->device->vMultiAdd) {
    return 0;
  }

  int32_t vNumAdds = 1;
  while (pNodeIdx + vNumAdds < pCgraph->n_nodes && pCgraph->nodes[pNodeIdx + vNumAdds]->op == GGML_OP_ADD &&
         vNumAdds < MAX_FUSED_ADDS) {
    vNumAdds++;
  }

  // The shader currently requires same shapes (but different strides are allowed),
  // everything f32, and no misalignment
  for (int32_t vI = 0; vI < vNumAdds; ++vI) {
    const ggml_tensor *vNextNode = pCgraph->nodes[pNodeIdx + vI];
    if (!ggml_are_same_shape(vFirstNode, vNextNode->src[0]) || !ggml_are_same_shape(vFirstNode, vNextNode->src[1]) ||
        vNextNode->type != GGML_TYPE_F32 || vNextNode->src[0]->type != GGML_TYPE_F32 ||
        vNextNode->src[1]->type != GGML_TYPE_F32 || fGetMisalignBytes(pCtx, vNextNode) ||
        fGetMisalignBytes(pCtx, vNextNode->src[0]) || fGetMisalignBytes(pCtx, vNextNode->src[1])) {
      vNumAdds = vI;
    }
  }

  // Verify we can fuse these
  ggml_op aAdds[MAX_FUSED_ADDS];
  for (int32_t vI = 0; vI < vNumAdds; ++vI) {
    aAdds[vI] = GGML_OP_ADD;
  }

  // decrease num_adds if they can't all be fused
  while (vNumAdds > 1 && !ggml_can_fuse(pCgraph, pNodeIdx, aAdds, vNumAdds)) {
    vNumAdds--;
  }

  // a single add is not "fused", so just return zero
  if (vNumAdds == 1) {
    return 0;
  }
  return vNumAdds;
}

static int32_t fFindFirstSet(uint32_t pX) {
  int32_t vRet = 0;
  if (!pX) {
    return -1;
  }
  while (!(pX & 1)) {
    pX >>= 1;
    vRet++;
  }
  return vRet;
}

static ggml_status fGgmlBackendVkGraphCompute(ggml_backend_t pBackend, ggml_cgraph *pCgraph) {
  VK_LOG_DEBUG("ggml_backend_vk_graph_compute(" << pCgraph->n_nodes << " nodes)");
  ggml_backend_vk_context *vCtx = (ggml_backend_vk_context *)pBackend->context;

  if (vk_instance.vDebugUtilsSupport) {
    vk::DebugUtilsLabelEXT vDul = {};
    vDul.pLabelName = "ggml_backend_vk_graph_compute";
    vDul.color = std::array<float, 4>{1.0f, 1.0f, 1.0f, 1.0f};

    std::lock_guard<vk_queue_handle> vGuard(*vCtx->device->vComputeQueue->vHandle);
    vk_instance.vPfnVkQueueBeginDebugUtilsLabelExt(vCtx->device->vComputeQueue->vHandle->vQueue,
                                                   reinterpret_cast<VkDebugUtilsLabelEXT *>(&vDul));
  }

  vCtx->vPreallocSizeAddRmsPartialsOffset = 0;
  vCtx->vDoAddRmsPartials = false;
  vCtx->vDoAddRmsPartialsOffsetCalculation = false;

  int vLastNode = pCgraph->n_nodes - 1;

  // If the last op in the cgraph isn't backend GPU, the command buffer doesn't get closed properly
  while (vLastNode > 0 && (fGgmlVkIsEmpty(pCgraph->nodes[vLastNode]) ||
                           ((pCgraph->nodes[vLastNode]->flags & GGML_TENSOR_FLAG_COMPUTE) == 0))) {
    vLastNode -= 1;
  }

  // Reserve tensor context space for all nodes
  vCtx->lTensorCtxs.resize(pCgraph->n_nodes);

  bool vFirstNodeInBatch = true; // true if next node will be first node in a batch
  int vSubmitNodeIdx = 0;        // index to first node in a batch

  fGgmlVkSubmitTransferCtx(vCtx);

  vk_context vComputeCtx;
  if (vk_perf_logger_enabled) {
    // allocate/resize the query pool
    if (vCtx->vNumQueries < pCgraph->n_nodes + 1) {
      if (vCtx->vQueryPool) {
        vCtx->device->device.destroyQueryPool(vCtx->vQueryPool);
      }
      vk::QueryPoolCreateInfo vQueryCreateInfo;
      vQueryCreateInfo.queryType = vk::QueryType::eTimestamp;
      vQueryCreateInfo.queryCount = pCgraph->n_nodes + 100;
      vCtx->vQueryPool = vCtx->device->device.createQueryPool(vQueryCreateInfo);
      vCtx->vNumQueries = vQueryCreateInfo.queryCount;
      vCtx->lQueryFusionNames.resize(vCtx->vNumQueries);
      vCtx->lQueryFusionNodeCount.resize(vCtx->vNumQueries);
      vCtx->lQueryNodes.resize(vCtx->vNumQueries);
      vCtx->lQueryNodeIdx.resize(vCtx->vNumQueries);
    }

    vCtx->device->device.resetQueryPool(vCtx->vQueryPool, 0, pCgraph->n_nodes + 1);
    std::fill(vCtx->lQueryFusionNames.begin(), vCtx->lQueryFusionNames.end(), nullptr);
    std::fill(vCtx->lQueryFusionNodeCount.begin(), vCtx->lQueryFusionNodeCount.end(), 0);
    std::fill(vCtx->lQueryNodes.begin(), vCtx->lQueryNodes.end(), nullptr);
    std::fill(vCtx->lQueryNodeIdx.begin(), vCtx->lQueryNodeIdx.end(), 0);

    // with a graph split between devices the input copies of this split can already be recorded in the open
    // compute context; the first timestamp then also covers them
    vComputeCtx = fGgmlVkGetComputeCtx(vCtx);
    vCtx->vQueryIdx = 0;
    vComputeCtx->s->buffer->vBuf.writeTimestamp(vk::PipelineStageFlagBits::eAllCommands, vCtx->vQueryPool,
                                                vCtx->vQueryIdx++);
    fGgmlVkSyncBuffers(vCtx, vComputeCtx);
  }

  vCtx->vPreallocYLastPipelineUsed = nullptr;
  vCtx->vPreallocYLastTensorUsed = nullptr;
  vCtx->vPreallocYLastDecodeVectorStaging = false;

  if (vCtx->vPreallocSizeAddRmsPartials) {
    fGgmlVkPreallocateBuffers(vCtx, nullptr);
    vComputeCtx = fGgmlVkGetComputeCtx(vCtx);
    // initialize partial sums to zero.
    fGgmlVkBufferMemsetAsync(vComputeCtx, vCtx->vPreallocAddRmsPartials, 0, 0, vCtx->vPreallocSizeAddRmsPartials);
    fGgmlVkSyncBuffers(vCtx, vComputeCtx);
  }

  // Submit after enough work has accumulated, to overlap CPU cmdbuffer generation with GPU execution.
  // Estimate the amount of compute work using flops, and submit every 200 GFLOP
  // (and scaled down based on total graph flops, so smaller models submit earlier).
  // Also submit at least every 100 nodes, in case there are workloads without heavy compute.
  uint32_t vSubmittedNodes = 0;
  uint32_t vSubmitCount = 0;
  uint64_t vBatchFlops = 0;
  uint64_t vTotalFlops = 0;
  uint64_t vFlopsCap = 200'000'000'000ULL;

  // On weaker AMD GPUs larger submissions can hit a driver timeout, submit more often to avoid this
  if (vCtx->device->vVendorId == VK_VENDOR_ID_AMD && vCtx->device->vShaderCoreCount > 0) {
    if (vCtx->device->vArchitecture == AMD_GCN && vCtx->device->vShaderCoreCount < 32) {
      vFlopsCap = 500'000'000ULL * vCtx->device->vShaderCoreCount;
    } else if (vCtx->device->vArchitecture != AMD_GCN && vCtx->device->vShaderCoreCount < 24) {
      vFlopsCap = 2'000'000'000ULL * vCtx->device->vShaderCoreCount;
    }
  }
  uint64_t vFlopsPerSubmit = std::min(vFlopsCap, vCtx->vLastTotalFlops / 40u);

  for (int vI = 0; vI < pCgraph->n_nodes; vI++) {
    if (vFirstNodeInBatch) {
      vSubmitNodeIdx = vI;
    }

    {
      auto vNodeFlops = fGgmlVkGetNodeFlops(pCgraph->nodes[vI]);
      vBatchFlops += vNodeFlops;
      vTotalFlops += vNodeFlops;
    }

    // op_srcs_fused_elementwise indicates whether an op's srcs all contribute to
    // the fused result in an elementwise-way. This affects whether the memory for
    // the src is allowed to overlap the memory for the destination.
    // The array is sized to handle the largest fusion (asserted later).
    bool vOpSrcsFusedElementwise[13];

    vCtx->vFusedTopkMoeMode = TOPK_MOE_COUNT;
    vCtx->vFusedTopkMoeScale = false;
    vCtx->vFusedHcPostGate = false;
    vCtx->vFusedAmaxPow2Mode = 0;
    const char *vFusionString{};
    if (!vCtx->device->vDisableFusion) {
      uint32_t vNumAdds = fGgmlVkFuseMultiAdd(vCtx, pCgraph, vI);
      if (vNumAdds) {
        vCtx->vNumAdditionalFusedOps = vNumAdds - 1;
        vFusionString = "MULTI_ADD";
        std::fill_n(vOpSrcsFusedElementwise, vCtx->vNumAdditionalFusedOps + 1, true);
      } else if (fGgmlVkCanFuse(vCtx, pCgraph, vI, {GGML_OP_MUL_MAT, GGML_OP_ADD, GGML_OP_ADD})) {
        vCtx->vNumAdditionalFusedOps = 2;
        vFusionString = "MUL_MAT_ADD_ADD";
        vOpSrcsFusedElementwise[0] = false;
        vOpSrcsFusedElementwise[1] = true;
        vOpSrcsFusedElementwise[2] = true;
      } else if (fGgmlVkCanFuse(vCtx, pCgraph, vI, {GGML_OP_MUL_MAT, GGML_OP_ADD})) {
        vCtx->vNumAdditionalFusedOps = 1;
        vFusionString = "MUL_MAT_ADD";
        vOpSrcsFusedElementwise[0] = false;
        vOpSrcsFusedElementwise[1] = true;
      } else if (fGgmlVkCanFuse(vCtx, pCgraph, vI, {GGML_OP_MUL_MAT_ID, GGML_OP_ADD_ID, GGML_OP_MUL})) {
        vCtx->vNumAdditionalFusedOps = 2;
        vFusionString = "MUL_MAT_ID_ADD_ID_MUL";
        vOpSrcsFusedElementwise[0] = false;
        vOpSrcsFusedElementwise[1] = true;
        vOpSrcsFusedElementwise[2] = true;
      } else if (fGgmlVkCanFuse(vCtx, pCgraph, vI, {GGML_OP_MUL_MAT_ID, GGML_OP_ADD_ID})) {
        vCtx->vNumAdditionalFusedOps = 1;
        vFusionString = "MUL_MAT_ID_ADD_ID";
        vOpSrcsFusedElementwise[0] = false;
        vOpSrcsFusedElementwise[1] = true;
      } else if (fGgmlVkCanFuse(vCtx, pCgraph, vI, {GGML_OP_MUL_MAT_ID, GGML_OP_MUL})) {
        vCtx->vNumAdditionalFusedOps = 1;
        vFusionString = "MUL_MAT_ID_MUL";
        vOpSrcsFusedElementwise[0] = false;
        vOpSrcsFusedElementwise[1] = true;
      } else if (ggml_can_fuse_subgraph(pCgraph, vI,
                                        {GGML_OP_RMS_NORM, GGML_OP_MUL, GGML_OP_ROPE, GGML_OP_VIEW, GGML_OP_SET_ROWS},
                                        {vI + 4}) &&
                 ggml_check_edges(pCgraph, vI, rms_norm_mul_rope_view_set_rows_edges) &&
                 fGgmlVkCanFuseRmsNormMulRope(vCtx, pCgraph, vI) && fGgmlVkCanFuseRopeSetRows(vCtx, pCgraph, vI + 2)) {
        vCtx->vNumAdditionalFusedOps = 4;
        vFusionString = "RMS_NORM_MUL_ROPE_VIEW_SET_ROWS";
        vOpSrcsFusedElementwise[0] = false;
        vOpSrcsFusedElementwise[1] = false;
        vOpSrcsFusedElementwise[2] = false;
        vOpSrcsFusedElementwise[3] = false;
        vOpSrcsFusedElementwise[4] = false;
      } else if (fGgmlVkCanFuse(vCtx, pCgraph, vI, {GGML_OP_RMS_NORM, GGML_OP_MUL, GGML_OP_ROPE}) &&
                 fGgmlVkCanFuseRmsNormMulRope(vCtx, pCgraph, vI)) {
        vCtx->vNumAdditionalFusedOps = 2;
        vFusionString = "RMS_NORM_MUL_ROPE";
        // rope is approximately elementwise - whole rows are done by a single workgroup and it's row-wise
        vOpSrcsFusedElementwise[0] = false;
        vOpSrcsFusedElementwise[1] = true;
        vOpSrcsFusedElementwise[2] = true;
      } else if (ggml_can_fuse_subgraph(pCgraph, vI, hc_post_gate_pattern, {vI + 3}) &&
                 ggml_check_edges(pCgraph, vI, hc_post_gate_edges) && fGgmlVkCanFuseHcPostGate(pCgraph, vI)) {
        vCtx->vNumAdditionalFusedOps = hc_post_gate_pattern.size() - 1;
        vCtx->vFusedHcPostGate = true;
        vFusionString = "HC_POST_GATE";
        std::fill_n(vOpSrcsFusedElementwise, vCtx->vNumAdditionalFusedOps + 1, false);
      } else if (fGgmlVkCanFuse(vCtx, pCgraph, vI, {GGML_OP_RMS_NORM, GGML_OP_MUL})) {
        vCtx->vNumAdditionalFusedOps = 1;
        vFusionString = "RMS_NORM_MUL";
        // rms_norm is not elementwise, but whole rows must be consumed and the scale factor computed before
        // they are overwritten, and one workgroup per row. So close enough.
        vOpSrcsFusedElementwise[0] = true;
        vOpSrcsFusedElementwise[1] = true;
      } else if (fGgmlVkCanFuse(vCtx, pCgraph, vI, {GGML_OP_UNARY, GGML_OP_MUL})) {
        vCtx->vNumAdditionalFusedOps = 1;
        switch (ggml_get_unary_op(pCgraph->nodes[vI])) {
        case GGML_UNARY_OP_GELU:
          vFusionString = "GELU_MUL";
          break;
        case GGML_UNARY_OP_SIGMOID:
          vFusionString = "SIGMOID_MUL";
          break;
        case GGML_UNARY_OP_SILU:
          vFusionString = "SILU_MUL";
          break;
        default:
          vFusionString = "SOFTPLUS_MUL";
          break;
        }
        vOpSrcsFusedElementwise[0] = true;
        vOpSrcsFusedElementwise[1] = true;
      } else if (fGgmlVkCanFuseSsmConv(vCtx, pCgraph, vI, 2)) {
        vCtx->vNumAdditionalFusedOps = 2;
        vFusionString = "SSM_CONV_BIAS_SILU";
        // ssm_conv reads multiple input tokens per output, so it's not elementwise w.r.t. its srcs.
        // The downstream add and silu are elementwise on the conv output.
        vOpSrcsFusedElementwise[0] = false;
        vOpSrcsFusedElementwise[1] = true;
        vOpSrcsFusedElementwise[2] = true;
      } else if (fGgmlVkCanFuseSsmConv(vCtx, pCgraph, vI, 1)) {
        vCtx->vNumAdditionalFusedOps = 1;
        vFusionString = "SSM_CONV_SILU";
        vOpSrcsFusedElementwise[0] = false;
        vOpSrcsFusedElementwise[1] = true;
      } else if (ggml_can_fuse_subgraph(pCgraph, vI, {GGML_OP_ROPE, GGML_OP_VIEW, GGML_OP_SET_ROWS}, {vI + 2}) &&
                 ggml_check_edges(pCgraph, vI, rope_view_set_rows_edges) &&
                 fGgmlVkCanFuseRopeSetRows(vCtx, pCgraph, vI)) {
        vCtx->vNumAdditionalFusedOps = 2;
        vFusionString = "ROPE_VIEW_SET_ROWS";
        vOpSrcsFusedElementwise[0] = false;
        vOpSrcsFusedElementwise[1] = false;
        vOpSrcsFusedElementwise[2] = false;
      } else if (fGgmlVkCanFuseSnake(vCtx, pCgraph, vI)) {
        vCtx->vNumAdditionalFusedOps = 4;
        vFusionString = "SNAKE";
        // elementwise=true: snake.comp is safe under exact aliasing because each
        // thread reads data_x[idx] into a register before writing data_d[idx]
        // with a data dependency on that register. The overlap check still
        // rejects partial overlaps (different base or size).
        std::fill_n(vOpSrcsFusedElementwise, 5, true);
      } else if (fGgmlVkCanFuseAmaxPow2(vCtx, pCgraph, vI, 2)) {
        vCtx->vNumAdditionalFusedOps = 2;
        // the weights of the MUL are written too
        vCtx->vFusedOpsWriteMask |= 1 << 1;
        vCtx->vFusedAmaxPow2Mode = 2;
        vFusionString = "AMAX_POW2_MUL_DIV";
        // each invocation reads its values before it writes them
        std::fill_n(vOpSrcsFusedElementwise, 3, true);
      } else if (fGgmlVkCanFuseAmaxPow2(vCtx, pCgraph, vI, 1)) {
        vCtx->vNumAdditionalFusedOps = 1;
        // the factor is written too
        vCtx->vFusedOpsWriteMask |= 1 << 0;
        vCtx->vFusedAmaxPow2Mode = 1;
        vFusionString = "AMAX_POW2_DIV";
        std::fill_n(vOpSrcsFusedElementwise, 2, true);
      } else if (ggml_can_fuse_subgraph(pCgraph, vI, topk_moe_early_softmax_norm, {vI + 3, vI + 9}) &&
                 ggml_check_edges(pCgraph, vI, topk_moe_early_softmax_norm_edges) &&
                 fGgmlVkCanFuseTopkMoe(vCtx, pCgraph, vI, TOPK_MOE_EARLY_SOFTMAX_NORM)) {
        vCtx->vNumAdditionalFusedOps = topk_moe_early_softmax_norm.size() - 1;
        // view of argsort writes to memory
        vCtx->vFusedOpsWriteMask |= 1 << 3;
        vCtx->vFusedTopkMoeMode = TOPK_MOE_EARLY_SOFTMAX_NORM;
        vFusionString = "TOPK_MOE_EARLY_SOFTMAX_NORM";
        std::fill_n(vOpSrcsFusedElementwise, vCtx->vNumAdditionalFusedOps + 1, false);
      } else if (ggml_can_fuse_subgraph(pCgraph, vI, topk_moe_sigmoid_norm_bias, {vI + 4, vI + 10}) &&
                 ggml_check_edges(pCgraph, vI, topk_moe_sigmoid_norm_bias_edges) &&
                 fGgmlVkCanFuseTopkMoe(vCtx, pCgraph, vI, TOPK_MOE_SIGMOID_NORM_BIAS)) {
        vCtx->vNumAdditionalFusedOps = topk_moe_sigmoid_norm_bias.size() - 1;
        // view of argsort writes to memory
        vCtx->vFusedOpsWriteMask |= 1 << 4;
        vCtx->vFusedTopkMoeMode = TOPK_MOE_SIGMOID_NORM_BIAS;
        vFusionString = "TOPK_MOE_SIGMOID_NORM_BIAS";
        std::fill_n(vOpSrcsFusedElementwise, vCtx->vNumAdditionalFusedOps + 1, false);
      } else if (ggml_can_fuse_subgraph(pCgraph, vI, topk_moe_sigmoid_norm, {vI + 3, vI + 9}) &&
                 ggml_check_edges(pCgraph, vI, topk_moe_early_softmax_norm_edges) &&
                 fGgmlVkCanFuseTopkMoe(vCtx, pCgraph, vI, TOPK_MOE_SIGMOID_NORM)) {
        vCtx->vNumAdditionalFusedOps = topk_moe_sigmoid_norm.size() - 1;
        // view of argsort writes to memory
        vCtx->vFusedOpsWriteMask |= 1 << 3;
        vCtx->vFusedTopkMoeMode = TOPK_MOE_SIGMOID_NORM;
        vFusionString = "TOPK_MOE_SIGMOID_NORM";
        std::fill_n(vOpSrcsFusedElementwise, vCtx->vNumAdditionalFusedOps + 1, false);
      } else if (ggml_can_fuse_subgraph(pCgraph, vI, topk_moe_sqrt_softplus_norm_bias, {vI + 5, vI + 11}) &&
                 ggml_check_edges(pCgraph, vI, topk_moe_sqrt_softplus_norm_bias_edges) &&
                 fGgmlVkCanFuseTopkMoe(vCtx, pCgraph, vI, TOPK_MOE_SQRT_SOFTPLUS_NORM_BIAS)) {
        vCtx->vNumAdditionalFusedOps = topk_moe_sqrt_softplus_norm_bias.size() - 1;
        // view of argsort writes to memory
        vCtx->vFusedOpsWriteMask |= 1 << 5;
        vCtx->vFusedTopkMoeMode = TOPK_MOE_SQRT_SOFTPLUS_NORM_BIAS;
        vFusionString = "TOPK_MOE_SQRT_SOFTPLUS_NORM_BIAS";
        std::fill_n(vOpSrcsFusedElementwise, vCtx->vNumAdditionalFusedOps + 1, false);
      } else if (ggml_can_fuse_subgraph(pCgraph, vI, topk_moe_early_softmax, {vI + 3, vI + 4}) &&
                 ggml_check_edges(pCgraph, vI, topk_moe_early_softmax_edges) &&
                 fGgmlVkCanFuseTopkMoe(vCtx, pCgraph, vI, TOPK_MOE_EARLY_SOFTMAX)) {
        vCtx->vNumAdditionalFusedOps = topk_moe_early_softmax.size() - 1;
        // view of argsort writes to memory
        vCtx->vFusedOpsWriteMask |= 1 << 3;
        vCtx->vFusedTopkMoeMode = TOPK_MOE_EARLY_SOFTMAX;
        vFusionString = "TOPK_MOE_EARLY_SOFTMAX";
        std::fill_n(vOpSrcsFusedElementwise, vCtx->vNumAdditionalFusedOps + 1, false);
      } else if (ggml_can_fuse_subgraph(pCgraph, vI, topk_moe_late_softmax, {vI + 1, vI + 5}) &&
                 ggml_check_edges(pCgraph, vI, topk_moe_late_softmax_edges) &&
                 fGgmlVkCanFuseTopkMoe(vCtx, pCgraph, vI, TOPK_MOE_LATE_SOFTMAX)) {
        vCtx->vNumAdditionalFusedOps = topk_moe_late_softmax.size() - 1;
        // view of argsort writes to memory
        vCtx->vFusedOpsWriteMask |= 1 << 1;
        vCtx->vFusedTopkMoeMode = TOPK_MOE_LATE_SOFTMAX;
        vFusionString = "TOPK_MOE_LATE_SOFTMAX";
        std::fill_n(vOpSrcsFusedElementwise, vCtx->vNumAdditionalFusedOps + 1, false);
      }
      if (vCtx->vFusedTopkMoeMode != TOPK_MOE_COUNT) {
        // Look for an additional scale op to fuse - occurs in nemotron3 nano.
        if (ggml_can_fuse_subgraph(pCgraph, vI + vCtx->vNumAdditionalFusedOps - 1,
                                   {GGML_OP_DIV, GGML_OP_RESHAPE, GGML_OP_SCALE},
                                   {vI + vCtx->vNumAdditionalFusedOps + 1}) ||
            ggml_can_fuse_subgraph(pCgraph, vI + vCtx->vNumAdditionalFusedOps, {GGML_OP_GET_ROWS, GGML_OP_SCALE},
                                   {vI + vCtx->vNumAdditionalFusedOps + 1})) {
          vCtx->vFusedTopkMoeScale = true;
          vCtx->vNumAdditionalFusedOps++;
          vOpSrcsFusedElementwise[vCtx->vNumAdditionalFusedOps] = false;
        }
      }
    }
    GGML_ASSERT(vCtx->vNumAdditionalFusedOps <
                (int)(sizeof(vOpSrcsFusedElementwise) / sizeof(vOpSrcsFusedElementwise[0])));
    vCtx->vFusedOpsWriteMask |= 1 << vCtx->vNumAdditionalFusedOps;

    // Check whether fusion would overwrite src operands while they're still in use.
    // If so, disable fusion.
    if (vCtx->vNumAdditionalFusedOps) {
      // There are up to two output nodes - topk_moe has two.
      uint32_t vBits = vCtx->vFusedOpsWriteMask & ~(1 << vCtx->vNumAdditionalFusedOps);
      ggml_tensor *aOutputNodes[2]{};
      aOutputNodes[0] = pCgraph->nodes[vI + vCtx->vNumAdditionalFusedOps];
      if (vBits) {
        int vOutputIdx = fFindFirstSet(vBits);
        GGML_ASSERT(vBits == (1u << vOutputIdx));
        aOutputNodes[1] = pCgraph->nodes[vI + vOutputIdx];
      }

      bool vNeedDisable = false;

      // topk_moe often overwrites the source, but for a given row all the src values are
      // loaded before anything is stored. If there's only one row, this is safe, so treat
      // this as a special case.
      bool vIsTopkMoeSingleRow =
          vCtx->vFusedTopkMoeMode != TOPK_MOE_COUNT && ggml_nrows(pCgraph->nodes[vI]->src[0]) == 1;

      if (!vIsTopkMoeSingleRow) {
        for (int vJ = 0; vJ < 2; ++vJ) {
          ggml_tensor *vDst = aOutputNodes[vJ];
          if (!vDst) {
            continue;
          }
          // Loop over all srcs of all nodes in the fusion. If the src overlaps
          // the destination and the src is not an intermediate node that's being
          // elided, then disable fusion.
          for (int vK = 0; vK <= vCtx->vNumAdditionalFusedOps; ++vK) {
            for (uint32_t vS = 0; vS < GGML_MAX_SRC; ++vS) {
              ggml_tensor *vSrc = pCgraph->nodes[vI + vK]->src[vS];
              if (!vSrc || vSrc->op == GGML_OP_NONE) {
                continue;
              }
              if (fGgmlVkTensorsOverlap(vSrc, vDst, vOpSrcsFusedElementwise[vK])) {
                bool vFound = false;
                for (int vN = 0; vN < vK; ++vN) {
                  if (pCgraph->nodes[vI + vN] == vSrc) {
                    vFound = true;
                    break;
                  }
                }
                if (!vFound) {
                  vNeedDisable = true;
                }
              }
            }
          }
        }
      }
      if (vNeedDisable) {
        vCtx->vNumAdditionalFusedOps = 0;
        vCtx->vFusedOpsWriteMask = 1;
        vCtx->vFusedTopkMoeMode = TOPK_MOE_COUNT;
        vCtx->vFusedTopkMoeScale = false;
        vCtx->vFusedHcPostGate = false;
        vCtx->vFusedAmaxPow2Mode = 0;
      }
    }

    // Signal the almost_ready fence when the graph is mostly complete (< 20% remaining)
    bool vAlmostReady = (pCgraph->n_nodes - vI) < pCgraph->n_nodes / 5;
    bool vSubmit = (vSubmittedNodes >= vCtx->device->vMaxNodesPerSubmit) ||
                   (vFlopsPerSubmit != 0 && vBatchFlops >= vFlopsPerSubmit) ||
                   (vI + vCtx->vNumAdditionalFusedOps >= vLastNode) ||
                   (vAlmostReady && !vCtx->vAlmostReadyFencePending);

    bool vEnqueued = fGgmlVkBuildGraph(vCtx, pCgraph, vI, pCgraph->nodes[vSubmitNodeIdx], vSubmitNodeIdx,
                                       vI + vCtx->vNumAdditionalFusedOps >= vLastNode, vAlmostReady, vSubmit);

    if (vk_perf_logger_enabled && vEnqueued) {
      vComputeCtx = fGgmlVkGetComputeCtx(vCtx);
      if (!vk_perf_logger_concurrent) {
        // track a single node/fusion for the current query
        vCtx->lQueryNodes[vCtx->vQueryIdx] = pCgraph->nodes[vI];
        vCtx->lQueryFusionNames[vCtx->vQueryIdx] = vFusionString;
        vComputeCtx->s->buffer->vBuf.writeTimestamp(vk::PipelineStageFlagBits::eAllCommands, vCtx->vQueryPool,
                                                    vCtx->vQueryIdx++);
        fGgmlVkSyncBuffers(vCtx, vComputeCtx);
      } else {
        // track a fusion string and number of fused ops for the current node_idx
        vCtx->lQueryFusionNames[vI] = vFusionString;
        vCtx->lQueryFusionNodeCount[vI] = vCtx->vNumAdditionalFusedOps;
      }
    }

    if (vEnqueued) {
      ++vSubmittedNodes;

#ifndef GGML_VULKAN_CHECK_RESULTS
      if (vFirstNodeInBatch) {
        vFirstNodeInBatch = false;
      }
#endif
    }

    if (vSubmit && vEnqueued) {
      vFirstNodeInBatch = true;
      vSubmittedNodes = 0;
      vBatchFlops = 0;
      if (vSubmitCount < 3) {
        vFlopsPerSubmit *= 2;
      }
      vSubmitCount++;
    }
    vI += vCtx->vNumAdditionalFusedOps;
    vCtx->vNumAdditionalFusedOps = 0;
    vCtx->vFusedOpsWriteMask = 0;
  }

  vCtx->vLastTotalFlops = vTotalFlops;

  if (vk_perf_logger_enabled) {
    // End the command buffer and submit/wait
    GGML_ASSERT(!vCtx->compute_ctx.expired());
    vComputeCtx = vCtx->compute_ctx.lock();
    fGgmlVkCtxEnd(vComputeCtx);

    fGgmlVkSubmit(vComputeCtx, vCtx->device->fence);
    VK_CHECK(vCtx->device->device.waitForFences({vCtx->device->fence}, true, UINT64_MAX),
             "GGML_VULKAN_PERF waitForFences");
    vCtx->device->device.resetFences({vCtx->device->fence});
    vCtx->compute_ctx.reset();

    // Get the results and pass them to the logger
    std::vector<uint64_t> vTimestamps(pCgraph->n_nodes + 1);
    VK_CHECK(vCtx->device->device.getQueryPoolResults(
                 vCtx->vQueryPool, 0, vCtx->vQueryIdx, (pCgraph->n_nodes + 1) * sizeof(uint64_t), vTimestamps.data(),
                 sizeof(uint64_t), vk::QueryResultFlagBits::e64 | vk::QueryResultFlagBits::eWait),
             "get timestamp results");
    if (!vk_perf_logger_concurrent) {
      // Log each op separately
      for (int vI = 1; vI < vCtx->vQueryIdx; vI++) {
        auto vNode = vCtx->lQueryNodes[vI];
        auto vName = vCtx->lQueryFusionNames[vI];
        vCtx->vPerfLogger->mLogTiming(
            vNode, vName,
            uint64_t((vTimestamps[vI] - vTimestamps[vI - 1]) * vCtx->device->properties.limits.timestampPeriod));
      }
    } else {
      // Log each group of nodes
      int vPrevNodeIdx = 0;
      for (int vI = 1; vI < vCtx->vQueryIdx; vI++) {
        auto vCurNodeIdx = vCtx->lQueryNodeIdx[vI];
        std::vector<ggml_tensor *> lNodes;
        std::vector<const char *> lNames;
        for (int vNodeIdx = vPrevNodeIdx; vNodeIdx < vCurNodeIdx; ++vNodeIdx) {
          if (ggml_op_is_empty(pCgraph->nodes[vNodeIdx]->op)) {
            continue;
          }
          lNodes.push_back(pCgraph->nodes[vNodeIdx]);
          lNames.push_back(vCtx->lQueryFusionNames[vNodeIdx]);
          vNodeIdx += vCtx->lQueryFusionNodeCount[vNodeIdx];
        }
        vPrevNodeIdx = vCurNodeIdx;
        vCtx->vPerfLogger->mLogTiming(
            lNodes, lNames,
            uint64_t((vTimestamps[vI] - vTimestamps[vI - 1]) * vCtx->device->properties.limits.timestampPeriod));
      }
    }
    vCtx->vPerfLogger->mPrintTimings();
  }

  if (!vCtx->device->vSupportAsync) {
    fGgmlVkSynchronize(vCtx);
  }

  return GGML_STATUS_SUCCESS;

  UNUSED(pBackend);
}

// Sort the graph for improved parallelism.
static void fGgmlVkGraphOptimize(ggml_backend_t pBackend, struct ggml_cgraph *pGraph,
                                 struct ggml_backend_graph_optimize_params *pParams) {
  VK_LOG_DEBUG("ggml_vk_graph_optimize(" << pGraph->n_nodes << " nodes)");
  ggml_backend_vk_context *vCtx = (ggml_backend_vk_context *)pBackend->context;

  if (vCtx->device->vDisableGraphOptimize) {
    return;
  }

  auto const &fIsEmpty = [](ggml_tensor *pNode) -> bool {
    return pNode->op == GGML_OP_NONE || pNode->op == GGML_OP_RESHAPE || pNode->op == GGML_OP_TRANSPOSE ||
           pNode->op == GGML_OP_VIEW || pNode->op == GGML_OP_PERMUTE;
  };

  auto const &fIsSrcOf = [](const ggml_tensor *pDst, const ggml_tensor *pSrc) -> bool {
    for (uint32_t vS = 0; vS < GGML_MAX_SRC; ++vS) {
      if (pDst->src[vS] == pSrc) {
        return true;
      }
    }
    // implicit dependency if they view the same tensor
    const ggml_tensor *vDst2 = pDst->view_src ? pDst->view_src : pDst;
    const ggml_tensor *vSrc2 = pSrc->view_src ? pSrc->view_src : pSrc;
    if (vDst2 == vSrc2) {
      return true;
    }
    return false;
  };

  std::vector<ggml_tensor *> lNewOrder;
  std::vector<bool> vUsed(pGraph->n_nodes, false);
  std::set<ggml_tensor *> sUsedNodeSet;

  int vFirstUnused = 0;

  // whether every node in [pLo, pHi) is already scheduled or computes nothing
  auto const &fEmptyOrScheduledBetween = [&](int pLo, int pHi) -> bool {
    for (int vV = pLo; vV < pHi; ++vV) {
      if (!vUsed[vV] && !fIsEmpty(pGraph->nodes[vV])) {
        return false;
      }
    }
    return true;
  };
  while (vFirstUnused < pGraph->n_nodes) {
    std::vector<int> lCurrentSet;

    // Check for fusion patterns and avoid reordering them
    auto const &fMatchPattern = [&](const std::initializer_list<ggml_op> &pPattern, int pStart) -> bool {
      if (pStart + (int)pPattern.size() <= pGraph->n_nodes) {
        bool vIsPattern = true;
        for (size_t vJ = 0; vJ < pPattern.size(); ++vJ) {
          if (pGraph->nodes[pStart + vJ]->op != pPattern.begin()[vJ] || vUsed[pStart + vJ]) {
            vIsPattern = false;
          }
        }
        return vIsPattern;
      }
      return false;
    };

    auto const &fKeepPattern = [&](const std::initializer_list<ggml_op> &pPattern) -> bool {
      if (fMatchPattern(pPattern, vFirstUnused)) {
        for (size_t vJ = 0; vJ < pPattern.size(); ++vJ) {
          lNewOrder.push_back(pGraph->nodes[vFirstUnused + vJ]);
          sUsedNodeSet.insert(pGraph->nodes[vFirstUnused + vJ]);
          vUsed[vFirstUnused + vJ] = true;
        }
        while (vFirstUnused < pGraph->n_nodes && vUsed[vFirstUnused]) {
          vFirstUnused++;
        }
        return true;
      }
      return false;
    };

    // Keeps the external inputs of a fused pattern allocated until its last node: the fused kernel still reads them
    // while it writes the outputs, which the unfused graph could place over an input it no longer needs (the router
    // logits, freed after the softmax), and the fusion would then be disabled for that overlap.
    auto const &fAddPatternAllocDeps = [&](const std::initializer_list<ggml_op> &pPattern, int pLastNode) {
      std::set<ggml_tensor *> sSeen;
      for (size_t vJ = 0; vJ < pPattern.size(); ++vJ) {
        ggml_tensor *vNode = pGraph->nodes[vFirstUnused + vJ];
        for (uint32_t vS = 0; vS < GGML_MAX_SRC; ++vS) {
          ggml_tensor *vSrc = vNode->src[vS];
          if (vSrc && sSeen.insert(vSrc).second) {
            pParams->add_alloc_dep(pParams->user_data, vSrc, pGraph->nodes[pLastNode]);
          }
        }
        sSeen.insert(vNode);
      }
    };

    auto const &fKeepTopkMoePattern = [&](const std::initializer_list<ggml_op> &pPattern) -> bool {
      if (!fMatchPattern(pPattern, vFirstUnused)) {
        return false;
      }

      int vLastNode = vFirstUnused + (int)pPattern.size() - 1;
      // Some TOPK_MOE variants fuse a trailing scale.
      if (vLastNode + 1 < pGraph->n_nodes && pGraph->nodes[vLastNode + 1]->op == GGML_OP_SCALE) {
        vLastNode++;
      }

      if (pParams) {
        fAddPatternAllocDeps(pPattern, vLastNode);
      }

      return fKeepPattern(pPattern);
    };

    if (fKeepTopkMoePattern(topk_moe_early_softmax_norm)) {
      continue;
    }
    if (fKeepTopkMoePattern(topk_moe_sigmoid_norm_bias)) {
      continue;
    }
    if (fKeepTopkMoePattern(topk_moe_sigmoid_norm)) {
      continue;
    }
    if (fKeepTopkMoePattern(topk_moe_sqrt_softplus_norm_bias)) {
      continue;
    }
    if (fKeepTopkMoePattern(topk_moe_early_softmax)) {
      continue;
    }
    if (fKeepTopkMoePattern(topk_moe_late_softmax)) {
      continue;
    }
    if (fKeepPattern(snake_pattern)) {
      continue;
    }
    if (fMatchPattern(amax_pow2_mul_div_pattern, vFirstUnused)) {
      if (pParams) {
        fAddPatternAllocDeps(amax_pow2_mul_div_pattern, vFirstUnused + 2);
      }
      fKeepPattern(amax_pow2_mul_div_pattern);
      continue;
    }
    if (fMatchPattern(amax_pow2_div_pattern, vFirstUnused)) {
      if (pParams) {
        fAddPatternAllocDeps(amax_pow2_div_pattern, vFirstUnused + 1);
      }
      fKeepPattern(amax_pow2_div_pattern);
      continue;
    }
    if (fKeepPattern(hc_post_gate_pattern)) {
      continue;
    }

    // First, grab the next unused node.
    lCurrentSet.push_back(vFirstUnused);

    // Loop through the next N nodes. Grab any that don't depend on other nodes that
    // haven't already been run. Nodes that have already been run have used[i] set
    // to true. Allow nodes that depend on the previous node if it's a fusion pattern
    // that we support (e.g. RMS_NORM + MUL).
    // This first pass only grabs "real" (non-view nodes). Second pass grabs view nodes.
    // The goal is to not interleave real and view nodes in a way that breaks fusion.
    const int cNumToCheck = 20;
    for (int vJ = vFirstUnused + 1; vJ < std::min(vFirstUnused + cNumToCheck, pGraph->n_nodes); ++vJ) {
      if (vUsed[vJ]) {
        continue;
      }
      if (fIsEmpty(pGraph->nodes[vJ])) {
        continue;
      }
      // Don't pull forward nodes from fusion patterns
      if (fMatchPattern(topk_moe_early_softmax_norm, vJ) || fMatchPattern(topk_moe_sigmoid_norm_bias, vJ) ||
          fMatchPattern(topk_moe_sigmoid_norm, vJ) ||
          fMatchPattern(topk_moe_sqrt_softplus_norm_bias, vJ) || fMatchPattern(topk_moe_early_softmax, vJ) ||
          fMatchPattern(topk_moe_late_softmax, vJ) || fMatchPattern(snake_pattern, vJ) ||
          fMatchPattern(hc_post_gate_pattern, vJ) || fMatchPattern(amax_pow2_mul_div_pattern, vJ) ||
          fMatchPattern(amax_pow2_div_pattern, vJ)) {
        continue;
      }
      bool vOk = true;
      for (int vC = vFirstUnused; vC < vJ; ++vC) {
        // a MUL may follow the RMS_NORM or UNARY it consumes once the nodes between them are scheduled or empty,
        // so that the two fuse
        if (!vUsed[vC] && fIsSrcOf(pGraph->nodes[vJ], pGraph->nodes[vC]) &&
            !(vC == lCurrentSet.back() && pGraph->nodes[vC]->op == GGML_OP_RMS_NORM &&
              pGraph->nodes[vJ]->op == GGML_OP_MUL && fEmptyOrScheduledBetween(vC + 1, vJ)) &&
            !(vC == lCurrentSet.back() && pGraph->nodes[vC]->op == GGML_OP_UNARY &&
              pGraph->nodes[vJ]->op == GGML_OP_MUL && fEmptyOrScheduledBetween(vC + 1, vJ)) &&
            !(vJ == vC + 1 && vC == lCurrentSet.back() && pGraph->nodes[vC]->op == GGML_OP_MUL_MAT &&
              pGraph->nodes[vJ]->op == GGML_OP_ADD) &&
            !(vJ == vC + 1 && vC == lCurrentSet.back() && pGraph->nodes[vC]->op == GGML_OP_MUL_MAT_ID &&
              pGraph->nodes[vJ]->op == GGML_OP_ADD_ID) &&
            !(vJ == vC + 1 && vC == lCurrentSet.back() && pGraph->nodes[vC]->op == GGML_OP_MUL_MAT_ID &&
              pGraph->nodes[vJ]->op == GGML_OP_MUL) &&
            !(vJ == vC + 1 && vC == lCurrentSet.back() && pGraph->nodes[vC]->op == GGML_OP_ADD &&
              pGraph->nodes[vJ]->op == GGML_OP_ADD) &&
            !(vJ == vC + 1 && vC == lCurrentSet.back() && pGraph->nodes[vC]->op == GGML_OP_SSM_CONV &&
              pGraph->nodes[vJ]->op == GGML_OP_ADD) &&
            !(vJ == vC + 1 && vC == lCurrentSet.back() && pGraph->nodes[vC]->op == GGML_OP_SSM_CONV &&
              pGraph->nodes[vJ]->op == GGML_OP_UNARY)) {
          vOk = false;
          break;
        }
      }
      if (vOk) {
        lCurrentSet.push_back(vJ);

        int vRopeIdx = vJ;

        // When we've found RMS_NORM + MUL, try to find a ROPE that uses it
        if (vJ > 0 && pGraph->nodes[vJ]->op == GGML_OP_MUL && pGraph->nodes[vJ - 1]->op == GGML_OP_RMS_NORM) {
          for (int vK = vJ + 1; vK < std::min(vJ + 15, pGraph->n_nodes); ++vK) {
            if (pGraph->nodes[vK]->op == GGML_OP_ROPE && pGraph->nodes[vK]->src[0] == pGraph->nodes[vJ] &&
                // Check that other srcs are already valid
                pGraph->nodes[vK]->src[1]->op == GGML_OP_NONE &&
                (pGraph->nodes[vK]->src[2] == nullptr || pGraph->nodes[vK]->src[2]->op == GGML_OP_NONE)) {
              vRopeIdx = vK;
              lCurrentSet.push_back(vRopeIdx);
              vUsed[vRopeIdx] = true;
              break;
            }
          }
        }
        // Look for ROPE + VIEW + SET_ROWS and make them consecutive
        if (pGraph->nodes[vRopeIdx]->op == GGML_OP_ROPE) {
          int vViewIdx = -1;
          int vSetRowsIdx = -1;
          for (int vK = vRopeIdx + 1; vK < std::min(vRopeIdx + 10, pGraph->n_nodes); ++vK) {
            if (vViewIdx == -1 && pGraph->nodes[vK]->op == GGML_OP_VIEW &&
                pGraph->nodes[vK]->src[0] == pGraph->nodes[vRopeIdx]) {
              vViewIdx = vK;
              continue;
            }
            if (vViewIdx != -1 && vSetRowsIdx == -1 && pGraph->nodes[vK]->op == GGML_OP_SET_ROWS &&
                pGraph->nodes[vK]->src[0] == pGraph->nodes[vViewIdx]) {
              vSetRowsIdx = vK;
              break;
            }
          }
          if (vSetRowsIdx != -1) {
            lCurrentSet.push_back(vViewIdx);
            lCurrentSet.push_back(vSetRowsIdx);
            vUsed[vViewIdx] = true;
            vUsed[vSetRowsIdx] = true;
          }
        }
        // Look for MUL_MAT_ID + ADD_ID + MUL
        if (vJ > 0 && pGraph->nodes[vJ]->op == GGML_OP_ADD_ID && pGraph->nodes[vJ - 1]->op == GGML_OP_MUL_MAT_ID) {
          for (int vK = vJ + 1; vK < std::min(vJ + 15, pGraph->n_nodes); ++vK) {
            if (pGraph->nodes[vK]->op == GGML_OP_MUL && pGraph->nodes[vK]->src[0] == pGraph->nodes[vJ] &&
                // src1 must either be weights or already processed
                (pGraph->nodes[vK]->src[1]->op == GGML_OP_NONE ||
                 sUsedNodeSet.find(pGraph->nodes[vK]->src[1]) != sUsedNodeSet.end())) {
              lCurrentSet.push_back(vK);
              vUsed[vK] = true;
              break;
            }
          }
        }
        // Look for MUL_MAT + ADD + ADD
        if (vJ > 0 && pGraph->nodes[vJ]->op == GGML_OP_ADD && pGraph->nodes[vJ - 1]->op == GGML_OP_MUL_MAT) {
          for (int vK = vJ + 1; vK < std::min(vJ + 15, pGraph->n_nodes); ++vK) {
            if (pGraph->nodes[vK]->op == GGML_OP_ADD && pGraph->nodes[vK]->src[0] == pGraph->nodes[vJ] &&
                // src1 must either be weights or already processed
                (pGraph->nodes[vK]->src[1]->op == GGML_OP_NONE ||
                 sUsedNodeSet.find(pGraph->nodes[vK]->src[1]) != sUsedNodeSet.end())) {
              lCurrentSet.push_back(vK);
              vUsed[vK] = true;
              break;
            }
          }
        }
        // SSM_CONV + ADD + UNARY: pull the consuming UNARY forward
        if (vJ > 0 && pGraph->nodes[vJ]->op == GGML_OP_ADD && pGraph->nodes[vJ - 1]->op == GGML_OP_SSM_CONV) {
          for (int vK = vJ + 1; vK < std::min(vJ + 15, pGraph->n_nodes); ++vK) {
            if (pGraph->nodes[vK]->op == GGML_OP_UNARY && pGraph->nodes[vK]->src[0] == pGraph->nodes[vJ]) {
              lCurrentSet.push_back(vK);
              vUsed[vK] = true;
              break;
            }
          }
        }
        // UNARY + MUL: pull the consuming MUL forward
        if (vJ > 0 && pGraph->nodes[vJ]->op == GGML_OP_UNARY) {
          for (int vK = vJ + 1; vK < std::min(vJ + 15, pGraph->n_nodes); ++vK) {
            ggml_tensor *vMul = pGraph->nodes[vK];
            if (vMul->op != GGML_OP_MUL || (vMul->src[0] != pGraph->nodes[vJ] && vMul->src[1] != pGraph->nodes[vJ])) {
              continue;
            }
            ggml_tensor *vOther = (vMul->src[0] == pGraph->nodes[vJ]) ? vMul->src[1] : vMul->src[0];
            // the other src must either be weights or already processed
            if (!(vOther->op == GGML_OP_NONE || sUsedNodeSet.find(vOther) != sUsedNodeSet.end())) {
              continue;
            }
            if (!fGgmlVkCanFuseUnaryMul(pGraph, vJ, vK)) {
              continue;
            }
            lCurrentSet.push_back(vK);
            vUsed[vK] = true;
            break;
          }
        }
      }
    }
    // Second pass grabs view nodes.
    // Skip this if it would break a fusion optimization (don't split up add->rms_norm or add->add).
    if (pGraph->nodes[lCurrentSet.back()]->op != GGML_OP_ADD) {
      for (int vJ = vFirstUnused + 1; vJ < std::min(vFirstUnused + cNumToCheck, pGraph->n_nodes); ++vJ) {
        if (vUsed[vJ]) {
          continue;
        }
        if (!fIsEmpty(pGraph->nodes[vJ])) {
          continue;
        }
        bool vOk = true;
        for (int vC = vFirstUnused; vC < vJ; ++vC) {
          bool vCInCurrentSet = std::find(lCurrentSet.begin(), lCurrentSet.end(), vC) != lCurrentSet.end();
          // skip views whose srcs haven't been processed.
          if (!vUsed[vC] && fIsSrcOf(pGraph->nodes[vJ], pGraph->nodes[vC]) && !vCInCurrentSet) {
            vOk = false;
            break;
          }
        }
        if (vOk) {
          lCurrentSet.push_back(vJ);
        }
      }
    }

    // Push the current set into new_order
    for (auto vC : lCurrentSet) {
      lNewOrder.push_back(pGraph->nodes[vC]);
      sUsedNodeSet.insert(pGraph->nodes[vC]);
      vUsed[vC] = true;
    }
    while (vFirstUnused < pGraph->n_nodes && vUsed[vFirstUnused]) {
      vFirstUnused++;
    }
  }
  // Replace the graph with the new order.
  for (int vI = 0; vI < pGraph->n_nodes; ++vI) {
    pGraph->nodes[vI] = lNewOrder[vI];
  }
}

static void fGgmlBackendVkEventRecord(ggml_backend_t pBackend, ggml_backend_event_t event) {
  VK_LOG_DEBUG("ggml_backend_vk_event_record(backend=" << pBackend << ", event=" << event << ")");
  ggml_backend_vk_context *vCtx = (ggml_backend_vk_context *)pBackend->context;
  vk_event *vVkev = (vk_event *)event->context;

  fGgmlVkSubmitTransferCtx(vCtx);

  vk_context vComputeCtx = fGgmlVkGetComputeCtx(vCtx);
  auto *vCmdBuf = vComputeCtx->s->buffer; // retrieve pointer before it gets reset

  if (vVkev->vHasEvent) {
    // Move existing event into submitted
    vVkev->lEventsSubmitted.push_back(vVkev->event);
  }

  // Grab the next event and record it, create one if necessary
  if (vVkev->lEventsFree.empty()) {
    vVkev->event = vCtx->device->device.createEvent({});
  } else {
    vVkev->event = vVkev->lEventsFree.back();
    vVkev->lEventsFree.pop_back();
  }

  vVkev->vHasEvent = true;

  fGgmlVkSetEvent(vComputeCtx, vVkev->event);

  vVkev->vTlSemaphore.value++;
  vComputeCtx->s->lSignalSemaphores.push_back(vVkev->vTlSemaphore);
  fGgmlVkCtxEnd(vComputeCtx);

  fGgmlVkSubmit(vComputeCtx, {});
  vCtx->vSubmitPending = true;
  vVkev->vCmdBuffer = vCmdBuf;
  vVkev->vCmdBufferUseCounter = vCmdBuf->vUseCounter;
  vCtx->compute_ctx.reset();
}

static void fGgmlBackendVkEventWait(ggml_backend_t pBackend, ggml_backend_event_t event) {
  VK_LOG_DEBUG("ggml_backend_vk_event_wait(backend=" << pBackend << ", event=" << event << ")");
  ggml_backend_vk_context *vCtx = (ggml_backend_vk_context *)pBackend->context;
  vk_event *vVkev = (vk_event *)event->context;

  vk_context vComputeCtx = fGgmlVkGetComputeCtx(vCtx);

  if (vVkev->vHasEvent) {
    // Wait for latest event
    fGgmlVkWaitEvents(vComputeCtx, {vVkev->event});

    if (vCtx->device->vAsyncUseTransferQueue) {
      vk_context vTransferCtx = fGgmlVkGetTransferCtx(vCtx);
      vTransferCtx->s->lWaitSemaphores.push_back(vVkev->vTlSemaphore);
    }
  }
}

