static ggml_guid_t fGgmlBackendVkGuid() {
  static ggml_guid aGuid = {0xb8, 0xf7, 0x4f, 0x86, 0x40, 0x3c, 0xe1, 0x02,
                            0x91, 0xc8, 0xdd, 0xe9, 0x02, 0x3f, 0xc0, 0x2b};
  return &aGuid;
}

ggml_backend_t ggml_backend_vk_init(size_t pDevNum) {
  VK_LOG_DEBUG("ggml_backend_vk_init(" << pDevNum << ")");

  ggml_backend_vk_context *vCtx = new ggml_backend_vk_context;
  fGgmlVkInit(vCtx, pDevNum);

  ggml_backend_t vVkBackend = new ggml_backend{
      /* .guid    = */ fGgmlBackendVkGuid(),
      /* .iface   = */ ggml_backend_vk_interface,
      /* .device  = */ ggml_backend_reg_dev_get(ggml_backend_vk_reg(), pDevNum),
      /* .context = */ vCtx,
  };

  if (!vCtx->device->vSupportAsync) {
    vVkBackend->iface.get_tensor_async = nullptr;
  }

  return vVkBackend;
}

bool ggml_backend_is_vk(ggml_backend_t pBackend) {
  return pBackend != NULL && ggml_guid_matches(pBackend->guid, fGgmlBackendVkGuid());
}

int ggml_backend_vk_get_device_count() { return fGgmlVkGetDeviceCount(); }

void ggml_backend_vk_get_device_description(int pDevice, char *pDescription, size_t pDescriptionSize) {
  GGML_ASSERT(pDevice < (int)vk_instance.vDeviceIndices.size());
  int vDevIdx = vk_instance.vDeviceIndices[pDevice];
  fGgmlVkGetDeviceDescription(vDevIdx, pDescription, pDescriptionSize);
}

void ggml_backend_vk_get_device_memory(int pDevice, size_t *pFree, size_t *pTotal) {
  GGML_ASSERT(pDevice < (int)vk_instance.vDeviceIndices.size());
  GGML_ASSERT(pDevice < (int)vk_instance.vDeviceSupportsMembudget.size());

  vk::PhysicalDevice vVkdev = vk_instance.vInstance.enumeratePhysicalDevices()[vk_instance.vDeviceIndices[pDevice]];
  vk::PhysicalDeviceMemoryBudgetPropertiesEXT vBudgetprops;
  vk::PhysicalDeviceMemoryProperties2 vMemprops = {};
  const bool cMembudgetSupported = vk_instance.vDeviceSupportsMembudget[pDevice];
  const bool cIsIntegratedGpu = vVkdev.getProperties().deviceType == vk::PhysicalDeviceType::eIntegratedGpu;

  if (cMembudgetSupported) {
    vMemprops.pNext = &vBudgetprops;
  }
  vVkdev.getMemoryProperties2(&vMemprops);

  *pTotal = 0;
  *pFree = 0;

  // Without resizable BAR, the CPU-visible device-local heap is a small window (usually 256 MiB) that the device
  // buffers avoid (see disable_host_visible_vidmem): it counts in the total VRAM but never as free memory for them.
  std::vector<bool> vABarWindow(vMemprops.memoryProperties.memoryHeapCount, false);
  if (!cIsIntegratedGpu) {
    std::vector<bool> vAVisibleHeap(vMemprops.memoryProperties.memoryHeapCount, false);
    for (uint32_t vType = 0; vType < vMemprops.memoryProperties.memoryTypeCount; vType++) {
      const vk::MemoryType &vMemoryType = vMemprops.memoryProperties.memoryTypes[vType];
      if ((vMemoryType.propertyFlags & vk::MemoryPropertyFlagBits::eDeviceLocal) &&
          (vMemoryType.propertyFlags & vk::MemoryPropertyFlagBits::eHostVisible)) {
        vAVisibleHeap[vMemoryType.heapIndex] = true;
      }
    }
    vk::DeviceSize vLocalHeapSize = 0;
    for (uint32_t vI = 0; vI < vMemprops.memoryProperties.memoryHeapCount; ++vI) {
      const vk::MemoryHeap &vHeap = vMemprops.memoryProperties.memoryHeaps[vI];
      if (vHeap.flags & vk::MemoryHeapFlagBits::eDeviceLocal) {
        vLocalHeapSize = std::max(vLocalHeapSize, vHeap.size);
      }
    }
    for (uint32_t vI = 0; vI < vMemprops.memoryProperties.memoryHeapCount; ++vI) {
      const vk::MemoryHeap &vHeap = vMemprops.memoryProperties.memoryHeaps[vI];
      vABarWindow[vI] =
          (vHeap.flags & vk::MemoryHeapFlagBits::eDeviceLocal) && vAVisibleHeap[vI] && vHeap.size * 2 < vLocalHeapSize;
    }
  }

  for (uint32_t vI = 0; vI < vMemprops.memoryProperties.memoryHeapCount; ++vI) {
    const vk::MemoryHeap &vHeap = vMemprops.memoryProperties.memoryHeaps[vI];

    if (cIsIntegratedGpu || (vHeap.flags & vk::MemoryHeapFlagBits::eDeviceLocal)) {
      *pTotal += vHeap.size;

      if (vABarWindow[vI]) {
        continue;
      }
      if (cMembudgetSupported && vI < vBudgetprops.heapUsage.size()) {
        *pFree += vBudgetprops.heapBudget[vI] - vBudgetprops.heapUsage[vI];
      } else {
        *pFree += vHeap.size;
      }
    }
  }
}

static vk::PhysicalDeviceType fGgmlBackendVkGetDeviceType(int pDeviceIdx) {
  GGML_ASSERT(pDeviceIdx >= 0 && pDeviceIdx < (int)vk_instance.vDeviceIndices.size());

  vk::PhysicalDevice vDevice = vk_instance.vInstance.enumeratePhysicalDevices()[vk_instance.vDeviceIndices[pDeviceIdx]];

  vk::PhysicalDeviceProperties2 vProps = {};
  vDevice.getProperties2(&vProps);

  return vProps.properties.deviceType;
}

static std::string fGgmlBackendVkGetDevicePciId(int pDeviceIdx) {
  GGML_ASSERT(pDeviceIdx >= 0 && pDeviceIdx < (int)vk_instance.vDeviceIndices.size());

  vk::PhysicalDevice vDevice = vk_instance.vInstance.enumeratePhysicalDevices()[vk_instance.vDeviceIndices[pDeviceIdx]];

  const std::vector<vk::ExtensionProperties> lExtProps = vDevice.enumerateDeviceExtensionProperties();

  bool vExtSupport = false;

  for (const auto &vProperties : lExtProps) {
    if (strcmp("VK_EXT_pci_bus_info", vProperties.extensionName) == 0) {
      vExtSupport = true;
      break;
    }
  }

  if (!vExtSupport) {
    return "";
  }

  vk::PhysicalDeviceProperties2 vProps = {};
  vk::PhysicalDevicePCIBusInfoPropertiesEXT vPciBusInfo = {};

  vProps.pNext = &vPciBusInfo;

  vDevice.getProperties2(&vProps);

  const uint32_t cPciDomain = vPciBusInfo.pciDomain;
  const uint32_t cPciBus = vPciBusInfo.pciBus;
  const uint32_t cPciDevice = vPciBusInfo.pciDevice;
  const uint8_t cPciFunction =
      (uint8_t)vPciBusInfo.pciFunction; // pci function is between 0 and 7, prevent printf overflow warning

  char aPciBusId[16] = {};
  snprintf(aPciBusId, sizeof(aPciBusId), "%04x:%02x:%02x.%x", cPciDomain, cPciBus, cPciDevice, cPciFunction);

  return std::string(aPciBusId);
}

