struct ggml_backend_vk_device_context {
  size_t device;
  std::string name;
  std::string vDescription;
  bool vIsIntegratedGpu;
  std::string vPciBusId;
  int vOpOffloadMinBatchSize;
};

static const char *fGgmlBackendVkDeviceGetName(ggml_backend_dev_t pDev) {
  ggml_backend_vk_device_context *vCtx = (ggml_backend_vk_device_context *)pDev->context;
  return vCtx->name.c_str();
}

static const char *fGgmlBackendVkDeviceGetDescription(ggml_backend_dev_t pDev) {
  ggml_backend_vk_device_context *vCtx = (ggml_backend_vk_device_context *)pDev->context;
  return vCtx->vDescription.c_str();
}

static void fGgmlBackendVkDeviceGetMemory(ggml_backend_dev_t pDevice, size_t *pFree, size_t *pTotal) {
  ggml_backend_vk_device_context *vCtx = (ggml_backend_vk_device_context *)pDevice->context;
  ggml_backend_vk_get_device_memory(vCtx->device, pFree, pTotal);
}

static ggml_backend_buffer_type_t fGgmlBackendVkDeviceGetBufferType(ggml_backend_dev_t pDev) {
  ggml_backend_vk_device_context *vCtx = (ggml_backend_vk_device_context *)pDev->context;
  return ggml_backend_vk_buffer_type(vCtx->device);
}

static ggml_backend_buffer_type_t fGgmlBackendVkDeviceGetHostBufferType(ggml_backend_dev_t pDev) {
  UNUSED(pDev);
  return ggml_backend_vk_host_buffer_type();
}

static enum ggml_backend_dev_type fGgmlBackendVkDeviceGetType(ggml_backend_dev_t pDev) {
  ggml_backend_vk_device_context *vCtx = (ggml_backend_vk_device_context *)pDev->context;

  return vCtx->vIsIntegratedGpu ? GGML_BACKEND_DEVICE_TYPE_IGPU : GGML_BACKEND_DEVICE_TYPE_GPU;
}

static void fGgmlBackendVkDeviceGetProps(ggml_backend_dev_t pDev, struct ggml_backend_dev_props *pProps) {
  ggml_backend_vk_device_context *vCtx = (ggml_backend_vk_device_context *)pDev->context;

  pProps->name = fGgmlBackendVkDeviceGetName(pDev);
  pProps->description = fGgmlBackendVkDeviceGetDescription(pDev);
  pProps->type = fGgmlBackendVkDeviceGetType(pDev);
  pProps->device_id = vCtx->vPciBusId.empty() ? nullptr : vCtx->vPciBusId.c_str();
  fGgmlBackendVkDeviceGetMemory(pDev, &pProps->memory_free, &pProps->memory_total);
  pProps->caps = {
      /* .async                 = */ true,
      /* .host_buffer           = */ true,
      /* .buffer_from_host_ptr  = */ false,
      /* .events                = */ true,
  };
}

static ggml_backend_t fGgmlBackendVkDeviceInit(ggml_backend_dev_t pDev, const char *pParams) {
  UNUSED(pParams);
  ggml_backend_vk_device_context *vCtx = (ggml_backend_vk_device_context *)pDev->context;
  return ggml_backend_vk_init(vCtx->device);
}

static bool fGgmlBackendVkDeviceSupportsOp(ggml_backend_dev_t pDev, const ggml_tensor *pOp) {
  ggml_backend_vk_device_context *vCtx = (ggml_backend_vk_device_context *)pDev->context;
  const vk_device &vDevice = fGgmlVkGetDevice(vCtx->device);

  const bool cUsesBda = (pOp->op == GGML_OP_IM2COL || pOp->op == GGML_OP_IM2COL_3D) && vDevice->vShaderInt64 &&
                        vDevice->vBufferDeviceAddress;

  auto const &fTensorSizeSupported = [&](size_t pTensorSize) {
    if (pTensorSize > vDevice->vMaxBufferSize) {
      return false;
    }
    // For im2col shaders using BDA, maxStorageBufferRange limit doesn't apply.
    // If shader64BitIndexing is enabled, maxStorageBufferRange limit doesn't apply.
    if (!cUsesBda && !vDevice->vShader64bIndexing) {
      if (pTensorSize > vDevice->properties.limits.maxStorageBufferRange) {
        return false;
      }
    }
    return true;
  };
  // reject any tensors larger than the max buffer size
  for (int vI = 0; vI < GGML_MAX_SRC; vI++) {
    if (pOp->src[vI] && !fTensorSizeSupported(ggml_nbytes(pOp->src[vI]))) {
      return false;
    }
  }
  if (!fTensorSizeSupported(ggml_nbytes(pOp))) {
    return false;
  }

  switch (pOp->op) {
  case GGML_OP_UNARY:
    switch (ggml_get_unary_op(pOp)) {
    case GGML_UNARY_OP_EXP:
    case GGML_UNARY_OP_EXPM1:
    case GGML_UNARY_OP_ELU:
    case GGML_UNARY_OP_GELU:
    case GGML_UNARY_OP_GELU_ERF:
    case GGML_UNARY_OP_GELU_QUICK:
    case GGML_UNARY_OP_SILU:
    case GGML_UNARY_OP_RELU:
    case GGML_UNARY_OP_XIELU:
    case GGML_UNARY_OP_NEG:
    case GGML_UNARY_OP_TANH:
    case GGML_UNARY_OP_SIGMOID:
    case GGML_UNARY_OP_HARDSIGMOID:
    case GGML_UNARY_OP_HARDSWISH:
    case GGML_UNARY_OP_ABS:
    case GGML_UNARY_OP_SOFTPLUS:
    case GGML_UNARY_OP_STEP:
    case GGML_UNARY_OP_ROUND:
    case GGML_UNARY_OP_CEIL:
    case GGML_UNARY_OP_FLOOR:
    case GGML_UNARY_OP_TRUNC:
    case GGML_UNARY_OP_SGN:
      return (pOp->src[0]->type == GGML_TYPE_F32 || pOp->src[0]->type == GGML_TYPE_F16) &&
             (pOp->type == GGML_TYPE_F32 || pOp->type == GGML_TYPE_F16) && (pOp->src[0]->type == pOp->type);
    default:
      return false;
    }
  case GGML_OP_GLU:
    switch (ggml_get_glu_op(pOp)) {
    case GGML_GLU_OP_GEGLU:
    case GGML_GLU_OP_REGLU:
    case GGML_GLU_OP_SWIGLU:
    case GGML_GLU_OP_SWIGLU_OAI:
    case GGML_GLU_OP_GEGLU_ERF:
    case GGML_GLU_OP_GEGLU_QUICK:
    case GGML_GLU_OP_SWIGLU_CLAMP:
      return (pOp->src[0]->type == GGML_TYPE_F32 || pOp->src[0]->type == GGML_TYPE_F16) &&
             (pOp->type == GGML_TYPE_F32 || pOp->type == GGML_TYPE_F16) && (pOp->src[0]->type == pOp->type) &&
             (!pOp->src[1] || pOp->src[1]->type == pOp->src[0]->type);
    default:
      return false;
    }
  case GGML_OP_MUL_MAT:
  case GGML_OP_MUL_MAT_ID: {
    ggml_type vSrc0Type = pOp->src[0]->type;
    if (pOp->op == GGML_OP_MUL_MAT_ID) {
      if (!vDevice->mul_mat_id_s[vSrc0Type] && !vDevice->mul_mat_id_m[vSrc0Type] && !vDevice->mul_mat_id_l[vSrc0Type]) {
        // If there's not enough shared memory for row_ids and the result tile, fallback to CPU
        return false;
      }
    }
    switch (vSrc0Type) {
    case GGML_TYPE_F32:
    case GGML_TYPE_F16:
    case GGML_TYPE_BF16:
    case GGML_TYPE_Q1_0:
    case GGML_TYPE_Q2_0:
    case GGML_TYPE_Q4_0:
    case GGML_TYPE_Q4_1:
    case GGML_TYPE_Q5_0:
    case GGML_TYPE_Q5_1:
    case GGML_TYPE_Q8_0:
    case GGML_TYPE_Q2_K:
    case GGML_TYPE_Q3_K:
    case GGML_TYPE_Q4_K:
    case GGML_TYPE_Q5_K:
    case GGML_TYPE_Q6_K:
    case GGML_TYPE_IQ1_S:
    case GGML_TYPE_IQ1_M:
    case GGML_TYPE_IQ2_XXS:
    case GGML_TYPE_IQ2_XS:
    case GGML_TYPE_IQ2_S:
    case GGML_TYPE_IQ3_XXS:
    case GGML_TYPE_IQ3_S:
    case GGML_TYPE_IQ4_XS:
    case GGML_TYPE_IQ4_NL:
    case GGML_TYPE_MXFP4:
    case GGML_TYPE_NVFP4:
      break;
    default:
      return false;
    }
    struct ggml_tensor *vA;
    struct ggml_tensor *vB;
    if (pOp->op == GGML_OP_MUL_MAT) {
      vA = pOp->src[0];
      vB = pOp->src[1];
    } else {
      vA = pOp->src[2];
      vB = pOp->src[1];
    }
    if (vA->ne[3] != vB->ne[3]) {
      return false;
    }
    if (!(fGgmlVkDim01Contiguous(pOp->src[0]) || pOp->src[0]->type == GGML_TYPE_F32 ||
          pOp->src[0]->type == GGML_TYPE_F16 || pOp->src[0]->type == GGML_TYPE_BF16) ||
        !(fGgmlVkDim01Contiguous(pOp->src[1]) || pOp->src[1]->type == GGML_TYPE_F32 ||
          pOp->src[1]->type == GGML_TYPE_F16)) {
      return false;
    }
    if (pOp->src[0]->type == GGML_TYPE_BF16 && pOp->src[1]->type == GGML_TYPE_F16) {
      // We currently don't have a bf16 x f16 shader, or an fp16->bf16 copy shader.
      // So don't support this combination for now.
      return false;
    }

    return true;
  }
  case GGML_OP_FLASH_ATTN_EXT: {
    bool vCoopmat2 = vDevice->vCoopmat2;
    uint32_t vHsk = pOp->src[1]->ne[0];
    uint32_t vHsv = pOp->src[2]->ne[0];
    if ((vHsk % 8) != 0 || (vHsv % 8) != 0) {
      return false;
    }
    if (pOp->src[4] && pOp->src[4]->type != GGML_TYPE_F32) {
      return false;
    }
    if (pOp->src[0]->type != GGML_TYPE_F32) {
      return false;
    }
    if (pOp->type != GGML_TYPE_F32) {
      return false;
    }
    if (pOp->src[3] && pOp->src[3]->type != GGML_TYPE_F16) {
      return false;
    }
    auto fFaKvOk = [](ggml_type pT) {
      switch (pT) {
      case GGML_TYPE_F32:
      case GGML_TYPE_F16:
      case GGML_TYPE_BF16:
      case GGML_TYPE_Q8_0:
      case GGML_TYPE_Q5_1:
      case GGML_TYPE_Q5_0:
      case GGML_TYPE_Q4_1:
      case GGML_TYPE_Q4_0:
      case GGML_TYPE_IQ4_NL:
        return true;
      default:
        return false;
      }
    };
    if (!fFaKvOk(pOp->src[1]->type) || !fFaKvOk(pOp->src[2]->type)) {
      return false;
    }
    if ((pOp->src[1]->type == GGML_TYPE_BF16) != (pOp->src[2]->type == GGML_TYPE_BF16)) {
      return false;
    }
    if (!vCoopmat2 && !(vDevice->vSubgroupShuffle && vDevice->vSubgroupVote)) {
      // scalar/coopmat1 FA uses subgroupShuffle/subgroupAll
      return false;
    }
    return true;
  }
  case GGML_OP_GET_ROWS: {
    switch (pOp->src[0]->type) {
    case GGML_TYPE_F32:
    case GGML_TYPE_F16:
    case GGML_TYPE_BF16:
    case GGML_TYPE_Q1_0:
    case GGML_TYPE_Q2_0:
    case GGML_TYPE_Q4_0:
    case GGML_TYPE_Q4_1:
    case GGML_TYPE_Q5_0:
    case GGML_TYPE_Q5_1:
    case GGML_TYPE_Q8_0:
    case GGML_TYPE_Q2_K:
    case GGML_TYPE_Q3_K:
    case GGML_TYPE_Q4_K:
    case GGML_TYPE_Q5_K:
    case GGML_TYPE_Q6_K:
    case GGML_TYPE_IQ1_S:
    case GGML_TYPE_IQ1_M:
    case GGML_TYPE_IQ2_XXS:
    case GGML_TYPE_IQ2_XS:
    case GGML_TYPE_IQ2_S:
    case GGML_TYPE_IQ3_XXS:
    case GGML_TYPE_IQ3_S:
    case GGML_TYPE_IQ4_XS:
    case GGML_TYPE_IQ4_NL:
    case GGML_TYPE_MXFP4:
    case GGML_TYPE_NVFP4:
    case GGML_TYPE_I32:
      return true;
    default:
      return false;
    }
  }
  case GGML_OP_GET_ROWS_BACK:
    return pOp->type == GGML_TYPE_F32 && pOp->src[0]->type == GGML_TYPE_F32;
  case GGML_OP_SET_ROWS: {
    if ((pOp->src[0]->type != GGML_TYPE_F32 && pOp->src[0]->type != GGML_TYPE_F16) ||
        (pOp->src[1]->type != GGML_TYPE_I32 && pOp->src[1]->type != GGML_TYPE_I64)) {
      return false;
    }
    switch (pOp->type) {
    case GGML_TYPE_F32:
    case GGML_TYPE_F16:
    case GGML_TYPE_BF16:
    case GGML_TYPE_Q1_0:
    case GGML_TYPE_Q2_0:
    case GGML_TYPE_Q4_0:
    case GGML_TYPE_Q4_1:
    case GGML_TYPE_Q5_0:
    case GGML_TYPE_Q5_1:
    case GGML_TYPE_Q8_0:
    case GGML_TYPE_IQ4_NL:
      return true;
    default:
      return false;
    }
  }
  case GGML_OP_CONT:
  case GGML_OP_CPY:
  case GGML_OP_DUP: {
    ggml_type vSrc0Type = pOp->src[0]->type;
    ggml_type vSrc1Type = pOp->src[1] != nullptr ? pOp->src[1]->type : vSrc0Type;

    if (vSrc0Type == GGML_TYPE_F32) {
      switch (vSrc1Type) {
      case GGML_TYPE_F32:
      case GGML_TYPE_F16:
      case GGML_TYPE_BF16:
      case GGML_TYPE_Q1_0:
      case GGML_TYPE_Q2_0:
      case GGML_TYPE_Q4_0:
      case GGML_TYPE_Q4_1:
      case GGML_TYPE_Q5_0:
      case GGML_TYPE_Q5_1:
      case GGML_TYPE_Q8_0:
      case GGML_TYPE_IQ4_NL:
        return true;
      default:
        break;
      }
    }
    if (vSrc1Type == GGML_TYPE_F32) {
      switch (vSrc0Type) {
      case GGML_TYPE_F16:
      case GGML_TYPE_BF16:
      case GGML_TYPE_Q1_0:
      case GGML_TYPE_Q2_0:
      case GGML_TYPE_Q4_0:
      case GGML_TYPE_Q4_1:
      case GGML_TYPE_Q5_0:
      case GGML_TYPE_Q5_1:
      case GGML_TYPE_Q8_0:
      case GGML_TYPE_IQ4_NL:
        return true;
      default:
        break;
      }
    }

    if (vSrc0Type == GGML_TYPE_F16 && vSrc1Type == GGML_TYPE_F16) {
      return true;
    }

    if ((vSrc0Type == GGML_TYPE_F32 && vSrc1Type == GGML_TYPE_I32) ||
        (vSrc0Type == GGML_TYPE_I32 && vSrc1Type == GGML_TYPE_F32)) {
      return true;
    }

    // We can handle copying from a type to the same type if it's
    // either not quantized or is quantized and contiguous.
    // We use f16 or f32 shaders to do the copy,
    // so the type/block size must be a multiple of 4.
    if (vSrc0Type == vSrc1Type &&
        (!ggml_is_quantized(vSrc0Type) || (ggml_is_contiguous(pOp->src[0]) && ggml_is_contiguous(pOp))) &&
        (ggml_type_size(vSrc0Type) % 2) == 0) {
      return true;
    }
    return false;
  }
  case GGML_OP_REPEAT:
    return ggml_type_size(pOp->type) == ggml_type_size(pOp->src[0]->type) &&
           (ggml_type_size(pOp->type) == sizeof(float) || ggml_type_size(pOp->type) == 2);
  case GGML_OP_REPEAT_BACK:
    return pOp->type == GGML_TYPE_F32 && pOp->src[0]->type == GGML_TYPE_F32;
  case GGML_OP_ROPE:
    return ggml_is_contiguous_rows(pOp) && ggml_is_contiguous_rows(pOp->src[0]);
  case GGML_OP_ROPE_BACK:
  case GGML_OP_NONE:
  case GGML_OP_RESHAPE:
  case GGML_OP_VIEW:
  case GGML_OP_PERMUTE:
  case GGML_OP_TRANSPOSE:
  case GGML_OP_RMS_NORM:
    return true;
  case GGML_OP_GROUP_NORM:
    return ggml_is_contiguous(pOp->src[0]);
  case GGML_OP_NORM:
  case GGML_OP_L2_NORM:
    return pOp->src[0]->type == GGML_TYPE_F32 && pOp->type == GGML_TYPE_F32;
  case GGML_OP_ADD:
  case GGML_OP_SUB:
  case GGML_OP_MUL:
  case GGML_OP_DIV:
    return (pOp->src[0]->type == GGML_TYPE_F32 || pOp->src[0]->type == GGML_TYPE_F16) &&
           (pOp->src[1]->type == GGML_TYPE_F32 || pOp->src[1]->type == GGML_TYPE_F16) &&
           (pOp->type == GGML_TYPE_F32 || pOp->type == GGML_TYPE_F16);
  case GGML_OP_ADD_ID:
    return pOp->src[0]->type == GGML_TYPE_F32 && pOp->src[1]->type == GGML_TYPE_F32 &&
           pOp->src[2]->type == GGML_TYPE_I32 && pOp->type == GGML_TYPE_F32;
  case GGML_OP_SILU_BACK:
  case GGML_OP_RMS_NORM_BACK:
    return ggml_is_contiguous(pOp->src[0]) && pOp->src[0]->type == GGML_TYPE_F32;
  case GGML_OP_SQR:
  case GGML_OP_SQRT:
  case GGML_OP_SIN:
  case GGML_OP_COS:
  case GGML_OP_CLAMP:
  case GGML_OP_LEAKY_RELU:
    return (pOp->src[0]->type == GGML_TYPE_F32 || pOp->src[0]->type == GGML_TYPE_F16) && pOp->type == pOp->src[0]->type;
  case GGML_OP_OPT_STEP_ADAMW:
  case GGML_OP_OPT_STEP_SGD:
    return ggml_is_contiguous(pOp->src[0]) && pOp->src[0]->type == GGML_TYPE_F32;
  case GGML_OP_OUT_PROD:
    return ggml_is_contiguous(pOp->src[0]) && pOp->src[0]->type == GGML_TYPE_F32 && ggml_is_contiguous(pOp->src[1]) &&
           pOp->src[1]->type == GGML_TYPE_F32 && pOp->type == GGML_TYPE_F32;
  case GGML_OP_LOG:
  case GGML_OP_TRI:
  case GGML_OP_DIAG:
    return (pOp->src[0]->type == GGML_TYPE_F32 || pOp->src[0]->type == GGML_TYPE_F16) && pOp->type == pOp->src[0]->type;
  case GGML_OP_ARGSORT: {
    if (!ggml_is_contiguous(pOp) || !ggml_is_contiguous(pOp->src[0])) {
      return false;
    }
    // pipeline_argsort_large_f32 requires vulkan memory model.
    if (vDevice->vVulkanMemoryModel) {
      return true;
    } else {
      return pOp->ne[0] <= (1 << vDevice->vMaxWorkgroupSizeLog2);
    }
  }
  case GGML_OP_TOP_K: {
    if (!ggml_is_contiguous(pOp) || !ggml_is_contiguous(pOp->src[0])) {
      return false;
    }
    // We could potentially support larger, using argsort to sort the
    // whole thing. Not clear if this is needed.
    uint32_t vMinPipeline = (uint32_t)log2f(float(pOp->ne[0])) + 1;
    if (vMinPipeline >= num_topk_pipelines || !vDevice->vPipelineTopkF32[vMinPipeline]) {
      return false;
    }
  }
    return true;
  case GGML_OP_UPSCALE:
    if (pOp->op_params[0] & GGML_SCALE_FLAG_ANTIALIAS) {
      if ((pOp->op_params[0] & 0xFF) != GGML_SCALE_MODE_BILINEAR) {
        return false;
      }
    }
    return pOp->src[0]->type == GGML_TYPE_F32;
  case GGML_OP_ACC:
    return pOp->src[0]->type == GGML_TYPE_F32 && pOp->src[1]->type == GGML_TYPE_F32 && pOp->type == GGML_TYPE_F32;
  case GGML_OP_SET:
    return pOp->src[0]->type == pOp->src[1]->type && pOp->src[0]->type == pOp->type &&
           (pOp->src[0]->type == GGML_TYPE_F32 || pOp->src[0]->type == GGML_TYPE_I32);
  case GGML_OP_CONCAT: {
    return fGgmlVkConcatSupported(pOp->src[0], pOp->src[1], pOp);
  }
  case GGML_OP_ADD1:
    return (pOp->src[0]->type == GGML_TYPE_F32 && pOp->src[1]->type == GGML_TYPE_F32) ||
           (pOp->src[0]->type == GGML_TYPE_F16 && pOp->src[1]->type == GGML_TYPE_F32) ||
           (pOp->src[0]->type == GGML_TYPE_F16 && pOp->src[1]->type == GGML_TYPE_F16);
  case GGML_OP_ARANGE:
    return pOp->type == GGML_TYPE_F32;
  case GGML_OP_FILL:
    return pOp->type == GGML_TYPE_F32 || pOp->type == GGML_TYPE_F16;
  case GGML_OP_SCALE:
    return ggml_is_contiguous(pOp->src[0]) && pOp->src[0]->type == GGML_TYPE_F32;
  case GGML_OP_PAD:
  case GGML_OP_ROLL:
    return pOp->src[0]->type == GGML_TYPE_F32;
  case GGML_OP_DIAG_MASK_INF:
    return ggml_is_contiguous(pOp->src[0]) && pOp->src[0]->type == GGML_TYPE_F32;
  case GGML_OP_SOFT_MAX:
    return ggml_is_contiguous(pOp->src[0]) && pOp->src[0]->type == GGML_TYPE_F32 &&
           (!pOp->src[1] || (pOp->src[1]->type == GGML_TYPE_F32 || pOp->src[1]->type == GGML_TYPE_F16));
  case GGML_OP_SOFT_MAX_BACK:
    return ggml_is_contiguous(pOp->src[0]) && pOp->src[0]->type == GGML_TYPE_F32 && ggml_is_contiguous(pOp->src[1]) &&
           pOp->src[1]->type == GGML_TYPE_F32;
  case GGML_OP_SUM:
  case GGML_OP_SUM_ROWS:
  case GGML_OP_MEAN:
    return pOp->src[0]->type == GGML_TYPE_F32 && ggml_is_contiguous_rows(pOp->src[0]);
  case GGML_OP_CUMSUM: {
    if (vDevice->vSubgroupArithmetic && vDevice->vSubgroupRequireFullSupport) {
      return pOp->src[0]->type == GGML_TYPE_F32 && ggml_is_contiguous_rows(pOp->src[0]);
    }
    return false;
  }
  case GGML_OP_SOLVE_TRI: {
    if (pOp->type != GGML_TYPE_F32 || pOp->src[0]->type != GGML_TYPE_F32) {
      return false;
    }
    const uint32_t cN = pOp->src[0]->ne[0];
    const uint32_t cK = pOp->src[1]->ne[0];
    // K dimension limited to workgroup size
    if (cK > 1u << vDevice->vMaxWorkgroupSizeLog2) {
      return false;
    }
    const uint32_t cBatchN = vDevice->properties.limits.maxComputeSharedMemorySize / ((cN + cK) * sizeof(float));

    if (cBatchN == 0) {
      return false;
    }
    return true;
  }
  case GGML_OP_ARGMAX:
    return ggml_is_contiguous(pOp->src[0]) && pOp->src[0]->type == GGML_TYPE_F32;
  case GGML_OP_AMAX_POW2:
    return ggml_is_contiguous(pOp->src[0]) && pOp->src[0]->type == GGML_TYPE_F32;
  case GGML_OP_COUNT_EQUAL:
    return ggml_is_contiguous(pOp->src[0]) && pOp->src[0]->type == GGML_TYPE_I32 && ggml_is_contiguous(pOp->src[1]) &&
           pOp->src[1]->type == GGML_TYPE_I32;
  case GGML_OP_IM2COL:
    return ggml_is_contiguous(pOp->src[1]) && pOp->src[1]->type == GGML_TYPE_F32 &&
           (pOp->type == GGML_TYPE_F32 || pOp->type == GGML_TYPE_F16);
  case GGML_OP_IM2COL_3D:
    return pOp->src[1]->type == GGML_TYPE_F32 && (pOp->type == GGML_TYPE_F32 || pOp->type == GGML_TYPE_F16);
  case GGML_OP_TIMESTEP_EMBEDDING:
    return pOp->src[0]->type == GGML_TYPE_F32;
  case GGML_OP_CONV_2D_DW:
    return (pOp->src[0]->type == GGML_TYPE_F32 || pOp->src[0]->type == GGML_TYPE_F16) &&
           pOp->src[1]->type == GGML_TYPE_F32;
  case GGML_OP_POOL_1D:
    return ggml_is_contiguous(pOp->src[0]) && pOp->src[0]->type == GGML_TYPE_F32;
  case GGML_OP_POOL_2D:
    return ggml_is_contiguous(pOp->src[0]) && pOp->src[0]->type == GGML_TYPE_F32;
  case GGML_OP_RWKV_WKV6:
  case GGML_OP_RWKV_WKV7:
    return true; // all inputs are contiguous, see ggml.c
  case GGML_OP_GATED_LINEAR_ATTN:
    // the shader block size is hardcoded to head_size 64
    return pOp->src[0]->type == GGML_TYPE_F32 && pOp->type == GGML_TYPE_F32 && pOp->src[0]->ne[0] == 64;
  case GGML_OP_DSV4_HC_COMB:
  case GGML_OP_DSV4_HC_PRE:
  case GGML_OP_DSV4_HC_POST: {
    if (pOp->type != GGML_TYPE_F32) {
      return false;
    }
    for (uint32_t vI = 0; vI < GGML_MAX_SRC; ++vI) {
      if (pOp->src[vI] && pOp->src[vI]->type != GGML_TYPE_F32) {
        return false;
      }
    }
    // the shaders hardcode hc = 4; ggml only constrains it to 4 for COMB, so PRE and POST are checked here
    if (pOp->op == GGML_OP_DSV4_HC_PRE && pOp->src[0]->ne[1] != 4) {
      return false;
    }
    if (pOp->op == GGML_OP_DSV4_HC_POST && pOp->src[1]->ne[1] != 4) {
      return false;
    }
    if (pOp->op == GGML_OP_DSV4_HC_COMB) {
      return vDevice->vPipelineDsv4HcCombF32 != nullptr;
    }
    return true;
  }
  case GGML_OP_LIGHTNING_INDEXER: {
    const ggml_tensor *vQ = pOp->src[0];
    const ggml_tensor *vK = pOp->src[1];
    const ggml_tensor *vW = pOp->src[2];
    const ggml_tensor *vM = pOp->src[3];

    // ggml_lightning_indexer() already asserts the q, w and m types and the shapes of q, k, w, m and dst
    if (!fGgmlVkLightningIndexerKTypeSupported(vK->type) || !vDevice->vFp16) {
      return false;
    }

    // the shader hardcodes a head size of 128
    if (vQ->ne[0] != 128) {
      return false;
    }

    // the shader indexes the buffers by element stride and is dispatched without allow_misalign
    for (const ggml_tensor *vT : {vQ, vK, vW, vM, pOp}) {
      if (vT->nb[0] != ggml_type_size(vT->type) ||
          (fVkTensorOffset(vT) + vT->view_offs) % vDevice->properties.limits.minStorageBufferOffsetAlignment != 0) {
        return false;
      }
      // the strides are scaled down from bytes, so the division must be exact
      for (int vD = 1; vD < GGML_MAX_DIMS; ++vD) {
        if (vT->nb[vD] % ggml_type_size(vT->type) != 0) {
          return false;
        }
      }
    }
    return true;
  }
  case GGML_OP_GATED_DELTA_NET: {
    const uint32_t cSV = pOp->src[2]->ne[0];
    if (cSV != 16 && cSV != 32 && cSV != 64 && cSV != 128) {
      return false;
    }
    for (int vI = 0; vI < 6; vI++) {
      if (pOp->src[vI] == nullptr || pOp->src[vI]->type != GGML_TYPE_F32) {
        return false;
      }
    }
    return pOp->type == GGML_TYPE_F32;
  }
  case GGML_OP_SSM_SCAN: {
    for (int vI = 0; vI < 6; vI++) {
      if (pOp->src[vI] && ggml_is_quantized(pOp->src[vI]->type)) {
        return false;
      }
    }
    if (pOp->src[6] && pOp->src[6]->type != GGML_TYPE_I32) {
      return false;
    }
    if (pOp->src[0]->type != GGML_TYPE_F32 || pOp->type != GGML_TYPE_F32) {
      return false;
    }

    const uint32_t cDState = pOp->src[0]->ne[0];
    const uint32_t cHeadDim = pOp->src[0]->ne[1];

    bool vIsMamba2 = (pOp->src[3] && pOp->src[3]->nb[1] == sizeof(float));
    if (!vIsMamba2) {
      return false;
    }

    if ((cDState != 128 && cDState != 256) || cHeadDim % 16 != 0) {
      return false;
    }

    size_t vShmemSize = cDState * sizeof(float);

    if (vShmemSize > vDevice->properties.limits.maxComputeSharedMemorySize) {
      return false;
    }

    if (!vDevice->vSubgroupBasic) {
      return false;
    }

    return true;
  }
  case GGML_OP_SSM_CONV:
    return pOp->src[0]->type == GGML_TYPE_F32;
  case GGML_OP_CONV_TRANSPOSE_1D:
    return pOp->src[0]->type == GGML_TYPE_F32 && pOp->src[1]->type == GGML_TYPE_F32;
  case GGML_OP_COL2IM_1D:
    return (pOp->src[0]->type == GGML_TYPE_F32 || pOp->src[0]->type == GGML_TYPE_F16 ||
            pOp->src[0]->type == GGML_TYPE_BF16) &&
           pOp->type == pOp->src[0]->type && ggml_is_contiguous(pOp->src[0]) && ggml_is_contiguous(pOp);
  case GGML_OP_CONV_2D:
  case GGML_OP_CONV_TRANSPOSE_2D: {
    const bool cTranspose = pOp->op == GGML_OP_CONV_TRANSPOSE_2D;
    const int64_t cCout = !cTranspose ? pOp->src[0]->ne[3] : pOp->src[0]->ne[2];
    const int64_t cCin = !cTranspose ? pOp->src[0]->ne[2] : pOp->src[0]->ne[3];

    // Channel-contiguous format is not supported yet.
    return ((pOp->src[0]->type == GGML_TYPE_F32 || pOp->src[0]->type == GGML_TYPE_F16) &&
            (pOp->src[0]->nb[0] == sizeof(float) || pOp->src[0]->nb[0] == sizeof(ggml_fp16_t)) &&
            pOp->src[1]->type == GGML_TYPE_F32 && pOp->type == GGML_TYPE_F32 && cCout == pOp->ne[2] &&
            cCin == pOp->src[1]->ne[2] && ggml_is_contiguous(pOp->src[0]) && ggml_is_contiguous(pOp->src[1]) &&
            ggml_is_contiguous(pOp));
  }
  case GGML_OP_CONV_3D:
    return (pOp->src[0]->type == GGML_TYPE_F32 || pOp->src[0]->type == GGML_TYPE_F16) &&
           pOp->src[1]->type == GGML_TYPE_F32 && pOp->type == GGML_TYPE_F32 && ggml_is_contiguous(pOp->src[0]) &&
           ggml_is_contiguous(pOp->src[1]) && ggml_is_contiguous(pOp);
  default:
    return false;
  }

  UNUSED(pDev);
}

static bool fGgmlBackendVkDeviceSupportsBuft(ggml_backend_dev_t pDev, ggml_backend_buffer_type_t pBuft) {
  if (pBuft->iface.get_name != fGgmlBackendVkBufferTypeName) {
    return false;
  }

  ggml_backend_vk_device_context *vCtx = (ggml_backend_vk_device_context *)pDev->context;
  ggml_backend_vk_buffer_type_context *vBuftCtx = (ggml_backend_vk_buffer_type_context *)pBuft->context;

  return vBuftCtx->device->idx == vCtx->device;
}

static int64_t fGgmlVkGetOpBatchSize(const ggml_tensor *pOp) {
  switch (pOp->op) {
  case GGML_OP_GET_ROWS:
    return 0;
  case GGML_OP_MUL_MAT:
    return pOp->ne[1];
  case GGML_OP_MUL_MAT_ID:
  case GGML_OP_ROPE:
  case GGML_OP_ROPE_BACK:
    return pOp->ne[2];
  default:
    return ggml_nrows(pOp);
  }
}

static bool fGgmlBackendVkDeviceOffloadOp(ggml_backend_dev_t pDev, const ggml_tensor *pOp) {
  ggml_backend_vk_device_context *vDevCtx = (ggml_backend_vk_device_context *)pDev->context;

  return fGgmlVkGetOpBatchSize(pOp) >= vDevCtx->vOpOffloadMinBatchSize;
}

static ggml_backend_event_t fGgmlBackendVkDeviceEventNew(ggml_backend_dev_t pDev) {
  ggml_backend_vk_device_context *vCtx = (ggml_backend_vk_device_context *)pDev->context;
  auto vDevice = fGgmlVkGetDevice(vCtx->device);

  vk_event *vVkev = new vk_event;
  if (!vVkev) {
    return nullptr;
  }

  // No events initially, they get created on demand
  vVkev->vHasEvent = false;

  vk::SemaphoreTypeCreateInfo vTci{vk::SemaphoreType::eTimeline, 0};
  vk::SemaphoreCreateInfo vCi{};
  vCi.setPNext(&vTci);
  vVkev->vTlSemaphore = {vDevice->device.createSemaphore(vCi), 0};

  return new ggml_backend_event{
      /* .device  = */ pDev,
      /* .context = */ vVkev,
  };
}

static void fGgmlBackendVkDeviceEventFree(ggml_backend_dev_t pDev, ggml_backend_event_t pEvent) {
  ggml_backend_vk_device_context *vCtx = (ggml_backend_vk_device_context *)pDev->context;
  auto vDevice = fGgmlVkGetDevice(vCtx->device);

  vk_event *vVkev = (vk_event *)pEvent->context;

  vDevice->device.destroySemaphore(vVkev->vTlSemaphore.s);
  for (auto &vEvent : vVkev->lEventsFree) {
    vDevice->device.destroyEvent(vEvent);
  }
  for (auto &vEvent : vVkev->lEventsSubmitted) {
    vDevice->device.destroyEvent(vEvent);
  }
  if (vVkev->vHasEvent) {
    vDevice->device.destroyEvent(vVkev->event);
  }
  delete vVkev;
  delete pEvent;
}

static void fGgmlBackendVkDeviceEventSynchronize(ggml_backend_dev_t pDev, ggml_backend_event_t event) {
  VK_LOG_DEBUG("ggml_backend_vk_device_event_synchronize(backend=" << pDev << ", event=" << event << ")");
  ggml_backend_vk_device_context *vCtx = (ggml_backend_vk_device_context *)pDev->context;
  auto vDevice = fGgmlVkGetDevice(vCtx->device);
  vk_event *vVkev = (vk_event *)event->context;

  // Only do something if the event has actually been used
  if (vVkev->vHasEvent) {
    vk::Semaphore vSem = vVkev->vTlSemaphore.s;
    uint64_t vVal = vVkev->vTlSemaphore.value;
    vk::SemaphoreWaitInfo vSwi{vk::SemaphoreWaitFlags{}, vSem, vVal};
    VK_CHECK(vDevice->device.waitSemaphores(vSwi, UINT64_MAX), "event_synchronize");

    // Reset and move submitted events
    for (auto &event : vVkev->lEventsSubmitted) {
      vDevice->device.resetEvent(event);
    }
    vVkev->lEventsFree.insert(vVkev->lEventsFree.end(), vVkev->lEventsSubmitted.begin(), vVkev->lEventsSubmitted.end());
    vVkev->lEventsSubmitted.clear();

    // Finished using current command buffer so we flag for reuse
    if (vVkev->vCmdBuffer) {
      // Only flag for reuse if it hasn't been reused already
      if (vVkev->vCmdBufferUseCounter == vVkev->vCmdBuffer->vUseCounter) {
        vVkev->vCmdBuffer->in_use = false;
        vVkev->vCmdBuffer->vBuf.reset();
      }
      vVkev->vCmdBuffer = nullptr;
    }
  }
}

static vk_buffer fGgmlVkBufferFromHostPtr(vk_device &pDevice, void *pPtr, size_t pSize) {
  if (!pDevice->vExternalMemoryHost) {
    return {};
  }

  uintptr_t vUptr = reinterpret_cast<uintptr_t>(pPtr);
  if (vUptr & (pDevice->vMinImportedHostPointerAlignment - 1)) {
    return {};
  }
  if (pSize & (pDevice->vMinImportedHostPointerAlignment - 1)) {
    return {};
  }

  const vk::MemoryPropertyFlags cPropertyFlags = vk::MemoryPropertyFlagBits::eHostVisible |
                                                 vk::MemoryPropertyFlagBits::eHostCoherent |
                                                 vk::MemoryPropertyFlagBits::eHostCached;

  vk_buffer vBuf{};
  try {
    vBuf = fGgmlVkCreateBuffer(pDevice, pSize, {cPropertyFlags}, pPtr);
  } catch (vk::SystemError &vE) {
    GGML_LOG_WARN("ggml_vulkan: Failed ggml_vk_create_buffer (%s)\n", vE.what());
  }

  return vBuf;
}

static ggml_backend_buffer_t fGgmlBackendVkDeviceBufferFromHostPtr(ggml_backend_dev_t pDev, void *ptr, size_t size,
                                                                   size_t pMaxTensorSize) {
  VK_LOG_DEBUG("ggml_backend_vk_device_buffer_from_host_ptr(backend=" << pDev << ", ptr=" << ptr << ", size=" << size
                                                                      << ")");
  GGML_UNUSED(pMaxTensorSize);

  ggml_backend_vk_device_context *vCtx = (ggml_backend_vk_device_context *)pDev->context;
  auto vDevice = fGgmlVkGetDevice(vCtx->device);

  vk_buffer vBuf = fGgmlVkBufferFromHostPtr(vDevice, ptr, size);

  if (!vBuf) {
    return {};
  }

  ggml_backend_vk_buffer_context *vBufctx = new ggml_backend_vk_buffer_context(vDevice, std::move(vBuf), vDevice->name);

  ggml_backend_buffer_t vRet = ggml_backend_buffer_init(fGgmlBackendVkDeviceGetBufferType(pDev),
                                                        ggml_backend_vk_buffer_interface, vBufctx, size);

  return vRet;
}

