static ggml_backend_dev_t fGgmlBackendVkRegGetDevice(ggml_backend_reg_t pReg, size_t pDevice) {
  static std::vector<ggml_backend_dev_t> vDevices;

  static bool vInitialized = false;

  {
    static std::mutex vMutex;
    std::lock_guard<std::mutex> vLock(vMutex);
    if (!vInitialized) {
      const int cMinBatchSize = getenv("GGML_OP_OFFLOAD_MIN_BATCH") ? atoi(getenv("GGML_OP_OFFLOAD_MIN_BATCH")) : 32;
      for (int vI = 0; vI < ggml_backend_vk_get_device_count(); vI++) {
        ggml_backend_vk_device_context *vCtx = new ggml_backend_vk_device_context;
        char aDesc[256];
        ggml_backend_vk_get_device_description(vI, aDesc, sizeof(aDesc));
        vCtx->device = vI;
        vCtx->name = GGML_VK_NAME + std::to_string(vI);
        vCtx->vDescription = aDesc;
        vCtx->vIsIntegratedGpu = fGgmlBackendVkGetDeviceType(vI) == vk::PhysicalDeviceType::eIntegratedGpu;
        vCtx->vPciBusId = fGgmlBackendVkGetDevicePciId(vI);
        vCtx->vOpOffloadMinBatchSize = cMinBatchSize;
        vDevices.push_back(new ggml_backend_device{
            /* .iface   = */ ggml_backend_vk_device_i,
            /* .reg     = */ pReg,
            /* .context = */ vCtx,
        });
      }
      vInitialized = true;
    }
  }

  GGML_ASSERT(pDevice < vDevices.size());
  return vDevices[pDevice];
}

// Lower eviction priority device memory for caches, exported as "ggml_backend_dev_get_cache_buffer_type".
static ggml_backend_buffer_type_t fGgmlBackendVkDeviceGetCacheBufferType(ggml_backend_dev_t pDev) {
  ggml_backend_vk_device_context *vCtx = (ggml_backend_vk_device_context *)pDev->context;
  fGgmlVkInstanceInit();
  vk_device vDevice = fGgmlVkGetDevice(vCtx->device);
  return &vDevice->vCacheBufferType;
}

static void *fGgmlBackendVkRegGetProcAddress(ggml_backend_reg_t pReg, const char *pName) {
  UNUSED(pReg);
  if (strcmp(pName, "ggml_backend_dev_get_cache_buffer_type") == 0) {
    return (void *)fGgmlBackendVkDeviceGetCacheBufferType;
  }
  return nullptr;
}

